select ac_cargar_unidad($ac${"slug":"energia-1","rama":"energia","orden":1,"nivel":1,"titulo_es":"Qué es la energía","bajada_es":"La energía no se ve, pero mueve todo. Sus formas, sus transformaciones, sus fuentes y por qué pesa tanto en el clima.","objetivos_es":["Reconocer las formas de la energía en situaciones cotidianas","Explicar por qué toda transformación \"pierde\" una parte como calor","Calcular la eficiencia de un aparato o una máquina","Distinguir fuentes primarias, fuentes secundarias y vectores","Relacionar el uso de energía fósil con las emisiones de CO₂"],"repasa":["tronco-1","tronco-2"],"requiere_tronco":1,"fuentes":["iea-energia","owid-energia","owid-co2","ipcc-ar6-syr","iea-eficiencia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-1.s1","orden":1,"tipo":"leccion","titulo_es":"La energía que mueve todo","bajada_es":"Luz, calor, movimiento, electricidad: la misma cosa en distintas formas.","minutos":11,"pasos":[{"slug":"energia-1.s1.p1","orden":1,"grupo":"energia-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una definición útil","cuerpo":["La energía es la capacidad de producir un cambio: mover algo, calentarlo, iluminarlo, hacerlo crecer. No se ve directamente; se ven sus efectos.","Aparece en muchas formas: química (guardada en la comida, la nafta o el gas), eléctrica, térmica (el calor), cinética (la del movimiento), luminosa, y potencial (la que tiene el agua en lo alto de una represa, lista para caer)."]},"solucion":{}},{"slug":"energia-1.s1.p2","orden":2,"grupo":"energia-1.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ejemplo con la forma de energía que tiene.","izquierda":[{"id":"a1","texto":"Un sándwich antes de comerlo"},{"id":"a2","texto":"Una pelota que rueda"},{"id":"a3","texto":"El agua detrás de una represa"},{"id":"a4","texto":"Una pava caliente"}],"derecha":[{"id":"b1","texto":"Química"},{"id":"b2","texto":"Cinética"},{"id":"b3","texto":"Potencial"},{"id":"b4","texto":"Térmica"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro formas distintas de la misma cosa. Lo interesante es cómo pasan de una a otra."}},{"slug":"energia-1.s1.p3","orden":3,"grupo":"energia-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nada se crea, todo se transforma","cuerpo":["La energía no aparece de la nada ni desaparece: se transforma de una forma en otra. Es una de las leyes más firmes de la física. En el tronco lo viste con la cadena del sol a las plantas y de las plantas a los animales.","Cuando decimos que \"gastamos\" energía, en realidad la transformamos en formas que ya no nos sirven, casi siempre calor que se dispersa en el ambiente."]},"solucion":{}},{"slug":"energia-1.s1.p4","orden":4,"grupo":"energia-1.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Seguí la energía desde el sol hasta tu pierna cuando pedaleás.","items":[{"id":"i1","texto":"El sol emite luz"},{"id":"i2","texto":"Una planta de trigo la guarda como energía química"},{"id":"i3","texto":"Comés pan hecho con ese trigo"},{"id":"i4","texto":"Tus músculos transforman esa energía en movimiento"},{"id":"i5","texto":"La bicicleta avanza"},{"id":"i6","texto":"El pan le devuelve la luz al sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Casi toda la energía que usamos empezó siendo luz del sol, incluso la del petróleo, que es sol guardado hace millones de años."}},{"slug":"energia-1.s1.p5","orden":5,"grupo":"energia-1.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuando una lámpara se apaga, la energía que usó desaparece.","razones":[{"id":"r1","texto":"Porque se transformó en luz y calor que se dispersaron"},{"id":"r2","texto":"Porque vuelve a la red eléctrica al apagar"},{"id":"r3","texto":"Porque queda guardada en la lámpara"}]},"solucion":{"valor":false,"explicacion":"No desaparece: se transformó en luz y calor, que se dispersaron en la habitación. La energía se conserva, pero se vuelve menos útil.","clave":["r1"]}},{"slug":"energia-1.s1.p6","orden":6,"grupo":"energia-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Transformaciones de todos los días","cuerpo":["Un celular transforma energía eléctrica en química (al cargar la batería) y después en luz, sonido y calor. Un auto transforma la energía química de la nafta en movimiento y mucho calor. Una central hidroeléctrica transforma la energía potencial del agua en movimiento de una turbina y después en electricidad."]},"solucion":{}},{"slug":"energia-1.s1.p7","orden":7,"grupo":"energia-1.s1.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las transformaciones en una central hidroeléctrica.","items":[{"id":"i1","texto":"El agua está acumulada en lo alto del embalse"},{"id":"i2","texto":"El agua cae por un conducto"},{"id":"i3","texto":"Hace girar una turbina"},{"id":"i4","texto":"La turbina mueve un generador"},{"id":"i5","texto":"Sale electricidad hacia la red"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Potencial, cinética, mecánica, eléctrica. Cada paso es una transformación."}},{"slug":"energia-1.s1.p8","orden":8,"grupo":"energia-1.s1.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué transformación principal hace cada aparato?","grupos":[{"id":"g1","nombre":"Eléctrica a movimiento"},{"id":"g2","nombre":"Eléctrica a calor"},{"id":"g3","nombre":"Química a calor"}],"items":[{"id":"i1","texto":"Un ventilador"},{"id":"i2","texto":"Una pava eléctrica"},{"id":"i3","texto":"Una hornalla de gas"},{"id":"i4","texto":"Una licuadora"},{"id":"i5","texto":"Una estufa de cuarzo"},{"id":"i6","texto":"Una estufa a leña"},{"id":"i7","texto":"Un lavarropas girando"},{"id":"i8","texto":"Una plancha"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2"},"explicacion":"Casi todos los aparatos hacen una transformación principal, y además producen algo de calor que no buscamos."}},{"slug":"energia-1.s1.p9","orden":9,"grupo":"energia-1.s1.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas cosas tienen energía química guardada? Marcá todas.","opciones":[{"id":"o1","texto":"La nafta de un tanque"},{"id":"o2","texto":"Una batería cargada"},{"id":"o3","texto":"Un leño seco"},{"id":"o4","texto":"Una manzana"},{"id":"o5","texto":"Una ráfaga de viento"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La energía química está en los enlaces de las moléculas. El viento tiene energía de movimiento, no química."}},{"slug":"energia-1.s1.p10","orden":10,"grupo":"energia-1.s1.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un auto frena y los discos de freno se calientan. ¿Qué pasó con la energía del movimiento?","opciones":[{"id":"o1","texto":"Se transformó en calor por el roce"},{"id":"o2","texto":"Volvió al tanque como nafta sin quemar"},{"id":"o3","texto":"Desapareció al frenar el auto"},{"id":"o4","texto":"Se guardó en las ruedas para arrancar después"}]},"solucion":{"clave":["o1"],"explicacion":"Los autos eléctricos pueden recuperar una parte al frenar (freno regenerativo), pero en un freno común todo termina como calor.","por_opcion":{"o3":"La energía no desaparece: se transforma. Los frenos calientes son la prueba."}}},{"slug":"energia-1.s1.p11","orden":11,"grupo":"energia-1.s1.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía no se crea ni se {{0}}: se {{1}}, y casi siempre una parte termina como {{2}}.","banco":[{"id":"w1","texto":"destruye"},{"id":"w2","texto":"transforma"},{"id":"w3","texto":"calor"},{"id":"w4","texto":"acumula"},{"id":"w5","texto":"multiplica"},{"id":"w6","texto":"luz"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres palabras que explican por qué hablar de \"gastar energía\" es una forma de decir."}},{"slug":"energia-1.s1.p12","orden":12,"grupo":"energia-1.s1.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación de un estudiante y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La energía de la nafta es energía química."},{"id":"s2","texto":"Cuando el auto anda, esa energía se destruye."},{"id":"s3","texto":"Por eso el motor se calienta tanto."},{"id":"s4","texto":"Un auto eléctrico no transforma energía: la usa tal cual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Toda máquina es una transformadora de energía. La pregunta útil es cuánta sale en la forma que queremos.","por_opcion":{"s2":"No se destruye: se transforma en movimiento y, sobre todo, en calor.","s4":"También transforma: de química (batería) a eléctrica y a movimiento."}}},{"slug":"energia-1.s1.p13","orden":13,"grupo":"energia-1.s1.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas cosas por cuánta energía tienen, de más a menos (valores aproximados).","items":[{"id":"i1","texto":"Un litro de nafta"},{"id":"i2","texto":"Un día de comida de una persona adulta"},{"id":"i3","texto":"Una batería de celular cargada"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Un litro de nafta tiene casi cuatro días de comida de una persona. Por eso los combustibles fósiles fueron tan poderosos, y tan difíciles de reemplazar.","valores":{"i1":"≈ 9 kWh","i2":"≈ 2,3 kWh","i3":"≈ 0,015 kWh"}}}]},{"slug":"energia-1.s2","orden":2,"tipo":"leccion","titulo_es":"Transformar siempre cuesta","bajada_es":"Por qué ninguna máquina aprovecha toda la energía, y cómo se mide cuánto aprovecha: la eficiencia.","minutos":13,"pasos":[{"slug":"energia-1.s2.p1","orden":1,"grupo":"energia-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La parte que se escapa","cuerpo":["En cada transformación, una parte de la energía termina en una forma que no buscábamos, casi siempre calor. Una lamparita vieja, incandescente, convierte solo alrededor del 5 % de la electricidad en luz: el resto es calor. Por eso quemaba al tocarla.","La eficiencia es la fracción de la energía que sale en la forma útil. Se calcula como energía útil dividida energía que entra, y se expresa en porcentaje."],"destacado":{"valor":"útil ÷ entra","texto":"es la cuenta de la eficiencia. Multiplicada por 100, da el porcentaje."}},"solucion":{}},{"slug":"energia-1.s2.p2","orden":2,"grupo":"energia-1.s2.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"La eficiencia de un motor","planteo":"Un motor de auto recibe 100 unidades de energía de la nafta y entrega 25 como movimiento de las ruedas.","pasos":["Energía útil: 25. Energía que entra: 100.","Eficiencia: 25 ÷ 100 = 0,25, o sea 25 %.","Las otras 75 unidades salen como calor por el escape y el radiador."],"resultado":"Un motor de nafta aprovecha alrededor de un cuarto de la energía. Un motor eléctrico, en cambio, supera el 85 %."},"solucion":{}},{"slug":"energia-1.s2.p3","orden":3,"grupo":"energia-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una máquina recibe 200 unidades de energía y entrega 50 en la forma útil. ¿Cuál es su eficiencia?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"50 ÷ 200 = 0,25, que es 25 %. El resto, 150 unidades, se fue como calor u otra forma no buscada."}},{"slug":"energia-1.s2.p3.v2","orden":3,"grupo":"energia-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una máquina recibe 500 unidades de energía y entrega 175 en la forma útil. ¿Cuál es su eficiencia?","unidad":"%","decimales":0},"solucion":{"valor":35,"tolerancia":0.7000000000000001,"explicacion":"175 ÷ 500 = 0,35, que es 35 %. El resto, 325 unidades, se fue como calor u otra forma no buscada."}},{"slug":"energia-1.s2.p3.v3","orden":3,"grupo":"energia-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una máquina recibe 80 unidades de energía y entrega 72 en la forma útil. ¿Cuál es su eficiencia?","unidad":"%","decimales":0},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"72 ÷ 80 = 0,9, que es 90 %. El resto, 8 unidades, se fue como calor u otra forma no buscada."}},{"slug":"energia-1.s2.p4","orden":4,"grupo":"energia-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lámparas: el mismo trabajo con menos energía","cuerpo":["Una lámpara LED da la misma luz que una incandescente de 60 W usando alrededor de 8 a 10 W. No es que \"ahorre luz\": desperdicia mucho menos en calor.","La misma idea sirve para cualquier aparato: cuando un aparato es más eficiente, hace el mismo trabajo con menos energía. Es la base de la etiqueta de eficiencia que vas a ver en la próxima unidad."]},"solucion":{}},{"slug":"energia-1.s2.p5","orden":5,"grupo":"energia-1.s2.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas máquinas por su eficiencia típica, de más a menos.","items":[{"id":"i1","texto":"Motor eléctrico"},{"id":"i2","texto":"Central térmica de ciclo combinado"},{"id":"i3","texto":"Motor de auto a nafta"},{"id":"i4","texto":"Lamparita incandescente (como fuente de luz)"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las máquinas que queman algo pierden mucho en calor. Las eléctricas pierden poco. Esa diferencia está en el centro de la transición energética.","valores":{"i1":"≈ 85-95 %","i2":"≈ 55-60 %","i3":"≈ 20-30 %","i4":"≈ 5 %"}}},{"slug":"energia-1.s2.p6","orden":6,"grupo":"energia-1.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 60 W se reemplaza por una LED de 9 W que da la misma luz. ¿Qué porcentaje de energía se ahorra? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1,"explicacion":"Se ahorran 60 − 9 = 51 W de 60: 51 ÷ 60 × 100 ≈ 85 %. La misma luz con mucho menos calor."}},{"slug":"energia-1.s2.p6.v2","orden":6,"grupo":"energia-1.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 100 W se reemplaza por una LED de 14 W que da la misma luz. ¿Qué porcentaje de energía se ahorra? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":86,"tolerancia":1,"explicacion":"Se ahorran 100 − 14 = 86 W de 100: 86 ÷ 100 × 100 ≈ 86 %. La misma luz con mucho menos calor."}},{"slug":"energia-1.s2.p6.v3","orden":6,"grupo":"energia-1.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 40 W se reemplaza por una LED de 6 W que da la misma luz. ¿Qué porcentaje de energía se ahorra? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1,"explicacion":"Se ahorran 40 − 6 = 34 W de 40: 34 ÷ 40 × 100 ≈ 85 %. La misma luz con mucho menos calor."}},{"slug":"energia-1.s2.p7","orden":7,"grupo":"energia-1.s2.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una lamparita incandescente de 60 W da más luz que una LED de 60 W.","razones":[{"id":"r1","texto":"Porque la LED convierte en luz mucha más parte de la energía"},{"id":"r2","texto":"Porque los watts miden la luz que da la lámpara"},{"id":"r3","texto":"Porque las dos tienen la misma eficiencia"}]},"solucion":{"valor":false,"explicacion":"Es al revés: con 60 W, una LED da muchísima más luz, porque convierte en luz una parte mucho mayor de la energía. Los watts miden energía por segundo, no luz.","clave":["r1"]}},{"slug":"energia-1.s2.p8","orden":8,"grupo":"energia-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pérdidas en cadena","cuerpo":["Cuando la energía pasa por varias transformaciones, las pérdidas se multiplican. Si una central aprovecha el 40 %, la red pierde un 10 % en el camino y la lamparita aprovecha el 5 %, de 100 unidades de gas quemado solo llegan como luz 100 × 0,4 × 0,9 × 0,05 ≈ 1,8 unidades.","Por eso mejorar la eficiencia en el último eslabón, el aparato, ahorra mucho más de lo que parece: cada unidad que no pide el aparato se ahorra en toda la cadena."]},"solucion":{}},{"slug":"energia-1.s2.p9","orden":9,"grupo":"energia-1.s2.p9","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"De gas a luz","planteo":"Una central aprovecha el 40 % del gas, la red pierde el 10 % y una lámpara LED convierte el 40 % de la electricidad en luz.","pasos":["Salen de la central: 100 × 0,40 = 40.","Llegan a casa: 40 × 0,90 = 36.","Salen como luz: 36 × 0,40 = 14,4."],"resultado":"Con LED llegan como luz unas 14 de cada 100 unidades de gas; con incandescente, menos de 2. La misma cadena, con un eslabón mejor."},"solucion":{}},{"slug":"energia-1.s2.p10","orden":10,"grupo":"energia-1.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central aprovecha el 40 % del combustible, a casa llega el 90 % de su electricidad y el aparato aprovecha el 80 %. De 100 unidades de combustible, ¿cuántas terminan como energía útil? Redondeá a un decimal.","unidad":"unidades","decimales":1},"solucion":{"valor":28.8,"tolerancia":0.2,"explicacion":"100 × 0,4 × 0,9 × 0,8 ≈ 28,8. Las pérdidas se multiplican eslabón por eslabón."}},{"slug":"energia-1.s2.p10.v2","orden":10,"grupo":"energia-1.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central aprovecha el 50 % del combustible, a casa llega el 90 % de su electricidad y el aparato aprovecha el 90 %. De 100 unidades de combustible, ¿cuántas terminan como energía útil? Redondeá a un decimal.","unidad":"unidades","decimales":1},"solucion":{"valor":40.5,"tolerancia":0.2,"explicacion":"100 × 0,5 × 0,9 × 0,9 ≈ 40,5. Las pérdidas se multiplican eslabón por eslabón."}},{"slug":"energia-1.s2.p10.v3","orden":10,"grupo":"energia-1.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central aprovecha el 35 % del combustible, a casa llega el 85 % de su electricidad y el aparato aprovecha el 60 %. De 100 unidades de combustible, ¿cuántas terminan como energía útil? Redondeá a un decimal.","unidad":"unidades","decimales":1},"solucion":{"valor":17.8,"tolerancia":0.2,"explicacion":"100 × 0,35 × 0,85 × 0,6 ≈ 17,8. Las pérdidas se multiplican eslabón por eslabón."}},{"slug":"energia-1.s2.p11","orden":11,"grupo":"energia-1.s2.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué cambiar una lámpara ahorra gas en una central.","items":[{"id":"i1","texto":"Se cambia una lámpara incandescente por una LED"},{"id":"i2","texto":"La casa pide menos electricidad"},{"id":"i3","texto":"La red transporta menos energía"},{"id":"i4","texto":"La central quema menos gas"},{"id":"i5","texto":"Se emite menos CO₂"},{"id":"i6","texto":"La LED produce gas en la casa"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ahorro viaja para atrás por la cadena. Por eso se dice que la energía más limpia es la que no se usa."}},{"slug":"energia-1.s2.p12","orden":12,"grupo":"energia-1.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los motores de auto a nafta se calientan tanto?","opciones":[{"id":"o1","texto":"Porque la mayor parte de la energía termina como calor"},{"id":"o2","texto":"Porque el sol calienta el capó durante el viaje"},{"id":"o3","texto":"Porque la nafta ya viene caliente de la estación"},{"id":"o4","texto":"Porque el motor necesita calor para mover las ruedas"}]},"solucion":{"clave":["o1"],"explicacion":"Tres cuartos de la energía de la nafta se van en calor. El radiador existe para sacarlo.","por_opcion":{"o3":"La nafta está a temperatura ambiente: el calor sale de la combustión."}}},{"slug":"energia-1.s2.p13","orden":13,"grupo":"energia-1.s2.p13","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales indican que un aparato es poco eficiente? Marcá todas.","opciones":[{"id":"o1","texto":"Se calienta mucho sin que su función sea calentar"},{"id":"o2","texto":"Hace el mismo trabajo que otro con más watts"},{"id":"o3","texto":"Hace mucho ruido o vibra al funcionar"},{"id":"o4","texto":"Tiene una etiqueta de eficiencia clase A"},{"id":"o5","texto":"Es más chico que otro modelo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El calor, el ruido y la vibración son energía que se va sin hacer el trabajo buscado."}},{"slug":"energia-1.s2.p14","orden":14,"grupo":"energia-1.s2.p14","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es energía útil o energía perdida?","grupos":[{"id":"g1","nombre":"Útil"},{"id":"g2","nombre":"Perdida"}],"items":[{"id":"i1","texto":"La luz de una lámpara"},{"id":"i2","texto":"El calor de una lamparita incandescente"},{"id":"i3","texto":"El giro del tambor del lavarropas"},{"id":"i4","texto":"El ruido de un motor"},{"id":"i5","texto":"El calor de una estufa en invierno"},{"id":"i6","texto":"El calor del cargador del celular"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Que algo sea útil depende de lo que buscamos: el calor de la estufa es el objetivo; el de la lamparita, un desperdicio."}},{"slug":"energia-1.s2.p15","orden":15,"grupo":"energia-1.s2.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La eficiencia es la energía {{0}} dividida la energía que {{1}}; en una cadena, las pérdidas se {{2}}.","banco":[{"id":"w1","texto":"útil"},{"id":"w2","texto":"entra"},{"id":"w3","texto":"multiplican"},{"id":"w4","texto":"total"},{"id":"w5","texto":"sale"},{"id":"w6","texto":"restan"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La cuenta y la regla de la cadena, juntas."}}]},{"slug":"energia-1.s3","orden":3,"tipo":"leccion","titulo_es":"De dónde sale la energía","bajada_es":"Fuentes primarias, fuentes secundarias y vectores: el mapa para entender cualquier discusión sobre energía.","minutos":11,"pasos":[{"slug":"energia-1.s3.p1","orden":1,"grupo":"energia-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Fuentes primarias","cuerpo":["Una fuente primaria es la energía tal como está en la naturaleza: petróleo, gas natural, carbón, uranio, sol, viento, agua de los ríos, biomasa (leña, residuos vegetales) y calor de la Tierra (geotermia).","Algunas son fósiles: se formaron durante millones de años con restos de seres vivos y, al quemarse, emiten CO₂ que estaba guardado bajo tierra. Otras son renovables: se reponen a escala humana."]},"solucion":{}},{"slug":"energia-1.s3.p2","orden":2,"grupo":"energia-1.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estas fuentes primarias.","grupos":[{"id":"g1","nombre":"Fósiles"},{"id":"g2","nombre":"Renovables"},{"id":"g3","nombre":"Ni fósil ni renovable"}],"items":[{"id":"i1","texto":"Petróleo"},{"id":"i2","texto":"Sol"},{"id":"i3","texto":"Uranio"},{"id":"i4","texto":"Gas natural"},{"id":"i5","texto":"Viento"},{"id":"i6","texto":"Carbón"},{"id":"i7","texto":"Agua de los ríos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g1","i7":"g2"},"explicacion":"El uranio no es fósil (no viene de seres vivos) ni renovable (es un mineral que se agota), pero no emite CO₂ al generar electricidad."}},{"slug":"energia-1.s3.p3","orden":3,"grupo":"energia-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Secundarias y vectores","cuerpo":["Las fuentes secundarias se obtienen transformando las primarias: la nafta y el gasoil se hacen refinando petróleo; la electricidad se genera con gas, agua, viento, sol o uranio.","La electricidad es un vector: no es una fuente, sino una forma cómoda de transportar energía. Por eso la pregunta \"¿es limpio un auto eléctrico?\" depende de con qué se generó esa electricidad."]},"solucion":{}},{"slug":"energia-1.s3.p4","orden":4,"grupo":"energia-1.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada energía secundaria con la primaria de la que suele salir.","izquierda":[{"id":"a1","texto":"Nafta"},{"id":"a2","texto":"Carbón vegetal"},{"id":"a3","texto":"Electricidad de Yacyretá"},{"id":"a4","texto":"Electricidad de un parque eólico"}],"derecha":[{"id":"b1","texto":"Petróleo"},{"id":"b2","texto":"Leña"},{"id":"b3","texto":"Agua del río Paraná"},{"id":"b4","texto":"Viento"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada secundaria tiene detrás una primaria. La electricidad puede venir de cualquiera."}},{"slug":"energia-1.s3.p5","orden":5,"grupo":"energia-1.s3.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad es una fuente de energía, como el petróleo o el viento.","razones":[{"id":"r1","texto":"Porque es un vector que transporta energía de otra fuente"},{"id":"r2","texto":"Porque la electricidad se extrae de minas"},{"id":"r3","texto":"Porque la electricidad no tiene relación con ninguna fuente"}]},"solucion":{"valor":false,"explicacion":"La electricidad es un vector: transporta energía que viene de una fuente primaria. Su impacto depende de esa fuente.","clave":["r1"]}},{"slug":"energia-1.s3.p6","orden":6,"grupo":"energia-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El mundo y Argentina","cuerpo":["A nivel mundial, alrededor de 8 de cada 10 unidades de energía primaria vienen todavía de combustibles fósiles. En Argentina la proporción es parecida o incluso mayor, con un peso muy alto del gas natural: se usa para generar electricidad, calefaccionar casas, cocinar y en la industria.","La energía primaria no es solo electricidad: también es el combustible del transporte, el gas de las casas y el calor de las industrias. La electricidad es una parte, importante pero no la única."],"datos":{"tipo":"barras","titulo":"Energía primaria mundial por fuente (aproximado)","unidad":"% del total","filas":[{"etiqueta":"Petróleo","valor":32},{"etiqueta":"Carbón","valor":26},{"etiqueta":"Gas natural","valor":23},{"etiqueta":"Hidro","valor":6},{"etiqueta":"Nuclear","valor":4},{"etiqueta":"Eólica, solar y otras renovables","valor":9}],"nota":"Valores redondeados de los últimos años; cambian año a año."}},"solucion":{}},{"slug":"energia-1.s3.p7","orden":7,"grupo":"energia-1.s3.p7","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la energía primaria del mundo viene de combustibles fósiles.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":80,"banda":"lineal","explicacion":"Alrededor del 80 %. Aunque las renovables crecen rápido, el mundo todavía funciona mayormente con petróleo, carbón y gas."}},{"slug":"energia-1.s3.p8","orden":8,"grupo":"energia-1.s3.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Para qué se usa el gas natural en Argentina? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Para generar electricidad en centrales térmicas"},{"id":"o2","texto":"Para calefaccionar casas y calentar agua"},{"id":"o3","texto":"Para cocinar"},{"id":"o4","texto":"Como combustible de algunos vehículos (GNC)"},{"id":"o5","texto":"Para producir la electricidad de las represas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El gas está en casi todo el sistema energético argentino. Las represas usan la fuerza del agua, no gas."}},{"slug":"energia-1.s3.p9","orden":9,"grupo":"energia-1.s3.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un auto eléctrico se carga en un país donde casi toda la electricidad sale del carbón. ¿Qué pasa con sus emisiones?","opciones":[{"id":"o1","texto":"Dependen del carbón que se quemó para generar esa electricidad"},{"id":"o2","texto":"Son cero, porque el auto no tiene caño de escape"},{"id":"o3","texto":"Son iguales a las de un auto a nafta en todos los casos"},{"id":"o4","texto":"Son mayores que las de cualquier auto a nafta"}]},"solucion":{"clave":["o1"],"explicacion":"El auto eléctrico traslada las emisiones del caño de escape a la central. Cuanto más limpia la red, mejor.","por_opcion":{"o3":"Depende de la red: en redes limpias el eléctrico emite mucho menos; en redes muy sucias, la ventaja se achica."}}},{"slug":"energia-1.s3.p10","orden":10,"grupo":"energia-1.s3.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la cadena del combustible de un colectivo diésel.","items":[{"id":"i1","texto":"Se extrae petróleo de un yacimiento"},{"id":"i2","texto":"Se transporta a una refinería"},{"id":"i3","texto":"Se refina y se obtiene gasoil"},{"id":"i4","texto":"Se distribuye a las estaciones de servicio"},{"id":"i5","texto":"El colectivo lo quema en su motor"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"De fuente primaria a secundaria y a uso final. Cada paso usa energía y tiene sus pérdidas."}},{"slug":"energia-1.s3.p11","orden":11,"grupo":"energia-1.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El petróleo y el gas son fuentes fósiles."},{"id":"s2","texto":"La electricidad es una fuente limpia porque no tiene humo."},{"id":"s3","texto":"El sol y el viento son renovables."},{"id":"s4","texto":"El uranio es un combustible fósil, como el carbón."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Fuente primaria, secundaria y vector: con esas tres ideas se desarman muchas confusiones.","por_opcion":{"s2":"La electricidad es un vector: es tan limpia como la fuente que la generó.","s4":"El uranio es un mineral, no se formó de restos de seres vivos."}}},{"slug":"energia-1.s3.p12","orden":12,"grupo":"energia-1.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El petróleo es una fuente {{0}}, la nafta es {{1}} y la electricidad es un {{2}}.","banco":[{"id":"w1","texto":"primaria"},{"id":"w2","texto":"secundaria"},{"id":"w3","texto":"vector"},{"id":"w4","texto":"renovable"},{"id":"w5","texto":"fósil"},{"id":"w6","texto":"residuo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El mapa de toda la energía, resumido en una sola línea."}},{"slug":"energia-1.s3.p13","orden":13,"grupo":"energia-1.s3.p13","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el sol de hace millones de años llega al tanque de un auto.","items":[{"id":"i1","texto":"Algas y plantas antiguas guardaron energía del sol"},{"id":"i2","texto":"Quedaron enterradas bajo capas de sedimentos"},{"id":"i3","texto":"Con presión, calor y millones de años se formó petróleo"},{"id":"i4","texto":"Se extrae y se refina en nafta"},{"id":"i5","texto":"El petróleo se forma en pocos años en las refinerías"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Quemar petróleo es liberar en segundos lo que la naturaleza tardó millones de años en guardar. Por eso no es renovable."}}]},{"slug":"energia-1.s4","orden":4,"tipo":"leccion","titulo_es":"Medir la energía","bajada_es":"Joules, calorías y kilowatt-hora: las unidades con que se mide la energía y cómo pasar de una a otra.","minutos":12,"pasos":[{"slug":"energia-1.s4.p1","orden":1,"grupo":"energia-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres unidades, una misma cosa","cuerpo":["La energía se mide en joules (J) en física, en calorías en la nutrición y en kilowatt-hora (kWh) en las facturas de luz. Son unidades distintas para la misma cosa, como litros y metros cúbicos para el agua.","Un kWh es la energía que usa un aparato de 1 kW durante 1 hora, como viste en el tronco. Equivale a 3,6 millones de joules (3,6 MJ). Una kilocaloría, la \"caloría\" de las etiquetas de comida, son unos 4.184 joules."],"destacado":{"valor":"1 kWh = 3,6 MJ","texto":"la equivalencia que conecta la factura de luz con la física."}},"solucion":{}},{"slug":"energia-1.s4.p2","orden":2,"grupo":"energia-1.s4.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada unidad con dónde se usa más.","izquierda":[{"id":"a1","texto":"Kilowatt-hora (kWh)"},{"id":"a2","texto":"Kilocaloría (kcal)"},{"id":"a3","texto":"Joule (J)"},{"id":"a4","texto":"Metro cúbico de gas (m³)"}],"derecha":[{"id":"b1","texto":"Factura de luz"},{"id":"b2","texto":"Etiqueta de un alimento"},{"id":"b3","texto":"Libros de física"},{"id":"b4","texto":"Factura de gas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El m³ de gas mide volumen, pero cada m³ de gas natural tiene unos 10 kWh de energía."}},{"slug":"energia-1.s4.p3","orden":3,"grupo":"energia-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Potencia contra energía, otra vez","cuerpo":["La potencia es el ritmo al que se usa la energía; se mide en watts (W) o kilowatts (kW). La energía es la cantidad total: potencia por tiempo. Una pava de 2.000 W prendida 3 minutos usa 2 kW × 0,05 h = 0,1 kWh.","Confundir las dos es el error más común. Un aparato de mucha potencia usado poco tiempo puede gastar menos energía que uno de poca potencia prendido todo el día."]},"solucion":{}},{"slug":"energia-1.s4.p4","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 2.000 W funciona 3 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":0.1,"tolerancia":0.01,"explicacion":"2 kW × 0,05 h = 0,1 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p4.v2","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.500 W funciona 20 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":0.5,"tolerancia":0.01,"explicacion":"1,5 kW × 0,333 h = 0,5 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p4.v3","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 800 W funciona 30 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":0.4,"tolerancia":0.01,"explicacion":"0,8 kW × 0,5 h = 0,4 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p4.v4","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 100 W funciona 600 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":1,"tolerancia":0.01,"explicacion":"0,1 kW × 10 h = 1 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p5","orden":5,"grupo":"energia-1.s4.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"La energía de tu comida en kWh","planteo":"Una persona come 2.000 kcal por día. ¿Cuántos kWh son?","pasos":["2.000 kcal × 4.184 J = 8.368.000 J ≈ 8,4 MJ.","8,4 MJ ÷ 3,6 MJ por kWh ≈ 2,3 kWh."],"resultado":"Todo lo que comés en un día equivale a unos 2,3 kWh: menos que lo que usa una estufa eléctrica de 2.000 W en poco más de una hora."},"solucion":{}},{"slug":"energia-1.s4.p6","orden":6,"grupo":"energia-1.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona come 2.500 kcal por día. ¿Cuántos kWh son? Usá 1 kcal = 4.184 J y 1 kWh = 3,6 MJ. Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":2.9,"tolerancia":0.1,"explicacion":"2.500 × 4.184 = 10.460.000 J; ÷ 3.600.000 ≈ 2,9 kWh."}},{"slug":"energia-1.s4.p6.v2","orden":6,"grupo":"energia-1.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona come 1.800 kcal por día. ¿Cuántos kWh son? Usá 1 kcal = 4.184 J y 1 kWh = 3,6 MJ. Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":2.1,"tolerancia":0.1,"explicacion":"1.800 × 4.184 = 7.531.200 J; ÷ 3.600.000 ≈ 2,1 kWh."}},{"slug":"energia-1.s4.p6.v3","orden":6,"grupo":"energia-1.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona come 3.000 kcal por día. ¿Cuántos kWh son? Usá 1 kcal = 4.184 J y 1 kWh = 3,6 MJ. Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"3.000 × 4.184 = 12.552.000 J; ÷ 3.600.000 ≈ 3,5 kWh."}},{"slug":"energia-1.s4.p7","orden":7,"grupo":"energia-1.s4.p7","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená por energía, de más a menos.","items":[{"id":"i1","texto":"1 m³ de gas natural"},{"id":"i2","texto":"2.000 kcal de comida"},{"id":"i3","texto":"Una pava eléctrica de 2.000 W por 3 minutos"},{"id":"i4","texto":"Una LED de 9 W prendida 1 hora"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Con una misma unidad, cosas muy distintas se vuelven comparables. Es la herramienta de los órdenes de magnitud del tronco.","valores":{"i1":"≈ 10 kWh","i2":"≈ 2,3 kWh","i3":"0,1 kWh","i4":"0,009 kWh"}}},{"slug":"energia-1.s4.p8","orden":8,"grupo":"energia-1.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una estufa de 2.000 W usa siempre más energía que una heladera de 150 W.","razones":[{"id":"r1","texto":"Porque la energía depende también del tiempo de uso"},{"id":"r2","texto":"Porque la potencia y la energía son lo mismo"},{"id":"r3","texto":"Porque las heladeras no usan electricidad"}]},"solucion":{"valor":false,"explicacion":"Depende del tiempo. La heladera funciona todo el año; la estufa, algunas horas en invierno. La energía es potencia por tiempo.","clave":["r1"]}},{"slug":"energia-1.s4.p9","orden":9,"grupo":"energia-1.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Grandes cantidades","cuerpo":["Para cantidades grandes se usan múltiplos: un megawatt-hora (MWh) son 1.000 kWh; un gigawatt-hora (GWh), un millón de kWh; un terawatt-hora (TWh), mil millones de kWh.","Una casa argentina típica usa del orden de 2.000 a 4.000 kWh de electricidad por año. Argentina, como país, consume alrededor de 140 TWh de electricidad por año."]},"solucion":{}},{"slug":"energia-1.s4.p10","orden":10,"grupo":"energia-1.s4.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas unidades de menor a mayor.","items":[{"id":"i1","texto":"Watt-hora (Wh)"},{"id":"i2","texto":"Kilowatt-hora (kWh)"},{"id":"i3","texto":"Megawatt-hora (MWh)"},{"id":"i4","texto":"Gigawatt-hora (GWh)"},{"id":"i5","texto":"Terawatt-hora (TWh)"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada paso multiplica por mil. Como gramo, kilo y tonelada, pero con más escalones."}},{"slug":"energia-1.s4.p11","orden":11,"grupo":"energia-1.s4.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 1.000 casas que usan 3.000 kWh por año cada una. ¿Cuántos GWh usan en total?","unidad":"GWh","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"1.000 × 3.000 = 3.000.000 kWh. Un GWh es un millón de kWh: 3 GWh."}},{"slug":"energia-1.s4.p11.v2","orden":11,"grupo":"energia-1.s4.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 5.000 casas que usan 2.500 kWh por año cada una. ¿Cuántos GWh usan en total?","unidad":"GWh","decimales":1},"solucion":{"valor":12.5,"tolerancia":0.25,"explicacion":"5.000 × 2.500 = 12.500.000 kWh. Un GWh es un millón de kWh: 12,5 GWh."}},{"slug":"energia-1.s4.p11.v3","orden":11,"grupo":"energia-1.s4.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 20.000 casas que usan 3.000 kWh por año cada una. ¿Cuántos GWh usan en total?","unidad":"GWh","decimales":1},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"20.000 × 3.000 = 60.000.000 kWh. Un GWh es un millón de kWh: 60 GWh."}},{"slug":"energia-1.s4.p12","orden":12,"grupo":"energia-1.s4.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La factura de luz marca 500 kWh en dos meses. ¿Qué mide ese número?","opciones":[{"id":"o1","texto":"La energía eléctrica que usó la casa en esos dos meses"},{"id":"o2","texto":"La potencia máxima que puede usar la casa por vez"},{"id":"o3","texto":"Lo que cuesta la luz en pesos"},{"id":"o4","texto":"La cantidad de aparatos que tiene conectados la casa"}]},"solucion":{"clave":["o1"],"explicacion":"El medidor suma energía, kWh, a lo largo del tiempo. La potencia contratada es otro dato.","por_opcion":{"o3":"Los kWh son energía; el precio sale de multiplicarlos por la tarifa."}}},{"slug":"energia-1.s4.p13","orden":13,"grupo":"energia-1.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diálogo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"—La pava tiene 2.000 W de potencia."},{"id":"s2","texto":"—Entonces cada vez que la uso gasto 2.000 kWh."},{"id":"s3","texto":"—Un kWh son 3,6 millones de joules."},{"id":"s4","texto":"—Y un GWh son mil kWh."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Potencia contra energía, y los múltiplos: dos trampas clásicas.","por_opcion":{"s2":"Los W son potencia; la energía depende del tiempo: 3 minutos son 0,1 kWh.","s4":"Un GWh es un millón de kWh; mil kWh son un MWh."}}},{"slug":"energia-1.s4.p14","orden":14,"grupo":"energia-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un kWh son {{0}} millones de joules; mil kWh son un {{1}}; y un millón de kWh son un {{2}}.","banco":[{"id":"w1","texto":"3,6"},{"id":"w2","texto":"MWh"},{"id":"w3","texto":"GWh"},{"id":"w4","texto":"36"},{"id":"w5","texto":"TWh"},{"id":"w6","texto":"kW"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La equivalencia y los múltiplos, resumidos en una línea."}}]},{"slug":"energia-1.s5","orden":5,"tipo":"leccion","titulo_es":"Energía y clima","bajada_es":"Por qué la energía está en el centro del cambio climático, y qué significa descarbonizar.","minutos":11,"pasos":[{"slug":"energia-1.s5.p1","orden":1,"grupo":"energia-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quemar es emitir","cuerpo":["Cuando se quema un combustible fósil, el carbono que tiene se une con el oxígeno del aire y forma CO₂. No hay forma de quemar nafta, gas o carbón sin producirlo: es química básica.","Por eso el uso de energía es la mayor fuente de gases de efecto invernadero: alrededor de tres cuartos de las emisiones del mundo vienen de producir y usar energía, en electricidad, transporte, calefacción e industria."],"destacado":{"valor":"≈ 3/4","texto":"de las emisiones mundiales de gases de efecto invernadero vienen de la energía."}},"solucion":{}},{"slug":"energia-1.s5.p2","orden":2,"grupo":"energia-1.s5.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué es imposible quemar gas natural sin emitir CO₂?","opciones":[{"id":"o1","texto":"Porque su carbono se combina con el oxígeno al quemarse"},{"id":"o2","texto":"Porque las cañerías de gas están hechas de carbono"},{"id":"o3","texto":"Porque el gas ya trae CO₂ mezclado desde el yacimiento"},{"id":"o4","texto":"Porque las hornallas liberan CO₂ aunque estén apagadas"}]},"solucion":{"clave":["o1"],"explicacion":"Combustión es, justamente, la reacción del carbono con el oxígeno. El CO₂ es su producto inevitable.","por_opcion":{"o3":"Puede traer algo, pero el grueso del CO₂ se forma en la combustión misma."}}},{"slug":"energia-1.s5.p3","orden":3,"grupo":"energia-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Factores de emisión","cuerpo":["Para calcular emisiones se usan factores de emisión: cuántos kilos de CO₂ salen por cada unidad de combustible. Quemar un litro de nafta emite unos 2,3 kg de CO₂; un litro de gasoil, unos 2,7 kg; un metro cúbico de gas natural, unos 1,9 kg.","Parece raro que un litro de nafta, que pesa menos de un kilo, produzca más de dos kilos de CO₂. La razón: el CO₂ incluye el oxígeno que se toma del aire."],"datos":{"tipo":"tabla","titulo":"Factores de emisión aproximados","columnas":["Combustible","kg de CO₂"],"filas":[["1 litro de nafta","≈ 2,3"],["1 litro de gasoil","≈ 2,7"],["1 m³ de gas natural","≈ 1,9"]],"nota":"Valores de referencia redondeados."}},"solucion":{}},{"slug":"energia-1.s5.p4","orden":4,"grupo":"energia-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto carga 40 litros de nafta por semana. ¿Cuántos kilos de CO₂ emite por semana al quemarla? (2,3 kg por litro)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":92,"tolerancia":1.84,"explicacion":"40 × 2,3 = 92 kg de CO₂ por semana. Por año son más de 4 toneladas."}},{"slug":"energia-1.s5.p4.v2","orden":4,"grupo":"energia-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto carga 50 litros de nafta por semana. ¿Cuántos kilos de CO₂ emite por semana al quemarla? (2,3 kg por litro)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":115,"tolerancia":2.3000000000000003,"explicacion":"50 × 2,3 = 115 kg de CO₂ por semana. Por año son más de 5 toneladas."}},{"slug":"energia-1.s5.p4.v3","orden":4,"grupo":"energia-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto carga 60 litros de nafta por semana. ¿Cuántos kilos de CO₂ emite por semana al quemarla? (2,3 kg por litro)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":138,"tolerancia":2.7600000000000002,"explicacion":"60 × 2,3 = 138 kg de CO₂ por semana. Por año son más de 7 toneladas."}},{"slug":"energia-1.s5.p5","orden":5,"grupo":"energia-1.s5.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un litro de nafta, que pesa unos 750 gramos, no puede producir más de 750 gramos de CO₂.","razones":[{"id":"r1","texto":"Porque el CO₂ incluye el oxígeno que se toma del aire"},{"id":"r2","texto":"Porque la nafta pesa más cuando está caliente"},{"id":"r3","texto":"Porque el CO₂ se produce de la nada"}]},"solucion":{"valor":false,"explicacion":"Produce unos 2,3 kg, porque al quemarse cada átomo de carbono toma dos átomos de oxígeno del aire, que suman peso.","clave":["r1"]}},{"slug":"energia-1.s5.p6","orden":6,"grupo":"energia-1.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 60 m³ de gas natural en un mes de invierno. ¿Cuántos kilos de CO₂ emite? (1,9 kg por m³)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":114,"tolerancia":2.2800000000000002,"explicacion":"60 × 1,9 = 114 kg de CO₂. En las casas argentinas, la calefacción a gas suele ser la mayor fuente de emisiones directas."}},{"slug":"energia-1.s5.p6.v2","orden":6,"grupo":"energia-1.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 90 m³ de gas natural en un mes de invierno. ¿Cuántos kilos de CO₂ emite? (1,9 kg por m³)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":171,"tolerancia":3.42,"explicacion":"90 × 1,9 = 171 kg de CO₂. En las casas argentinas, la calefacción a gas suele ser la mayor fuente de emisiones directas."}},{"slug":"energia-1.s5.p6.v3","orden":6,"grupo":"energia-1.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 150 m³ de gas natural en un mes de invierno. ¿Cuántos kilos de CO₂ emite? (1,9 kg por m³)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":285,"tolerancia":5.7,"explicacion":"150 × 1,9 = 285 kg de CO₂. En las casas argentinas, la calefacción a gas suele ser la mayor fuente de emisiones directas."}},{"slug":"energia-1.s5.p7","orden":7,"grupo":"energia-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Descarbonizar: tres caminos","cuerpo":["Descarbonizar la energía es bajar las emisiones de CO₂ por cada unidad de energía que usamos. Hay tres caminos que se combinan: usar menos energía para lo mismo (eficiencia), generar con fuentes que no emiten (renovables, nuclear) y electrificar los usos que hoy queman combustible (autos, calefacción, cocinas).","Electrificar sirve cuando la electricidad es cada vez más limpia. Por eso las tres cosas van juntas."],"lista":["Eficiencia: menos energía para lo mismo","Fuentes limpias: renovables y nuclear","Electrificación: pasar a eléctrico lo que hoy quema combustible"]},"solucion":{}},{"slug":"energia-1.s5.p8","orden":8,"grupo":"energia-1.s5.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué camino de descarbonización es cada medida?","grupos":[{"id":"g1","nombre":"Eficiencia"},{"id":"g2","nombre":"Fuentes limpias"},{"id":"g3","nombre":"Electrificación"}],"items":[{"id":"i1","texto":"Cambiar lámparas a LED"},{"id":"i2","texto":"Construir un parque eólico"},{"id":"i3","texto":"Pasar colectivos diésel a eléctricos"},{"id":"i4","texto":"Aislar el techo de una casa"},{"id":"i5","texto":"Instalar paneles solares en una escuela"},{"id":"i6","texto":"Cambiar una estufa a gas por una bomba de calor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres caminos que se refuerzan: la eficiencia achica la demanda, las fuentes limpias la cubren y la electrificación lleva esa limpieza a más usos."}},{"slug":"energia-1.s5.p9","orden":9,"grupo":"energia-1.s5.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué electrificar sirve más cuando la red es limpia.","items":[{"id":"i1","texto":"Un colectivo pasa de gasoil a electricidad"},{"id":"i2","texto":"Deja de quemar combustible en la calle"},{"id":"i3","texto":"Su energía ahora viene de la red"},{"id":"i4","texto":"Si la red se genera con fuentes limpias, emite mucho menos"},{"id":"i5","texto":"El colectivo eléctrico produce su propia electricidad al andar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Electrificar sin limpiar la red sirve menos. Limpiar la red sin electrificar deja afuera al transporte y al calor."}},{"slug":"energia-1.s5.p10","orden":10,"grupo":"energia-1.s5.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos usos de energía emiten CO₂ directamente al usarse? Marcá todos.","opciones":[{"id":"o1","texto":"Una hornalla de gas"},{"id":"o2","texto":"Un auto a nafta"},{"id":"o3","texto":"Una estufa a leña"},{"id":"o4","texto":"Un ventilador eléctrico"},{"id":"o5","texto":"Una LED encendida"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los eléctricos no emiten donde se usan; sus emisiones, si las hay, están en la central. Los que queman algo emiten en el lugar."}},{"slug":"energia-1.s5.p11","orden":11,"grupo":"energia-1.s5.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para un país cuya electricidad sale mayormente de gas, ¿qué conviene hacer primero si quiere que los autos eléctricos ayuden mucho?","opciones":[{"id":"o1","texto":"Limpiar la red sumando fuentes que no emiten"},{"id":"o2","texto":"Prohibir todos los autos de un día para el otro"},{"id":"o3","texto":"Nada: el auto eléctrico siempre emite cero"},{"id":"o4","texto":"Importar nafta más barata de otros países"}]},"solucion":{"clave":["o1"],"explicacion":"La electrificación y la red limpia van de la mano. Aun con gas, el eléctrico suele emitir menos, pero la ventaja crece con una red más limpia.","por_opcion":{"o3":"El auto no tiene caño de escape, pero su electricidad sí puede tener emisiones."}}},{"slug":"energia-1.s5.p12","orden":12,"grupo":"energia-1.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La energía es la mayor fuente de emisiones del mundo."},{"id":"s2","texto":"Como la electricidad no emite humo, electrificar alcanza para resolver el clima."},{"id":"s3","texto":"Quemar un litro de nafta emite más de 2 kg de CO₂."},{"id":"s4","texto":"La eficiencia no sirve porque las renovables son infinitas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ningún camino alcanza solo. La combinación es la estrategia.","por_opcion":{"s2":"Electrificar ayuda si la electricidad se genera con fuentes limpias; si no, se traslada el problema.","s4":"La eficiencia reduce cuánto hay que generar: abarata y acelera la transición."}}},{"slug":"energia-1.s5.p13","orden":13,"grupo":"energia-1.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Quemar combustibles fósiles emite {{0}}; los tres caminos para descarbonizar son eficiencia, fuentes {{1}} y {{2}}.","banco":[{"id":"w1","texto":"CO₂"},{"id":"w2","texto":"limpias"},{"id":"w3","texto":"electrificación"},{"id":"w4","texto":"oxígeno"},{"id":"w5","texto":"fósiles"},{"id":"w6","texto":"importación"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea central de toda la rama de energía."}}]},{"slug":"energia-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: qué es la energía","bajada_es":"Formas, eficiencia, fuentes, unidades y emisiones, mezclados.","minutos":8,"pasos":[{"slug":"energia-1.s6.p1","orden":1,"grupo":"energia-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Qué es la energía». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la energía de un día de Lucía","bajada_es":"Seguí la energía de un día común: qué usa, de dónde sale y cuánto CO₂ emite. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"energia-1.s7.p1","orden":1,"grupo":"energia-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El día de Lucía","cuerpo":["Lucía vive en Córdoba. A la mañana calienta agua en una pava eléctrica de 2.000 W durante 3 minutos. Va al trabajo en auto: 20 km ida y vuelta, y su auto usa 8 litros de nafta cada 100 km. A la noche mira una serie 2 horas en un televisor de 100 W con dos lámparas LED de 9 W prendidas.","En invierno, la estufa a gas de su casa usa 3 m³ de gas por día."]},"solucion":{}},{"slug":"energia-1.s7.p2","orden":2,"grupo":"energia-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de nafta usa Lucía por día para ir y volver del trabajo?","unidad":"litros","decimales":1,"contexto":"Lucía maneja 20 km por día; su auto usa 8 L cada 100 km."},"solucion":{"valor":1.6,"tolerancia":0.05,"explicacion":"20 km × 8 litros ÷ 100 km = 1,6 litros por día."}},{"slug":"energia-1.s7.p3","orden":3,"grupo":"energia-1.s7.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos de CO₂ emite ese viaje diario? (2,3 kg por litro de nafta)","unidad":"kg de CO₂","decimales":2,"contexto":"Lucía usa 1,6 L de nafta por día; la nafta emite 2,3 kg de CO₂ por litro."},"solucion":{"valor":3.68,"tolerancia":0.05,"explicacion":"1,6 × 2,3 = 3,68 kg de CO₂ por día. En un año laboral de unos 230 días, más de 800 kg."}},{"slug":"energia-1.s7.p4","orden":4,"grupo":"energia-1.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh de electricidad usa a la noche entre el televisor y las dos lámparas?","unidad":"kWh","decimales":3,"contexto":"TV de 100 W y dos LED de 9 W, prendidos 2 horas."},"solucion":{"valor":0.236,"tolerancia":0.005,"explicacion":"Televisor: 0,1 kW × 2 h = 0,2 kWh. Lámparas: 2 × 0,009 kW × 2 h = 0,036 kWh. Total: 0,236 kWh."}},{"slug":"energia-1.s7.p5","orden":5,"grupo":"energia-1.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los usos de energía de Lucía en un día de invierno, de más a menos energía (aproximado).","items":[{"id":"i1","texto":"Estufa a gas (3 m³)"},{"id":"i2","texto":"Viaje en auto (1,6 L de nafta)"},{"id":"i3","texto":"Televisor y lámparas"},{"id":"i4","texto":"Pava eléctrica"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La calefacción y el auto pesan cientos de veces más que la pava o las luces. Es el principio de elegir por impacto del tronco.","valores":{"i1":"≈ 30 kWh","i2":"≈ 14 kWh","i3":"≈ 0,24 kWh","i4":"0,1 kWh"}}},{"slug":"energia-1.s7.p6","orden":6,"grupo":"energia-1.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si Lucía quiere bajar sus emisiones lo más posible con un solo cambio, ¿cuál tiene más impacto?","opciones":[{"id":"o1","texto":"Mejorar la aislación de la casa o la calefacción"},{"id":"o2","texto":"Apagar las lámparas LED un rato antes"},{"id":"o3","texto":"Calentar menos agua en la pava a la mañana"},{"id":"o4","texto":"Desenchufar el cargador del celular a la noche"}]},"solucion":{"clave":["o1"],"explicacion":"La calefacción es el mayor uso de energía de su día de invierno. Ahí está el cambio grande. El auto es el segundo.","por_opcion":{"o3":"Ahorra, pero es un uso muy chico comparado con la calefacción y el auto."}}},{"slug":"energia-1.s7.p7","orden":7,"grupo":"energia-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los usos de energía de Lucía.","grupos":[{"id":"g1","nombre":"Emiten CO₂ donde se usan"},{"id":"g2","nombre":"Sus emisiones dependen de la red"}],"items":[{"id":"i1","texto":"La estufa a gas"},{"id":"i2","texto":"La pava eléctrica"},{"id":"i3","texto":"El auto a nafta"},{"id":"i4","texto":"El televisor"},{"id":"i5","texto":"Las lámparas LED"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Los usos que queman combustible emiten en el lugar; los eléctricos, en la central. Electrificar y limpiar la red atacan los dos grupos."}},{"slug":"energia-1.s7.p8","orden":8,"grupo":"energia-1.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Lucía escribe su plan. Marcá lo que está mal razonado.","segmentos":[{"id":"s1","texto":"Voy a revisar los burletes y cerrar mejor las ventanas en invierno."},{"id":"s2","texto":"Voy a desenchufar la pava, porque es lo que más energía usa en mi casa."},{"id":"s3","texto":"Voy a compartir el auto con un compañero dos días por semana."},{"id":"s4","texto":"Como la tele es eléctrica, no tiene ningún impacto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan empieza por los usos grandes y no descarta los eléctricos: solo los pone en su lugar.","por_opcion":{"s2":"La pava usa 0,1 kWh por día; la estufa, unos 30.","s4":"Su impacto depende de cómo se genera la electricidad, aunque sea chico."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-2","rama":"energia","orden":2,"nivel":1,"titulo_es":"La energía en casa","bajada_es":"Calefacción, heladera, aire acondicionado y stand-by: en qué se va la energía de una casa y dónde está el ahorro de verdad.","objetivos_es":["Identificar los usos que más energía consumen en un hogar","Calcular el consumo mensual de un aparato con su potencia y sus horas de uso","Leer una factura de electricidad y comparar períodos","Usar la etiqueta de eficiencia para elegir un aparato","Aplicar medidas de calefacción y refrigeración eficientes"],"repasa":["energia-1","tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["iea-eficiencia","iea-energia","owid-energia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-2.s1","orden":1,"tipo":"leccion","titulo_es":"En qué se va la energía de una casa","bajada_es":"Gas y electricidad, calefacción y heladera: el mapa de los consumos de un hogar.","minutos":11,"pasos":[{"slug":"energia-2.s1.p1","orden":1,"grupo":"energia-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos energías entran a casa","cuerpo":["En la mayoría de las casas argentinas con red de gas entran dos energías: gas natural y electricidad. El gas se usa para calefacción, agua caliente y cocina; la electricidad, para la heladera, la iluminación, los electrodomésticos, los equipos electrónicos y, cada vez más, el aire acondicionado.","Donde no hay red de gas, se usa gas envasado (garrafas), leña o electricidad para calefaccionar y cocinar, y eso cambia mucho las cuentas."]},"solucion":{}},{"slug":"energia-2.s1.p2","orden":2,"grupo":"energia-2.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué energía suele usar cada cosa en una casa con red de gas?","grupos":[{"id":"g1","nombre":"Gas"},{"id":"g2","nombre":"Electricidad"}],"items":[{"id":"i1","texto":"Estufa de tiro balanceado"},{"id":"i2","texto":"Heladera"},{"id":"i3","texto":"Calefón o termotanque a gas"},{"id":"i4","texto":"Lámparas"},{"id":"i5","texto":"Hornallas de la cocina"},{"id":"i6","texto":"Aire acondicionado"},{"id":"i7","texto":"Televisor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g2"},"explicacion":"En una casa con gas, la calefacción y el agua caliente suelen ser a gas. Eso importa: son justamente los usos más grandes."}},{"slug":"energia-2.s1.p3","orden":3,"grupo":"energia-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Calor: el uso más grande","cuerpo":["Si se suma toda la energía de un año, en muchas casas del centro y el sur del país el uso más grande es la calefacción, seguida por el agua caliente. Calentar aire y agua requiere muchísima energía.","En la electricidad, los grandes consumos suelen ser la heladera (que funciona todo el año), el aire acondicionado en verano, los aparatos que calientan (pava, horno eléctrico, estufas eléctricas) y la suma de muchos aparatos chicos."],"datos":{"tipo":"barras","titulo":"Energía de una casa con gas en un año (ejemplo aproximado)","unidad":"% del total","filas":[{"etiqueta":"Calefacción","valor":50},{"etiqueta":"Agua caliente","valor":20},{"etiqueta":"Cocina","valor":8},{"etiqueta":"Heladera","valor":7},{"etiqueta":"Resto de la electricidad","valor":15}],"nota":"Ejemplo ilustrativo de una casa de clima templado. Varía mucho según la región y el tipo de casa."}},"solucion":{}},{"slug":"energia-2.s1.p4","orden":4,"grupo":"energia-2.s1.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"En esa casa de ejemplo, ordená los usos de más a menos energía anual.","items":[{"id":"i1","texto":"Calefacción"},{"id":"i2","texto":"Agua caliente"},{"id":"i3","texto":"Cocina"},{"id":"i4","texto":"Heladera"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El calor —para el ambiente y para el agua— se lleva la mayor parte. Por eso ahí están los ahorros más grandes.","valores":{"i1":"≈ 50 %","i2":"≈ 20 %","i3":"≈ 8 %","i4":"≈ 7 %"}}},{"slug":"energia-2.s1.p5","orden":5,"grupo":"energia-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En una casa con gas, apagar las luces es la forma más efectiva de bajar la energía total que usa la casa.","razones":[{"id":"r1","texto":"Porque la calefacción y el agua caliente pesan mucho más"},{"id":"r2","texto":"Porque las luces no usan energía"},{"id":"r3","texto":"Porque las luces usan más energía que la calefacción"}]},"solucion":{"valor":false,"explicacion":"Apagar luces ayuda, pero la iluminación LED es un uso chico. La calefacción y el agua caliente pesan muchísimo más.","clave":["r1"]}},{"slug":"energia-2.s1.p6","orden":6,"grupo":"energia-2.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los pilotos y los consumos que no se ven","cuerpo":["Algunos consumos pasan desapercibidos: el piloto de un termotanque o una estufa a gas queda encendido todo el día, aunque nadie use agua caliente ni calefacción. En verano, apagar los pilotos de las estufas que no se usan ahorra gas sin ningún esfuerzo.","En la electricidad pasa algo parecido con el stand-by: televisores, decodificadores, cargadores y equipos de audio que consumen aunque estén \"apagados\"."]},"solucion":{}},{"slug":"energia-2.s1.p7","orden":7,"grupo":"energia-2.s1.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos consumos suceden aunque nadie esté usando el aparato? Marcá todos.","opciones":[{"id":"o1","texto":"El piloto de una estufa a gas en verano"},{"id":"o2","texto":"Un decodificador en stand-by"},{"id":"o3","texto":"Un cargador enchufado sin celular"},{"id":"o4","texto":"Una pava eléctrica desenchufada"},{"id":"o5","texto":"Una lámpara apagada con la llave"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Lo que queda enchufado o encendido \"por las dudas\" consume todo el tiempo. Chico por hora, grande por año."}},{"slug":"energia-2.s1.p8","orden":8,"grupo":"energia-2.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada uso con su mejor ahorro.","izquierda":[{"id":"a1","texto":"Calefacción"},{"id":"a2","texto":"Agua caliente"},{"id":"a3","texto":"Heladera"},{"id":"a4","texto":"Stand-by"}],"derecha":[{"id":"b1","texto":"Burletes y temperatura moderada"},{"id":"b2","texto":"Duchas más cortas"},{"id":"b3","texto":"Cerrarla bien y no poner cosas calientes"},{"id":"b4","texto":"Zapatilla con interruptor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada uso tiene su palanca. Las más grandes están en el calor."}},{"slug":"energia-2.s1.p9","orden":9,"grupo":"energia-2.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una familia quiere bajar su consumo de gas en invierno. ¿Por dónde conviene empezar?","opciones":[{"id":"o1","texto":"Por la calefacción y sus pérdidas"},{"id":"o2","texto":"Por la cocina: dejar de hacer guisos y sopas"},{"id":"o3","texto":"Por el horno: usarlo solo los domingos"},{"id":"o4","texto":"Por la pava: calentar agua solo una vez por día"}]},"solucion":{"clave":["o1"],"explicacion":"Elegir por impacto, como en el tronco: la calefacción es la mitad del consumo en muchas casas.","por_opcion":{"o3":"El horno usa gas, pero mucho menos que la calefacción en invierno."}}},{"slug":"energia-2.s1.p10","orden":10,"grupo":"energia-2.s1.p10","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de una revista y marcá los que no tienen sentido o están mal.","segmentos":[{"id":"s1","texto":"En verano, apagá los pilotos de las estufas."},{"id":"s2","texto":"Desenchufá la heladera de noche para ahorrar."},{"id":"s3","texto":"Revisá los burletes antes del invierno."},{"id":"s4","texto":"Dejá la estufa prendida con la ventana abierta para ventilar mejor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen consejo ahorra sin arruinar la comida ni la salud.","por_opcion":{"s2":"Se corta la cadena de frío y la comida se echa a perder; además al volver consume más.","s4":"Se tira el calor afuera. Para ventilar alcanza con abrir unos minutos."}}},{"slug":"energia-2.s1.p11","orden":11,"grupo":"energia-2.s1.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el piloto de una estufa en verano es un derroche.","items":[{"id":"i1","texto":"La estufa no se usa en verano"},{"id":"i2","texto":"El piloto sigue encendido todo el día"},{"id":"i3","texto":"Quema gas durante meses sin calentar nada útil"},{"id":"i4","texto":"Se paga ese gas y se emite CO₂ sin motivo"},{"id":"i5","texto":"El piloto genera electricidad para la casa"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un consumo chico por hora, multiplicado por todas las horas de un verano."}},{"slug":"energia-2.s1.p12","orden":12,"grupo":"energia-2.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En muchas casas, el mayor consumo de energía es la {{0}}, seguida por el agua {{1}}.","banco":[{"id":"w1","texto":"calefacción"},{"id":"w2","texto":"caliente"},{"id":"w3","texto":"iluminación"},{"id":"w4","texto":"fría"},{"id":"w5","texto":"computadora"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Por eso los ahorros grandes están en el calor, no en las luces."}},{"slug":"energia-2.s1.p13","orden":13,"grupo":"energia-2.s1.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"En esa casa de ejemplo, ¿qué porcentaje de toda la energía va a calefacción y agua caliente juntas?","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":70,"banda":"lineal","explicacion":"Alrededor del 70 %: la mitad para la calefacción y un quinto para el agua caliente. Calentar es lo que más energía pide."}}]},{"slug":"energia-2.s2","orden":2,"tipo":"leccion","titulo_es":"Cuánto usa cada aparato","bajada_es":"Potencia por horas: la cuenta que permite saber cuánto consume la heladera, el aire o el stand-by.","minutos":12,"pasos":[{"slug":"energia-2.s2.p1","orden":1,"grupo":"energia-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cuenta que ya sabés","cuerpo":["La energía que usa un aparato es su potencia por el tiempo que funciona. Si un aire acondicionado consume 1 kW y funciona 6 horas, usa 6 kWh ese día. En un mes de 30 días, 180 kWh.","La potencia figura en una etiqueta del aparato o en el manual, en watts (W). Para pasar a kW se divide por 1.000."]},"solucion":{}},{"slug":"energia-2.s2.p2","orden":2,"grupo":"energia-2.s2.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El aire acondicionado en enero","planteo":"Un aire acondicionado consume 1.000 W y funciona 6 horas por día durante 30 días.","pasos":["Potencia: 1.000 W = 1 kW.","Por día: 1 kW × 6 h = 6 kWh.","Por mes: 6 kWh × 30 = 180 kWh."],"resultado":"180 kWh en un mes solo de aire: puede ser tanto como todo el resto de la casa junto."},"solucion":{}},{"slug":"energia-2.s2.p3","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.000 W funciona 6 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"1 kW × 6 h × 30 días = 180 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p3.v2","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.300 W funciona 4 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":156,"tolerancia":3.12,"explicacion":"1,3 kW × 4 h × 30 días = 156 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p3.v3","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 800 W funciona 8 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":192,"tolerancia":3.84,"explicacion":"0,8 kW × 8 h × 30 días = 192 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p3.v4","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.500 W funciona 5 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":225,"tolerancia":4.5,"explicacion":"1,5 kW × 5 h × 30 días = 225 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p4","orden":4,"grupo":"energia-2.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los aparatos que se prenden y apagan solos","cuerpo":["La heladera no funciona a plena potencia todo el tiempo: su motor se prende y se apaga para mantener el frío. Por eso conviene mirar su consumo anual o diario, que figura en la etiqueta, en vez de su potencia. Una heladera eficiente usa del orden de 1 kWh por día.","Con el aire acondicionado pasa algo parecido: los equipos inverter regulan su potencia en vez de prender y apagar, y suelen usar bastante menos energía."]},"solucion":{}},{"slug":"energia-2.s2.p5","orden":5,"grupo":"energia-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La etiqueta de una heladera dice que consume 300 kWh por año. ¿Cuántos kWh usa por mes, en promedio?","unidad":"kWh por mes","decimales":1},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"300 ÷ 12 = 25 kWh por mes. El consumo anual de la etiqueta es la forma más confiable de comparar heladeras."}},{"slug":"energia-2.s2.p5.v2","orden":5,"grupo":"energia-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La etiqueta de una heladera dice que consume 450 kWh por año. ¿Cuántos kWh usa por mes, en promedio?","unidad":"kWh por mes","decimales":1},"solucion":{"valor":37.5,"tolerancia":0.75,"explicacion":"450 ÷ 12 = 37,5 kWh por mes. El consumo anual de la etiqueta es la forma más confiable de comparar heladeras."}},{"slug":"energia-2.s2.p5.v3","orden":5,"grupo":"energia-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La etiqueta de una heladera dice que consume 600 kWh por año. ¿Cuántos kWh usa por mes, en promedio?","unidad":"kWh por mes","decimales":1},"solucion":{"valor":50,"tolerancia":1,"explicacion":"600 ÷ 12 = 50 kWh por mes. El consumo anual de la etiqueta es la forma más confiable de comparar heladeras."}},{"slug":"energia-2.s2.p6","orden":6,"grupo":"energia-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Stand-by: poco por hora, mucho por año","cuerpo":["Un aparato en stand-by puede consumir de 1 a 10 W, o más en equipos viejos. Parece nada, pero funciona las 8.760 horas del año. Diez aparatos con 5 W de stand-by cada uno suman 50 W constantes: unos 438 kWh por año.","Según la Agencia Internacional de Energía, el stand-by llegó a representar una parte de la electricidad de los hogares de entre el 5 y el 10 % en muchos países."]},"solucion":{}},{"slug":"energia-2.s2.p7","orden":7,"grupo":"energia-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los aparatos en stand-by de una casa suman 30 W constantes. ¿Cuántos kWh usan en un año de 8.760 horas?","unidad":"kWh por año","decimales":1},"solucion":{"valor":262.8,"tolerancia":5.256,"explicacion":"0,03 kW × 8.760 h = 262,8 kWh por año. Poco por hora, mucho por año."}},{"slug":"energia-2.s2.p7.v2","orden":7,"grupo":"energia-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los aparatos en stand-by de una casa suman 50 W constantes. ¿Cuántos kWh usan en un año de 8.760 horas?","unidad":"kWh por año","decimales":1},"solucion":{"valor":438,"tolerancia":8.76,"explicacion":"0,05 kW × 8.760 h = 438 kWh por año. Poco por hora, mucho por año."}},{"slug":"energia-2.s2.p7.v3","orden":7,"grupo":"energia-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los aparatos en stand-by de una casa suman 20 W constantes. ¿Cuántos kWh usan en un año de 8.760 horas?","unidad":"kWh por año","decimales":1},"solucion":{"valor":175.2,"tolerancia":3.504,"explicacion":"0,02 kW × 8.760 h = 175,2 kWh por año. Poco por hora, mucho por año."}},{"slug":"energia-2.s2.p8","orden":8,"grupo":"energia-2.s2.p8","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená por consumo mensual típico, de más a menos (valores aproximados).","items":[{"id":"i1","texto":"Aire acondicionado 6 h diarias en verano"},{"id":"i2","texto":"Heladera con freezer"},{"id":"i3","texto":"Stand-by de toda la casa"},{"id":"i4","texto":"Cinco lámparas LED 5 h diarias"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El aire en verano es un gigante. El stand-by puede competir con la heladera. Las LED son chicas.","valores":{"i1":"≈ 180 kWh","i2":"≈ 30-45 kWh","i3":"≈ 15-35 kWh","i4":"≈ 7 kWh"}}},{"slug":"energia-2.s2.p9","orden":9,"grupo":"energia-2.s2.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un aparato de mucha potencia siempre consume más energía por mes que uno de poca potencia.","razones":[{"id":"r1","texto":"Porque la energía depende también de las horas de uso"},{"id":"r2","texto":"Porque la potencia es la energía mensual"},{"id":"r3","texto":"Porque los aparatos de mucha potencia no consumen"}]},"solucion":{"valor":false,"explicacion":"Depende de cuántas horas funciona. Un secador de pelo de 2.000 W usado 5 minutos por día consume menos que una heladera que funciona todo el día.","clave":["r1"]}},{"slug":"energia-2.s2.p10","orden":10,"grupo":"energia-2.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un secador de pelo de 2.000 W se usa 5 minutos por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":5,"tolerancia":0.05,"explicacion":"2 kW × 0,083 h × 30 = 5 kWh. Mucha potencia, poco tiempo."}},{"slug":"energia-2.s2.p10.v2","orden":10,"grupo":"energia-2.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un secador de pelo de 1.800 W se usa 10 minutos por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":9,"tolerancia":0.05,"explicacion":"1,8 kW × 0,167 h × 30 = 9 kWh. Mucha potencia, poco tiempo."}},{"slug":"energia-2.s2.p10.v3","orden":10,"grupo":"energia-2.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un secador de pelo de 2.200 W se usa 6 minutos por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":6.6,"tolerancia":0.05,"explicacion":"2,2 kW × 0,1 h × 30 = 6,6 kWh. Mucha potencia, poco tiempo."}},{"slug":"energia-2.s2.p11","orden":11,"grupo":"energia-2.s2.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué dato conviene mirar para comparar el consumo de dos heladeras?","opciones":[{"id":"o1","texto":"El consumo anual en kWh de la etiqueta"},{"id":"o2","texto":"La potencia del motor en watts"},{"id":"o3","texto":"El tamaño en litros solamente"},{"id":"o4","texto":"El color y el material de la puerta"}]},"solucion":{"clave":["o1"],"explicacion":"Como el motor se prende y apaga, la potencia sola no dice cuánto usa. El consumo anual sí.","por_opcion":{"o3":"El tamaño importa, pero dos heladeras iguales pueden consumir muy distinto."}}},{"slug":"energia-2.s2.p12","orden":12,"grupo":"energia-2.s2.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué reduce el consumo de una heladera? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Cerrar bien la puerta y no dejarla abierta"},{"id":"o2","texto":"Dejar espacio atrás para que ventile"},{"id":"o3","texto":"No meter comida caliente"},{"id":"o4","texto":"Revisar que el burlete cierre bien"},{"id":"o5","texto":"Ponerla al lado del horno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La heladera saca calor de adentro y lo tira afuera por atrás. Si le entra calor o no puede tirarlo, trabaja más."}},{"slug":"energia-2.s2.p13","orden":13,"grupo":"energia-2.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía de un aparato es su {{0}} por las {{1}} de uso; el stand-by consume poco por hora pero mucho por {{2}}.","banco":[{"id":"w1","texto":"potencia"},{"id":"w2","texto":"horas"},{"id":"w3","texto":"año"},{"id":"w4","texto":"tamaño"},{"id":"w5","texto":"watts"},{"id":"w6","texto":"minuto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La cuenta básica de la energía y su trampa más común."}},{"slug":"energia-2.s2.p14","orden":14,"grupo":"energia-2.s2.p14","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este razonamiento y marcá los errores.","segmentos":[{"id":"s1","texto":"El aire tiene 1.000 W y lo uso 6 horas: son 6 kWh por día."},{"id":"s2","texto":"La heladera tiene un motor de 150 W, así que usa 150 × 24 = 3,6 kWh por día."},{"id":"s3","texto":"El stand-by de 5 W por aparato no importa en un año."},{"id":"s4","texto":"El secador de 2.000 W usado 5 minutos consume poco por mes."}]},"solucion":{"clave":["s2","s3"],"explicacion":"Potencia por tiempo, pero con el tiempo real de funcionamiento.","por_opcion":{"s2":"El motor se prende y se apaga: el consumo real es mucho menor, mejor mirar la etiqueta.","s3":"Varios aparatos por 8.760 horas suman cientos de kWh."}}}]},{"slug":"energia-2.s3","orden":3,"tipo":"leccion","titulo_es":"Leer la factura de luz","bajada_es":"Qué dice cada parte, cómo comparar períodos y cómo pasar de la factura a kWh por día.","minutos":11,"pasos":[{"slug":"energia-2.s3.p1","orden":1,"grupo":"energia-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las partes de una factura","cuerpo":["Una factura de electricidad tiene el período facturado (las fechas entre dos lecturas del medidor), la lectura anterior y la actual, el consumo en kWh (la resta de las dos lecturas), los cargos (uno fijo y uno variable por kWh) y los impuestos.","El número clave para el ambiente es el consumo en kWh. El monto en pesos cambia por tarifas, subsidios e impuestos; los kWh dicen cuánta energía usó la casa."]},"solucion":{}},{"slug":"energia-2.s3.p2","orden":2,"grupo":"energia-2.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El medidor marcaba 45.320 kWh en la lectura anterior y 45.680 en la actual. ¿Cuántos kWh se consumieron?","unidad":"kWh","decimales":0},"solucion":{"valor":360,"tolerancia":7.2,"explicacion":"45.680 − 45.320 = 360 kWh. El consumo es la diferencia entre las dos lecturas."}},{"slug":"energia-2.s3.p3","orden":3,"grupo":"energia-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Comparar bien","cuerpo":["Para comparar dos facturas conviene pasar a kWh por día, porque los períodos no siempre tienen la misma cantidad de días. También conviene comparar con el mismo período del año anterior: julio con julio, enero con enero, porque el clima cambia mucho el consumo.","Muchas facturas traen un gráfico con los consumos de los últimos meses: es la herramienta más simple para ver si un cambio de hábito funcionó."]},"solucion":{}},{"slug":"energia-2.s3.p4","orden":4,"grupo":"energia-2.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una factura marca 360 kWh en un período de 60 días. ¿Cuántos kWh por día usó la casa? Redondeá a un decimal.","unidad":"kWh por día","decimales":1},"solucion":{"valor":6,"tolerancia":0.1,"explicacion":"360 ÷ 60 ≈ 6 kWh por día. Así se pueden comparar períodos de distinta duración."}},{"slug":"energia-2.s3.p4.v2","orden":4,"grupo":"energia-2.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una factura marca 420 kWh en un período de 61 días. ¿Cuántos kWh por día usó la casa? Redondeá a un decimal.","unidad":"kWh por día","decimales":1},"solucion":{"valor":6.9,"tolerancia":0.1,"explicacion":"420 ÷ 61 ≈ 6,9 kWh por día. Así se pueden comparar períodos de distinta duración."}},{"slug":"energia-2.s3.p4.v3","orden":4,"grupo":"energia-2.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una factura marca 250 kWh en un período de 30 días. ¿Cuántos kWh por día usó la casa? Redondeá a un decimal.","unidad":"kWh por día","decimales":1},"solucion":{"valor":8.3,"tolerancia":0.1,"explicacion":"250 ÷ 30 ≈ 8,3 kWh por día. Así se pueden comparar períodos de distinta duración."}},{"slug":"energia-2.s3.p5","orden":5,"grupo":"energia-2.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Con qué conviene comparar el consumo de la factura de enero para saber si la casa ahorró?","opciones":[{"id":"o1","texto":"Con el consumo de enero del año anterior"},{"id":"o2","texto":"Con el consumo de julio del mismo año"},{"id":"o3","texto":"Con el monto en pesos de diciembre"},{"id":"o4","texto":"Con la factura de enero de un vecino"}]},"solucion":{"clave":["o1"],"explicacion":"Mismo mes, mismo clima aproximado. Así la diferencia se explica por los hábitos, no por el tiempo.","por_opcion":{"o3":"El monto cambia por tarifas e impuestos; y diciembre tiene otro clima."}}},{"slug":"energia-2.s3.p6","orden":6,"grupo":"energia-2.s3.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la factura de este mes cuesta más pesos que la anterior, seguro la casa usó más energía.","razones":[{"id":"r1","texto":"Porque el precio puede cambiar aunque el consumo no"},{"id":"r2","texto":"Porque los pesos y los kWh son siempre proporcionales"},{"id":"r3","texto":"Porque las facturas no dicen los kWh"}]},"solucion":{"valor":false,"explicacion":"Puede haber subido la tarifa o cambiado un subsidio. Para saber si se usó más energía hay que mirar los kWh, y mejor por día.","clave":["r1"]}},{"slug":"energia-2.s3.p7","orden":7,"grupo":"energia-2.s3.p7","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Comparar dos veranos","planteo":"Enero del año pasado: 420 kWh en 31 días. Enero de este año: 360 kWh en 31 días. La familia cambió el aire acondicionado a 24 °C y cerró cortinas de día.","pasos":["Año pasado: 420 ÷ 31 ≈ 13,5 kWh por día.","Este año: 360 ÷ 31 ≈ 11,6 kWh por día.","Diferencia: 13,5 − 11,6 = 1,9 kWh por día, un 14 % menos."],"resultado":"Mismo mes, misma cantidad de días: el ahorro se debe a los hábitos. Así se verifica que un cambio funciona."},"solucion":{}},{"slug":"energia-2.s3.p8","orden":8,"grupo":"energia-2.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En enero del año pasado la casa usó 420 kWh y este enero 360 kWh (mismos días). ¿En qué porcentaje bajó el consumo? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":14,"tolerancia":1,"explicacion":"Bajó 60 kWh sobre 420: 60 ÷ 420 × 100 ≈ 14 %. Siempre sobre el valor original."}},{"slug":"energia-2.s3.p8.v2","orden":8,"grupo":"energia-2.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En enero del año pasado la casa usó 500 kWh y este enero 400 kWh (mismos días). ¿En qué porcentaje bajó el consumo? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":20,"tolerancia":1,"explicacion":"Bajó 100 kWh sobre 500: 100 ÷ 500 × 100 ≈ 20 %. Siempre sobre el valor original."}},{"slug":"energia-2.s3.p8.v3","orden":8,"grupo":"energia-2.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En enero del año pasado la casa usó 300 kWh y este enero 270 kWh (mismos días). ¿En qué porcentaje bajó el consumo? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":10,"tolerancia":1,"explicacion":"Bajó 30 kWh sobre 300: 30 ÷ 300 × 100 ≈ 10 %. Siempre sobre el valor original."}},{"slug":"energia-2.s3.p9","orden":9,"grupo":"energia-2.s3.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para revisar si un cambio de hábito funcionó.","items":[{"id":"i1","texto":"Anotar el consumo en kWh del mismo mes del año anterior"},{"id":"i2","texto":"Aplicar el cambio de hábito durante el mes"},{"id":"i3","texto":"Leer el consumo en kWh de la nueva factura"},{"id":"i4","texto":"Pasar los dos consumos a kWh por día"},{"id":"i5","texto":"Comparar y calcular la diferencia en porcentaje"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Medir antes, cambiar, medir después y comparar en la misma unidad: el método del tronco aplicado a la factura."}},{"slug":"energia-2.s3.p10","orden":10,"grupo":"energia-2.s3.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este dato de la factura dice cuánta energía usó la casa o no?","grupos":[{"id":"g1","nombre":"Dice cuánta energía usó"},{"id":"g2","nombre":"No dice cuánta energía usó"}],"items":[{"id":"i1","texto":"Consumo en kWh"},{"id":"i2","texto":"Monto total en pesos"},{"id":"i3","texto":"Lecturas del medidor"},{"id":"i4","texto":"Impuestos provinciales"},{"id":"i5","texto":"Gráfico de consumos por mes"},{"id":"i6","texto":"Fecha de vencimiento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La energía está en los kWh y las lecturas. Lo demás es plata y administración."}},{"slug":"energia-2.s3.p11","orden":11,"grupo":"energia-2.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término de la factura con su significado.","izquierda":[{"id":"a1","texto":"Período"},{"id":"a2","texto":"Lectura actual"},{"id":"a3","texto":"Consumo"},{"id":"a4","texto":"Cargo fijo"}],"derecha":[{"id":"b1","texto":"Fechas entre dos lecturas"},{"id":"b2","texto":"Número que marca hoy el medidor"},{"id":"b3","texto":"Diferencia entre lecturas en kWh"},{"id":"b4","texto":"Monto que se paga aunque no se consuma"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro términos que alcanzan para entender cualquier factura de electricidad."}},{"slug":"energia-2.s3.p12","orden":12,"grupo":"energia-2.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estas conclusiones sobre una factura y marcá las equivocadas.","segmentos":[{"id":"s1","texto":"Este bimestre usamos 360 kWh, unos 6 kWh por día."},{"id":"s2","texto":"Julio consumió más que enero: seguro alguien dejó luces prendidas."},{"id":"s3","texto":"La factura vino más cara, así que usamos más kWh."},{"id":"s4","texto":"Comparamos con el mismo bimestre del año pasado y bajamos un 10 %."}]},"solucion":{"clave":["s2","s3"],"explicacion":"Comparar bien es mismo período, misma unidad, y kWh en vez de pesos.","por_opcion":{"s2":"Puede deberse al clima; hay que comparar julio con julio.","s3":"El precio puede subir por la tarifa aunque el consumo baje."}}},{"slug":"energia-2.s3.p13","orden":13,"grupo":"energia-2.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para comparar facturas conviene pasar a kWh por {{0}} y comparar con el mismo {{1}} del año anterior.","banco":[{"id":"w1","texto":"día"},{"id":"w2","texto":"mes"},{"id":"w3","texto":"peso"},{"id":"w4","texto":"vecino"},{"id":"w5","texto":"minuto"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Así se ve el efecto de los hábitos y no el del clima o el de la tarifa."}},{"slug":"energia-2.s3.p14","orden":14,"grupo":"energia-2.s3.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá: una casa usa 6 kWh por día. ¿Cuántos kWh usa por año?","min":500,"max":5000,"paso":10,"unidad":"kWh","escala":"lineal"},"solucion":{"valor":2190,"banda":"lineal","explicacion":"6 × 365 = 2.190 kWh por año. Un orden de magnitud típico para una casa argentina con gas."}}]},{"slug":"energia-2.s4","orden":4,"tipo":"leccion","titulo_es":"La etiqueta de eficiencia","bajada_es":"Las letras y los números de la etiqueta, y cómo usarlos para elegir un aparato que gaste menos toda su vida.","minutos":11,"pasos":[{"slug":"energia-2.s4.p1","orden":1,"grupo":"energia-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué dice la etiqueta","cuerpo":["En Argentina, muchos aparatos se venden con una etiqueta de eficiencia energética: heladeras, lavarropas, aires acondicionados, lámparas, termotanques y otros. Tiene una escala de letras, de la más eficiente (A o sus variantes con signos +) a la menos eficiente, y el consumo de energía estimado, normalmente por año.","La letra sirve para una comparación rápida; el consumo en kWh por año sirve para hacer cuentas. Dos heladeras con la misma letra pueden consumir distinto si tienen distinto tamaño."]},"solucion":{}},{"slug":"energia-2.s4.p2","orden":2,"grupo":"energia-2.s4.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En la etiqueta de una heladera, ¿qué dato permite calcular cuánto va a consumir?","opciones":[{"id":"o1","texto":"El consumo de energía en kWh por año"},{"id":"o2","texto":"La letra de la clase de eficiencia"},{"id":"o3","texto":"El nombre del fabricante"},{"id":"o4","texto":"El volumen del freezer en litros"}]},"solucion":{"clave":["o1"],"explicacion":"La letra orienta; el número es lo que se multiplica por el precio del kWh o por años de uso.","por_opcion":{"o3":"La marca no dice cuánto consume: la etiqueta sí."}}},{"slug":"energia-2.s4.p3","orden":3,"grupo":"energia-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El precio de toda la vida","cuerpo":["Un aparato se paga dos veces: cuando se compra y cada mes en la factura. Una heladera dura 10 o 15 años. Si una consume 200 kWh por año más que otra, en 12 años son 2.400 kWh más.","Por eso conviene comparar el costo total: precio de compra más energía durante la vida útil. A veces el aparato un poco más caro es el más barato."]},"solucion":{}},{"slug":"energia-2.s4.p4","orden":4,"grupo":"energia-2.s4.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Dos heladeras","planteo":"Heladera A: consume 300 kWh por año. Heladera B: consume 500 kWh por año. Las dos duran 12 años.","pasos":["Diferencia anual: 500 − 300 = 200 kWh.","En 12 años: 200 × 12 = 2.400 kWh.","Si cada kWh cuesta $100, son $240.000 de diferencia en energía."],"resultado":"Si la heladera A cuesta menos de $240.000 más que la B, termina siendo más barata. Y además emite menos."},"solucion":{}},{"slug":"energia-2.s4.p5","orden":5,"grupo":"energia-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera consume 300 kWh por año y otra 500. Si duran 12 años, ¿cuántos kWh más usa la menos eficiente en toda su vida?","unidad":"kWh","decimales":0},"solucion":{"valor":2400,"tolerancia":48,"explicacion":"(500 − 300) × 12 = 2.400 kWh. La diferencia de consumo se repite todos los años de uso."}},{"slug":"energia-2.s4.p5.v2","orden":5,"grupo":"energia-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera consume 250 kWh por año y otra 400. Si duran 10 años, ¿cuántos kWh más usa la menos eficiente en toda su vida?","unidad":"kWh","decimales":0},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"(400 − 250) × 10 = 1.500 kWh. La diferencia de consumo se repite todos los años de uso."}},{"slug":"energia-2.s4.p5.v3","orden":5,"grupo":"energia-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera consume 350 kWh por año y otra 450. Si duran 15 años, ¿cuántos kWh más usa la menos eficiente en toda su vida?","unidad":"kWh","decimales":0},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"(450 − 350) × 15 = 1.500 kWh. La diferencia de consumo se repite todos los años de uso."}},{"slug":"energia-2.s4.p6","orden":6,"grupo":"energia-2.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera usa 2.400 kWh más que otra en toda su vida. Si el kWh cuesta $100, ¿cuántos pesos más cuesta usarla?","unidad":"$","decimales":0},"solucion":{"valor":240000,"tolerancia":4800,"explicacion":"2.400 × 100 = $240.000. Ese es el \"precio escondido\" de la heladera menos eficiente."}},{"slug":"energia-2.s4.p6.v2","orden":6,"grupo":"energia-2.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera usa 1.500 kWh más que otra en toda su vida. Si el kWh cuesta $120, ¿cuántos pesos más cuesta usarla?","unidad":"$","decimales":0},"solucion":{"valor":180000,"tolerancia":3600,"explicacion":"1.500 × 120 = $180.000. Ese es el \"precio escondido\" de la heladera menos eficiente."}},{"slug":"energia-2.s4.p6.v3","orden":6,"grupo":"energia-2.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera usa 1.500 kWh más que otra en toda su vida. Si el kWh cuesta $150, ¿cuántos pesos más cuesta usarla?","unidad":"$","decimales":0},"solucion":{"valor":225000,"tolerancia":4500,"explicacion":"1.500 × 150 = $225.000. Ese es el \"precio escondido\" de la heladera menos eficiente."}},{"slug":"energia-2.s4.p7","orden":7,"grupo":"energia-2.s4.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si dos aparatos tienen la misma letra de eficiencia, consumen lo mismo.","razones":[{"id":"r1","texto":"Porque el consumo también depende del tamaño y las funciones"},{"id":"r2","texto":"Porque la letra indica el consumo exacto"},{"id":"r3","texto":"Porque las etiquetas no dicen el consumo"}]},"solucion":{"valor":false,"explicacion":"La letra compara con aparatos de su tipo y tamaño. Una heladera grande clase A puede consumir más que una chica clase A. Para comparar, el número de kWh.","clave":["r1"]}},{"slug":"energia-2.s4.p8","orden":8,"grupo":"energia-2.s4.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene mirar antes de comprar un aire acondicionado? Marcá todo lo útil.","opciones":[{"id":"o1","texto":"La clase de eficiencia de la etiqueta"},{"id":"o2","texto":"El consumo de energía estimado"},{"id":"o3","texto":"Si es inverter"},{"id":"o4","texto":"Que la potencia sea adecuada al tamaño del ambiente"},{"id":"o5","texto":"Que sea el más potente disponible, por las dudas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un equipo sobredimensionado cuesta más, consume de más y prende y apaga seguido. Tamaño justo y eficiente."}},{"slug":"energia-2.s4.p9","orden":9,"grupo":"energia-2.s4.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la etiqueta de eficiencia cambia un mercado entero.","items":[{"id":"i1","texto":"La etiqueta muestra cuánto consume cada aparato"},{"id":"i2","texto":"Los compradores eligen más los eficientes"},{"id":"i3","texto":"Los fabricantes compiten por mejores letras"},{"id":"i4","texto":"Los aparatos del mercado se vuelven más eficientes"},{"id":"i5","texto":"La etiqueta obliga a cada casa a consumir menos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La etiqueta no obliga a nadie, pero cambia lo que se elige, y eso cambia lo que se fabrica. Una palanca de sistema, como en el tronco."}},{"slug":"energia-2.s4.p10","orden":10,"grupo":"energia-2.s4.p10","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos aparatos por su costo total en 12 años, de más a menos. Precio de compra más energía a $100 por kWh.","items":[{"id":"i1","texto":"Heladera B: $500.000 y 500 kWh por año"},{"id":"i2","texto":"Heladera A: $700.000 y 300 kWh por año"},{"id":"i3","texto":"Heladera C: $800.000 y 200 kWh por año"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"La más barata en la vidriera es la más cara en la vida. Pasa seguido con los aparatos que funcionan todo el día.","valores":{"i1":"$1.100.000","i2":"$1.060.000","i3":"$1.040.000"}}},{"slug":"energia-2.s4.p11","orden":11,"grupo":"energia-2.s4.p11","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para qué aparato la etiqueta de eficiencia pesa más en la decisión?","grupos":[{"id":"g1","nombre":"Pesa mucho (funcionan muchas horas)"},{"id":"g2","nombre":"Pesa poco (funcionan pocas horas)"}],"items":[{"id":"i1","texto":"Heladera"},{"id":"i2","texto":"Secador de pelo"},{"id":"i3","texto":"Aire acondicionado"},{"id":"i4","texto":"Batidora"},{"id":"i5","texto":"Termotanque"},{"id":"i6","texto":"Tostadora"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cuanto más horas funciona un aparato, más importa su eficiencia. En los que se usan minutos, casi no cambia la cuenta."}},{"slug":"energia-2.s4.p12","orden":12,"grupo":"energia-2.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé lo que dice un vendedor y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Esta heladera es clase A y consume 280 kWh por año."},{"id":"s2","texto":"La otra es más barata, así que es la que más le conviene."},{"id":"s3","texto":"La etiqueta es obligatoria para las heladeras."},{"id":"s4","texto":"Todas las clase A consumen exactamente lo mismo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El precio de vidriera y la letra sola pueden engañar. El kWh por año, no.","por_opcion":{"s2":"Hay que sumar la energía de toda su vida, no solo el precio.","s4":"La letra depende del tipo y tamaño; el consumo en kWh puede variar."}}},{"slug":"energia-2.s4.p13","orden":13,"grupo":"energia-2.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un aparato se paga al {{0}} y cada mes en la {{1}}; por eso conviene comparar el costo {{2}}.","banco":[{"id":"w1","texto":"comprarlo"},{"id":"w2","texto":"factura"},{"id":"w3","texto":"total"},{"id":"w4","texto":"venderlo"},{"id":"w5","texto":"garantía"},{"id":"w6","texto":"inicial"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea del costo de toda la vida, en una línea."}}]},{"slug":"energia-2.s5","orden":5,"tipo":"leccion","titulo_es":"Calor y frío sin derrochar","bajada_es":"Termostatos, burletes, cortinas y sol: cómo estar a gusto usando mucha menos energía.","minutos":12,"pasos":[{"slug":"energia-2.s5.p1","orden":1,"grupo":"energia-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa como un balde con agujeros","cuerpo":["Calefaccionar en invierno es como llenar un balde con agujeros: el calor se escapa por el techo, las paredes, las ventanas y las rendijas. La estufa repone lo que se pierde. Tapar agujeros es más efectivo que poner una estufa más grande.","Las rendijas de puertas y ventanas dejan entrar aire frío; los burletes las cierran. Los techos sin aislar pierden mucho calor, porque el aire caliente sube. Las ventanas de vidrio simple pierden más que las paredes."]},"solucion":{}},{"slug":"energia-2.s5.p2","orden":2,"grupo":"energia-2.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Por dónde se escapa el calor de una casa en invierno? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Por el techo, sobre todo si no está aislado"},{"id":"o2","texto":"Por las rendijas de puertas y ventanas"},{"id":"o3","texto":"Por los vidrios simples de las ventanas"},{"id":"o4","texto":"Por las paredes"},{"id":"o5","texto":"Por las lámparas LED encendidas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Techo, paredes, ventanas y rendijas: los cuatro agujeros del balde."}},{"slug":"energia-2.s5.p3","orden":3,"grupo":"energia-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La temperatura justa","cuerpo":["La temperatura a la que se pone la calefacción importa mucho: cuanto más diferencia hay entre adentro y afuera, más rápido se escapa el calor. Se suele recomendar alrededor de 20 °C en invierno y, para el aire acondicionado, alrededor de 24 °C en verano.","Cada grado de más en la calefacción, o de menos en el aire, aumenta el consumo en varios puntos porcentuales. Abrigarse un poco más adentro o usar ventilador junto con el aire son cambios chicos con efecto grande."],"destacado":{"valor":"20 °C / 24 °C","texto":"son las temperaturas recomendadas para calefacción en invierno y aire en verano."}},"solucion":{}},{"slug":"energia-2.s5.p4","orden":4,"grupo":"energia-2.s5.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué cuesta más energía mantener la casa a 24 °C que a 20 °C en invierno?","opciones":[{"id":"o1","texto":"Porque con más diferencia, el calor se escapa más rápido"},{"id":"o2","texto":"Porque a más de 20 °C las estufas funcionan peor y se rompen"},{"id":"o3","texto":"Porque el aire caliente pesa más"},{"id":"o4","texto":"Porque la tarifa de gas se cobra más cara arriba de 20 °C"}]},"solucion":{"clave":["o1"],"explicacion":"La pérdida de calor crece con la diferencia de temperatura. Cuatro grados más pueden significar un aumento importante del consumo.","por_opcion":{"o3":"El aire caliente es más liviano y sube; lo que importa es la diferencia de temperatura."}}},{"slug":"energia-2.s5.p5","orden":5,"grupo":"energia-2.s5.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Poner el aire acondicionado a 17 °C enfría la habitación más rápido que ponerlo a 24 °C.","razones":[{"id":"r1","texto":"Porque la velocidad es la misma; solo sigue enfriando hasta más abajo"},{"id":"r2","texto":"Porque a 17 °C el equipo se apaga solo"},{"id":"r3","texto":"Porque a 24 °C el equipo no enfría"}]},"solucion":{"valor":false,"explicacion":"La mayoría de los equipos enfría a la misma velocidad; lo que cambia es hasta dónde sigue enfriando. A 17 °C sigue trabajando mucho más tiempo y gasta mucho más.","clave":["r1"]}},{"slug":"energia-2.s5.p6","orden":6,"grupo":"energia-2.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol como aliado","cuerpo":["En invierno, abrir cortinas en las ventanas donde da el sol durante el día deja entrar calor gratis; cerrarlas al atardecer ayuda a que no se escape. En verano, al revés: cerrar persianas y cortinas donde da el sol evita que la casa se caliente, y ventilar de noche con aire más fresco la enfría.","Árboles de hoja caduca del lado del sol dan sombra en verano y dejan pasar el sol en invierno. Es un ejemplo de diseño que trabaja con el clima en vez de contra él."]},"solucion":{}},{"slug":"energia-2.s5.p7","orden":7,"grupo":"energia-2.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida es para invierno o para verano?","grupos":[{"id":"g1","nombre":"Invierno"},{"id":"g2","nombre":"Verano"}],"items":[{"id":"i1","texto":"Abrir cortinas donde da el sol de día"},{"id":"i2","texto":"Cerrar persianas donde da el sol"},{"id":"i3","texto":"Cerrar cortinas gruesas al atardecer"},{"id":"i4","texto":"Ventilar de noche con aire fresco"},{"id":"i5","texto":"Colocar burletes en las ventanas"},{"id":"i6","texto":"Usar ventilador de techo con el aire a 24 °C"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las mismas cortinas y ventanas sirven en las dos estaciones, usadas al revés."}},{"slug":"energia-2.s5.p8","orden":8,"grupo":"energia-2.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un burlete ahorra gas.","items":[{"id":"i1","texto":"El burlete tapa la rendija de la ventana"},{"id":"i2","texto":"Entra menos aire frío de afuera"},{"id":"i3","texto":"La habitación pierde menos calor"},{"id":"i4","texto":"La estufa funciona menos tiempo para mantener la temperatura"},{"id":"i5","texto":"Se quema menos gas"},{"id":"i6","texto":"El burlete calienta el aire de la habitación"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una medida barata que actúa sobre la pérdida, no sobre la fuente. Tapar agujeros del balde."}},{"slug":"energia-2.s5.p9","orden":9,"grupo":"energia-2.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con su solución.","izquierda":[{"id":"a1","texto":"Rendijas en la puerta"},{"id":"a2","texto":"Techo sin aislar"},{"id":"a3","texto":"Sol fuerte en verano sobre la ventana"},{"id":"a4","texto":"Aire acondicionado a 18 °C"}],"derecha":[{"id":"b1","texto":"Burlete"},{"id":"b2","texto":"Aislante en el entretecho"},{"id":"b3","texto":"Persiana o toldo exterior"},{"id":"b4","texto":"Subirlo a 24 °C y usar ventilador"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada pérdida tiene su tapón. Algunos son gratis, otros una inversión."}},{"slug":"energia-2.s5.p10","orden":10,"grupo":"energia-2.s5.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ventilar sin tirar el calor","cuerpo":["Ventilar es necesario: renueva el aire, saca humedad y, con estufas a gas, es una cuestión de seguridad. Las estufas y calefones que no son de tiro balanceado necesitan ventilación permanente, porque pueden producir monóxido de carbono, un gas invisible y mortal.","Para ventilar sin perder calor conviene abrir bien las ventanas durante unos pocos minutos, en vez de dejarlas entreabiertas durante horas."]},"solucion":{}},{"slug":"energia-2.s5.p11","orden":11,"grupo":"energia-2.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la forma más eficiente de ventilar una habitación en invierno?","opciones":[{"id":"o1","texto":"Abrir bien la ventana unos pocos minutos"},{"id":"o2","texto":"Dejar la ventana entreabierta toda la tarde"},{"id":"o3","texto":"No ventilar nunca para no perder calor"},{"id":"o4","texto":"Abrir la puerta de entrada durante una hora"}]},"solucion":{"clave":["o1"],"explicacion":"Unos minutos con la ventana bien abierta renuevan el aire sin enfriar paredes y muebles, que guardan el calor.","por_opcion":{"o3":"Ventilar es necesario por la salud, y con estufas a gas, por seguridad."}}},{"slug":"energia-2.s5.p12","orden":12,"grupo":"energia-2.s5.p12","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una casa tiene estufas a gas que no son de tiro balanceado, tapar todas las rejillas de ventilación es una buena forma de ahorrar.","razones":[{"id":"r1","texto":"Porque sin ventilación se puede acumular monóxido de carbono"},{"id":"r2","texto":"Porque las rejillas no dejan pasar aire"},{"id":"r3","texto":"Porque tapar rejillas aumenta el consumo de luz"}]},"solucion":{"valor":false,"explicacion":"Es peligroso: esas estufas necesitan aire y pueden producir monóxido de carbono. Las rejillas de ventilación nunca se tapan.","clave":["r1"]}},{"slug":"energia-2.s5.p13","orden":13,"grupo":"energia-2.s5.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los que son peligrosos o equivocados.","segmentos":[{"id":"s1","texto":"Poné burletes en las ventanas antes del invierno."},{"id":"s2","texto":"Tapá las rejillas de ventilación para que no entre frío."},{"id":"s3","texto":"Poné el aire a 16 °C para que enfríe más rápido."},{"id":"s4","texto":"Cerrá persianas donde da el sol en verano."}]},"solucion":{"clave":["s2","s3"],"explicacion":"Ahorrar energía nunca a costa de la seguridad: las rejillas no se tocan.","por_opcion":{"s2":"Las rejillas son obligatorias con artefactos a gas: evitan intoxicaciones por monóxido de carbono.","s3":"No enfría más rápido: solo sigue enfriando más y gasta mucho más."}}},{"slug":"energia-2.s5.p14","orden":14,"grupo":"energia-2.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Se recomienda calefaccionar a unos {{0}} °C y usar el aire a unos {{1}} °C; cada grado de diferencia {{2}} el consumo.","banco":[{"id":"w1","texto":"20"},{"id":"w2","texto":"24"},{"id":"w3","texto":"aumenta"},{"id":"w4","texto":"26"},{"id":"w5","texto":"16"},{"id":"w6","texto":"reduce"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Dos números para recordar y una regla general."}}]},{"slug":"energia-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la energía en casa","bajada_es":"Usos, aparatos, factura, etiqueta y clima de la casa, mezclados.","minutos":8,"pasos":[{"slug":"energia-2.s6.p1","orden":1,"grupo":"energia-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La energía en casa». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la factura de los Giménez","bajada_es":"Una familia de Rosario recibe una factura de verano muy alta. Encontrá dónde se va la energía y armá el plan.","minutos":10,"pasos":[{"slug":"energia-2.s7.p1","orden":1,"grupo":"energia-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa de los Giménez","cuerpo":["Los Giménez son cuatro. Su factura de enero marca 540 kWh en 30 días; la de enero del año anterior, 450 kWh en 30 días. Este año compraron un segundo aire acondicionado de 1.200 W que usan 6 horas por día, y lo ponen a 18 °C.","Su heladera tiene 18 años y según una medición consume 2 kWh por día. En la casa hay un televisor, un decodificador, una consola y dos cargadores enchufados todo el tiempo, con unos 40 W de stand-by en total."]},"solucion":{}},{"slug":"energia-2.s7.p2","orden":2,"grupo":"energia-2.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por mes usa el segundo aire acondicionado? (30 días)","unidad":"kWh","decimales":0,"contexto":"Aire de 1.200 W, 6 horas por día, 30 días."},"solucion":{"valor":216,"tolerancia":4.32,"explicacion":"1,2 kW × 6 h × 30 días = 216 kWh por mes. Solo ese equipo es casi la mitad de la factura."}},{"slug":"energia-2.s7.p3","orden":3,"grupo":"energia-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje subió el consumo respecto de enero del año anterior?","unidad":"%","decimales":0,"contexto":"Enero pasado: 450 kWh. Este enero: 540 kWh. Mismos días."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"Subió 540 − 450 = 90 kWh sobre 450: 90 ÷ 450 × 100 = 20 %."}},{"slug":"energia-2.s7.p4","orden":4,"grupo":"energia-2.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por mes usa el stand-by de la casa? (40 W, 30 días de 24 horas)","unidad":"kWh","decimales":1,"contexto":"40 W de stand-by constante."},"solucion":{"valor":28.8,"tolerancia":0.5760000000000001,"explicacion":"0,04 kW × 24 h × 30 = 28,8 kWh por mes. Casi lo mismo que una heladera nueva y eficiente."}},{"slug":"energia-2.s7.p5","orden":5,"grupo":"energia-2.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas posibles según cuántos kWh por mes ahorrarían, de más a menos (estimaciones).","items":[{"id":"i1","texto":"Subir los aires de 18 °C a 24 °C y cerrar persianas"},{"id":"i2","texto":"Cambiar la heladera vieja (2 kWh/día) por una de 1 kWh/día"},{"id":"i3","texto":"Cortar el stand-by con una zapatilla con interruptor"},{"id":"i4","texto":"Cambiar las 3 lámparas que quedaban por LED"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El aire es el gigante del verano. La heladera y el stand-by vienen después y suman. Las lámparas, al final.","valores":{"i1":"≈ 60-90 kWh","i2":"≈ 30 kWh","i3":"≈ 20-25 kWh","i4":"≈ 5 kWh"}}},{"slug":"energia-2.s7.p6","orden":6,"grupo":"energia-2.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La familia quiere un solo cambio para este mismo mes, sin gastar plata. ¿Cuál conviene?","opciones":[{"id":"o1","texto":"Aires a 24 °C y persianas cerradas de día"},{"id":"o2","texto":"Comprar una heladera nueva de clase A esta semana"},{"id":"o3","texto":"Cambiar todas las lámparas a LED"},{"id":"o4","texto":"Instalar paneles solares en todo el techo de la casa"}]},"solucion":{"clave":["o1"],"explicacion":"Sin gastar plata y con efecto inmediato: el termostato y las persianas atacan el uso más grande del verano.","por_opcion":{"o3":"Ya casi todas son LED: el ahorro sería mínimo comparado con el aire."}}},{"slug":"energia-2.s7.p7","orden":7,"grupo":"energia-2.s7.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La heladera vieja consume 2 kWh por día y una nueva consumiría 1 kWh por día. Con el kWh a $100, ¿cuántos pesos por año ahorraría la nueva? (365 días)","unidad":"$","decimales":0},"solucion":{"valor":36500,"tolerancia":730,"explicacion":"Ahorra 1 kWh por día: 365 kWh por año × $100 = $36.500 por año. En 10 años de vida útil, diez veces eso."}},{"slug":"energia-2.s7.p7.v2","orden":7,"grupo":"energia-2.s7.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La heladera vieja consume 2 kWh por día y una nueva consumiría 1 kWh por día. Con el kWh a $120, ¿cuántos pesos por año ahorraría la nueva? (365 días)","unidad":"$","decimales":0},"solucion":{"valor":43800,"tolerancia":876,"explicacion":"Ahorra 1 kWh por día: 365 kWh por año × $120 = $43.800 por año. En 10 años de vida útil, diez veces eso."}},{"slug":"energia-2.s7.p7.v3","orden":7,"grupo":"energia-2.s7.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La heladera vieja consume 2 kWh por día y una nueva consumiría 1 kWh por día. Con el kWh a $150, ¿cuántos pesos por año ahorraría la nueva? (365 días)","unidad":"$","decimales":0},"solucion":{"valor":54750,"tolerancia":1095,"explicacion":"Ahorra 1 kWh por día: 365 kWh por año × $150 = $54.750 por año. En 10 años de vida útil, diez veces eso."}},{"slug":"energia-2.s7.p8","orden":8,"grupo":"energia-2.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La familia escribe su plan. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Vamos a poner los aires a 24 °C y usar el ventilador de techo."},{"id":"s2","texto":"Desenchufamos la heladera de noche para compensar."},{"id":"s3","texto":"Juntamos los aparatos del stand-by en una zapatilla con interruptor."},{"id":"s4","texto":"Comparamos la próxima factura con la de diciembre para ver el ahorro."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan ataca el uso grande, no pone en riesgo la comida y se verifica comparando bien.","por_opcion":{"s2":"Se corta el frío, se arruina la comida y al volver consume más.","s4":"Hay que comparar con el mismo mes del año anterior y en kWh por día."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-3","rama":"energia","orden":3,"nivel":2,"titulo_es":"De dónde sale la electricidad","bajada_es":"Detrás de cada enchufe hay turbinas, represas, parques eólicos, centrales nucleares y miles de kilómetros de cables. Cómo funciona el sistema que te da luz.","objetivos_es":["Explicar cómo se genera electricidad con distintas fuentes","Describir la matriz eléctrica argentina y cómo cambia","Seguir el recorrido de la electricidad por la red de transmisión y distribución","Interpretar la curva de demanda y el problema de los picos","Calcular las emisiones de un consumo eléctrico con un factor de emisión"],"repasa":["energia-1","energia-2","tronco-2"],"requiere_tronco":2,"fuentes":["cammesa","iea-energia","owid-energia","ley-27424-generacion","irena"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-3.s1","orden":1,"tipo":"leccion","titulo_es":"Cómo se genera la electricidad","bajada_es":"Turbinas, generadores y paneles: las distintas formas de convertir energía en electricidad.","minutos":11,"pasos":[{"slug":"energia-3.s1.p1","orden":1,"grupo":"energia-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hacer girar un imán","cuerpo":["Casi toda la electricidad del mundo se produce igual: algo hace girar una turbina, y la turbina mueve un generador, donde un imán gira dentro de bobinas de cobre y produce corriente eléctrica. Lo que cambia es qué hace girar la turbina.","En una central térmica, es el vapor o los gases calientes de quemar gas, carbón o gasoil. En una represa, el agua que cae. En un aerogenerador, el viento. En una central nuclear, el vapor calentado por la fisión del uranio."]},"solucion":{}},{"slug":"energia-3.s1.p2","orden":2,"grupo":"energia-3.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada central con lo que hace girar su turbina.","izquierda":[{"id":"a1","texto":"Central térmica a gas"},{"id":"a2","texto":"Represa hidroeléctrica"},{"id":"a3","texto":"Aerogenerador"},{"id":"a4","texto":"Central nuclear"}],"derecha":[{"id":"b1","texto":"Gases calientes de la combustión"},{"id":"b2","texto":"Agua que cae"},{"id":"b3","texto":"Viento"},{"id":"b4","texto":"Vapor calentado por la fisión del uranio"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas fuentes, un mismo principio: hacer girar un generador."}},{"slug":"energia-3.s1.p3","orden":3,"grupo":"energia-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La excepción: el panel solar","cuerpo":["Los paneles solares fotovoltaicos no tienen turbina ni partes que giren: la luz del sol, al llegar a un material semiconductor como el silicio, libera electrones y genera corriente directamente. Por eso casi no tienen mantenimiento mecánico y se pueden instalar en un techo.","La corriente de los paneles es continua; un equipo llamado inversor la transforma en corriente alterna, la que usa la red."]},"solucion":{}},{"slug":"energia-3.s1.p4","orden":4,"grupo":"energia-3.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta forma de generar usa una turbina o no?","grupos":[{"id":"g1","nombre":"Usa turbina"},{"id":"g2","nombre":"No usa turbina"}],"items":[{"id":"i1","texto":"Central térmica de ciclo combinado"},{"id":"i2","texto":"Panel solar fotovoltaico en un techo"},{"id":"i3","texto":"Represa de Yacyretá"},{"id":"i4","texto":"Parque solar en la Puna"},{"id":"i5","texto":"Parque eólico"},{"id":"i6","texto":"Central nuclear Atucha II"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g1"},"explicacion":"La fotovoltaica es la gran excepción: convierte luz en electricidad sin movimiento."}},{"slug":"energia-3.s1.p5","orden":5,"grupo":"energia-3.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un panel solar genera electricidad haciendo girar una pequeña turbina con el calor del sol.","razones":[{"id":"r1","texto":"Porque la luz genera corriente directamente en el semiconductor"},{"id":"r2","texto":"Porque los paneles tienen un motor adentro"},{"id":"r3","texto":"Porque los paneles queman el aire caliente"}]},"solucion":{"valor":false,"explicacion":"Los paneles fotovoltaicos no tienen partes móviles: la luz libera electrones en un semiconductor y eso genera corriente directamente.","clave":["r1"]}},{"slug":"energia-3.s1.p6","orden":6,"grupo":"energia-3.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una central térmica a gas.","items":[{"id":"i1","texto":"Se quema gas natural"},{"id":"i2","texto":"Los gases calientes hacen girar una turbina"},{"id":"i3","texto":"La turbina mueve el generador"},{"id":"i4","texto":"El generador produce electricidad"},{"id":"i5","texto":"La electricidad sale a la red de alta tensión"},{"id":"i6","texto":"El gas se convierte directamente en electricidad sin girar nada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Química a calor, calor a movimiento, movimiento a electricidad: las transformaciones de la unidad 1."}},{"slug":"energia-3.s1.p7","orden":7,"grupo":"energia-3.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ciclo combinado","cuerpo":["Una central térmica común aprovecha alrededor de un tercio de la energía del combustible. Las de ciclo combinado usan los gases calientes para mover una turbina y, además, aprovechan el calor que queda para producir vapor y mover otra: así llegan a aprovechar alrededor del 55 al 60 %.","Por eso, con el mismo gas, una central de ciclo combinado produce mucha más electricidad y emite menos por kWh."]},"solucion":{}},{"slug":"energia-3.s1.p8","orden":8,"grupo":"energia-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 100 unidades de energía de gas, ¿cuántas unidades más de electricidad produce una central de ciclo combinado (58 %) que una térmica común (35 %)?","unidad":"unidades","decimales":1},"solucion":{"valor":23,"tolerancia":0.46,"explicacion":"Común: 100 × 0,35 = 35. Ciclo combinado: 100 × 0,58 = 58. Diferencia: 23 unidades más con el mismo gas."}},{"slug":"energia-3.s1.p8.v2","orden":8,"grupo":"energia-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 200 unidades de energía de gas, ¿cuántas unidades más de electricidad produce una central de ciclo combinado (58 %) que una térmica común (35 %)?","unidad":"unidades","decimales":1},"solucion":{"valor":46,"tolerancia":0.92,"explicacion":"Común: 200 × 0,35 = 70. Ciclo combinado: 200 × 0,58 = 116. Diferencia: 46 unidades más con el mismo gas."}},{"slug":"energia-3.s1.p8.v3","orden":8,"grupo":"energia-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 150 unidades de energía de gas, ¿cuántas unidades más de electricidad produce una central de ciclo combinado (58 %) que una térmica común (35 %)?","unidad":"unidades","decimales":1},"solucion":{"valor":34.5,"tolerancia":0.6900000000000001,"explicacion":"Común: 150 × 0,35 = 52,5. Ciclo combinado: 150 × 0,58 = 87. Diferencia: 34,5 unidades más con el mismo gas."}},{"slug":"energia-3.s1.p9","orden":9,"grupo":"energia-3.s1.p9","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas centrales por la eficiencia típica con que convierten su fuente en electricidad, de más a menos.","items":[{"id":"i1","texto":"Represa hidroeléctrica"},{"id":"i2","texto":"Central de ciclo combinado"},{"id":"i3","texto":"Central térmica común"},{"id":"i4","texto":"Panel solar comercial"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La eficiencia no lo es todo: el sol es gratis e inagotable, aunque el panel aproveche una parte chica.","valores":{"i1":"≈ 85-90 %","i2":"≈ 55-60 %","i3":"≈ 30-40 %","i4":"≈ 20 % de la luz que recibe"}}},{"slug":"energia-3.s1.p10","orden":10,"grupo":"energia-3.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué fuentes generan electricidad sin emitir CO₂ al funcionar? Marcá todas.","opciones":[{"id":"o1","texto":"Represa hidroeléctrica"},{"id":"o2","texto":"Parque eólico"},{"id":"o3","texto":"Central nuclear"},{"id":"o4","texto":"Paneles solares"},{"id":"o5","texto":"Central térmica a gas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Hidro, eólica, nuclear y solar no emiten CO₂ al generar, aunque todas tienen impactos al construirse."}},{"slug":"energia-3.s1.p11","orden":11,"grupo":"energia-3.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué equipo convierte la corriente continua de los paneles solares en la corriente alterna de la red?","opciones":[{"id":"o1","texto":"El inversor"},{"id":"o2","texto":"El medidor de luz"},{"id":"o3","texto":"La turbina"},{"id":"o4","texto":"El disyuntor diferencial"}]},"solucion":{"clave":["o1"],"explicacion":"Sin inversor, la electricidad de los paneles no podría usarse en la casa ni volcarse a la red.","por_opcion":{"o3":"Los paneles no tienen turbina: la conversión la hace un equipo electrónico."}}},{"slug":"energia-3.s1.p12","orden":12,"grupo":"energia-3.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En una represa, el agua que cae hace girar una turbina."},{"id":"s2","texto":"Las centrales nucleares queman uranio como si fuera carbón."},{"id":"s3","texto":"Los aerogeneradores convierten el viento en movimiento y luego en electricidad."},{"id":"s4","texto":"Una central de ciclo combinado es menos eficiente que una térmica común."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer cómo funciona cada central ayuda a entender sus ventajas y límites.","por_opcion":{"s2":"No hay combustión: la fisión del uranio libera calor que produce vapor.","s4":"Es más eficiente: aprovecha el calor dos veces."}}},{"slug":"energia-3.s1.p13","orden":13,"grupo":"energia-3.s1.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Casi toda la electricidad se genera haciendo girar un {{0}}; los paneles solares son la excepción porque convierten la {{1}} directamente; y el {{2}} adapta su corriente a la red.","banco":[{"id":"w1","texto":"generador"},{"id":"w2","texto":"luz"},{"id":"w3","texto":"inversor"},{"id":"w4","texto":"motor"},{"id":"w5","texto":"calor"},{"id":"w6","texto":"medidor"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El principio de la generación y su gran excepción."}}]},{"slug":"energia-3.s2","orden":2,"tipo":"leccion","titulo_es":"La matriz eléctrica argentina","bajada_es":"Gas, represas, uranio, viento y sol: de qué está hecha la electricidad del país y cómo cambia.","minutos":11,"pasos":[{"slug":"energia-3.s2.p1","orden":1,"grupo":"energia-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un sistema interconectado","cuerpo":["Casi todo el país está conectado al Sistema Argentino de Interconexión (SADI): una red de líneas de alta tensión que une centrales y ciudades de casi todas las provincias. CAMMESA es la empresa que administra ese sistema: decide, hora por hora, qué centrales generan para cubrir la demanda.","Así, la electricidad que llega a tu casa es una mezcla de lo que generan muchas centrales, a veces a cientos de kilómetros."]},"solucion":{}},{"slug":"energia-3.s2.p2","orden":2,"grupo":"energia-3.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De qué está hecha","cuerpo":["En los últimos años, algo más de la mitad de la electricidad argentina salió de centrales térmicas, sobre todo a gas natural. Las grandes represas —como Yacyretá, Salto Grande, El Chocón o Piedra del Águila— aportaron una parte que cambia mucho según las lluvias. Las centrales nucleares Atucha I, Atucha II y Embalse aportaron alrededor de un 5 a 8 %. Y las renovables, sobre todo eólica y solar, crecieron rápido en la última década."],"datos":{"tipo":"barras","titulo":"Generación eléctrica en Argentina por fuente (aproximado, años recientes)","unidad":"% del total","filas":[{"etiqueta":"Térmica (sobre todo gas)","valor":57},{"etiqueta":"Hidráulica (grandes represas)","valor":18},{"etiqueta":"Renovables (eólica, solar y otras)","valor":17},{"etiqueta":"Nuclear","valor":8}],"nota":"Valores aproximados redondeados a partir de datos de CAMMESA; cambian cada año con las lluvias y la demanda."}},"solucion":{}},{"slug":"energia-3.s2.p3","orden":3,"grupo":"energia-3.s2.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese gráfico, ordená las fuentes por su aporte a la electricidad argentina, de más a menos.","items":[{"id":"i1","texto":"Térmica, sobre todo gas"},{"id":"i2","texto":"Hidráulica"},{"id":"i3","texto":"Renovables como eólica y solar"},{"id":"i4","texto":"Nuclear"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El gas sigue siendo la base del sistema. Las renovables ya aportan casi tanto como las grandes represas.","valores":{"i1":"≈ 57 %","i2":"≈ 18 %","i3":"≈ 17 %","i4":"≈ 8 %"}}},{"slug":"energia-3.s2.p4","orden":4,"grupo":"energia-3.s2.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la electricidad argentina viene de fuentes que no emiten CO₂ al generar (hidráulica, nuclear y renovables), según ese gráfico.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":43,"banda":"lineal","explicacion":"18 + 8 + 17 = 43 %. Algo más de cuatro de cada diez kWh."}},{"slug":"energia-3.s2.p5","orden":5,"grupo":"energia-3.s2.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada central con su fuente.","izquierda":[{"id":"a1","texto":"Yacyretá"},{"id":"a2","texto":"Atucha II"},{"id":"a3","texto":"Parques eólicos de Chubut"},{"id":"a4","texto":"Cauchari, en Jujuy"}],"derecha":[{"id":"b1","texto":"Agua del río Paraná"},{"id":"b2","texto":"Uranio"},{"id":"b3","texto":"Viento patagónico"},{"id":"b4","texto":"Sol de la Puna"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una geografía diversa: agua en el noreste, viento en el sur, sol en el noroeste."}},{"slug":"energia-3.s2.p6","orden":6,"grupo":"energia-3.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué cambia de un año a otro","cuerpo":["La matriz no es fija. En años secos, las represas generan menos y hay que quemar más gas, como pasó durante la bajante del Paraná. En años lluviosos, al revés. Las renovables crecen por las leyes que las promueven y porque se abarataron: la Ley 27.191 fijó metas de participación de renovables, y la Ley 27.424 habilitó a usuarios a generar su propia energía y volcar excedentes a la red."]},"solucion":{}},{"slug":"energia-3.s2.p7","orden":7,"grupo":"energia-3.s2.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una sequía puede aumentar las emisiones de la electricidad.","items":[{"id":"i1","texto":"Llueve poco en la cuenca de los ríos"},{"id":"i2","texto":"Las represas generan menos electricidad"},{"id":"i3","texto":"CAMMESA despacha más centrales térmicas"},{"id":"i4","texto":"Se quema más gas"},{"id":"i5","texto":"Suben las emisiones por kWh"},{"id":"i6","texto":"Las represas emiten más CO₂ en la sequía"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Agua y energía están conectadas: la bajante del río se nota en la matriz eléctrica."}},{"slug":"energia-3.s2.p8","orden":8,"grupo":"energia-3.s2.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La matriz eléctrica argentina es siempre la misma, año tras año.","razones":[{"id":"r1","texto":"Porque depende de las lluvias, la demanda y las nuevas centrales"},{"id":"r2","texto":"Porque la ley fija un porcentaje exacto de cada fuente"},{"id":"r3","texto":"Porque solo hay centrales a gas"}]},"solucion":{"valor":false,"explicacion":"Cambia con las lluvias (más o menos hidro), con la demanda y con las nuevas centrales renovables que se suman.","clave":["r1"]}},{"slug":"energia-3.s2.p9","orden":9,"grupo":"energia-3.s2.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace CAMMESA? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Administra el mercado eléctrico mayorista"},{"id":"o2","texto":"Decide qué centrales generan en cada momento"},{"id":"o3","texto":"Publica datos de generación y demanda"},{"id":"o4","texto":"Construye todos los paneles solares de las casas"},{"id":"o5","texto":"Factura directamente la luz de cada hogar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"CAMMESA administra el sistema; las facturas de las casas las emiten las distribuidoras."}},{"slug":"energia-3.s2.p10","orden":10,"grupo":"energia-3.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué establece la Ley 27.424 de generación distribuida?","opciones":[{"id":"o1","texto":"Que los usuarios generen renovable y vuelquen excedentes"},{"id":"o2","texto":"Que todas las casas deben tener paneles solares por obligación"},{"id":"o3","texto":"Que se prohíben las centrales térmicas"},{"id":"o4","texto":"Que la electricidad es gratuita para quienes tienen paneles"}]},"solucion":{"clave":["o1"],"explicacion":"Un usuario con paneles puede consumir su propia energía y entregar lo que sobra a la red.","por_opcion":{"o3":"No prohíbe centrales: habilita a los usuarios a generar y conectarse a la red."}}},{"slug":"energia-3.s2.p11","orden":11,"grupo":"energia-3.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina genera unos 140 TWh de electricidad por año y las renovables aportan el 17 %, ¿cuántos TWh aportan?","unidad":"TWh","decimales":1},"solucion":{"valor":23.8,"tolerancia":0.47600000000000003,"explicacion":"140 × 17 ÷ 100 = 23,8 TWh: el consumo de millones de hogares, sin quemar combustible."}},{"slug":"energia-3.s2.p11.v2","orden":11,"grupo":"energia-3.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina genera unos 140 TWh de electricidad por año y las renovables aportan el 15 %, ¿cuántos TWh aportan?","unidad":"TWh","decimales":1},"solucion":{"valor":21,"tolerancia":0.42,"explicacion":"140 × 15 ÷ 100 = 21 TWh: el consumo de millones de hogares, sin quemar combustible."}},{"slug":"energia-3.s2.p11.v3","orden":11,"grupo":"energia-3.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina genera unos 140 TWh de electricidad por año y las renovables aportan el 20 %, ¿cuántos TWh aportan?","unidad":"TWh","decimales":1},"solucion":{"valor":28,"tolerancia":0.56,"explicacion":"140 × 20 ÷ 100 = 28 TWh: el consumo de millones de hogares, sin quemar combustible."}},{"slug":"energia-3.s2.p12","orden":12,"grupo":"energia-3.s2.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad que llega a tu casa sale siempre de la central más cercana.","razones":[{"id":"r1","texto":"Porque llega de un sistema interconectado con muchas centrales"},{"id":"r2","texto":"Porque cada barrio tiene su propia central"},{"id":"r3","texto":"Porque la electricidad no viaja por cables"}]},"solucion":{"valor":false,"explicacion":"Llega de un sistema interconectado: es una mezcla de lo que generan muchas centrales, algunas a cientos de kilómetros.","clave":["r1"]}},{"slug":"energia-3.s2.p13","orden":13,"grupo":"energia-3.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Buena parte de la electricidad argentina se genera con gas."},{"id":"s2","texto":"Las represas generan siempre lo mismo, llueva o no."},{"id":"s3","texto":"Argentina tiene tres centrales nucleares en funcionamiento."},{"id":"s4","texto":"Las renovables todavía no generan nada relevante en el país."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer la matriz permite entender el impacto de cada kWh que usamos.","por_opcion":{"s2":"Dependen de las lluvias: en sequías generan menos.","s4":"Ya aportan una parte importante, que creció rápido en la última década."}}},{"slug":"energia-3.s2.p14","orden":14,"grupo":"energia-3.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El sistema que conecta centrales y ciudades se llama {{0}}; lo administra {{1}}; y la fuente que más electricidad aporta en Argentina es el {{2}}.","banco":[{"id":"w1","texto":"SADI"},{"id":"w2","texto":"CAMMESA"},{"id":"w3","texto":"gas"},{"id":"w4","texto":"ENARGAS"},{"id":"w5","texto":"INTA"},{"id":"w6","texto":"carbón"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para entender la electricidad del país."}}]},{"slug":"energia-3.s3","orden":3,"tipo":"leccion","titulo_es":"La red: del generador al enchufe","bajada_es":"Alta tensión, transformadores, distribuidoras y pérdidas: el viaje de la electricidad.","minutos":11,"pasos":[{"slug":"energia-3.s3.p1","orden":1,"grupo":"energia-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Subir la tensión para viajar","cuerpo":["La electricidad viaja desde las centrales por líneas de alta tensión: cientos de miles de voltios. ¿Por qué tan alta? Porque a mayor tensión, para la misma potencia, circula menos corriente, y los cables se calientan menos: se pierde menos energía en el camino.","Cerca de las ciudades, las subestaciones bajan la tensión con transformadores, y las distribuidoras la llevan por la red de media y baja tensión hasta las casas, donde llega a 220 voltios."]},"solucion":{}},{"slug":"energia-3.s3.p2","orden":2,"grupo":"energia-3.s3.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido de la electricidad desde la central hasta tu casa.","items":[{"id":"i1","texto":"Se genera en la central"},{"id":"i2","texto":"Un transformador eleva la tensión"},{"id":"i3","texto":"Viaja por líneas de alta tensión"},{"id":"i4","texto":"Una subestación la baja cerca de la ciudad"},{"id":"i5","texto":"La distribuidora la lleva por el barrio hasta tu casa"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Subir para viajar lejos, bajar para usar. Transformadores en los dos extremos."}},{"slug":"energia-3.s3.p3","orden":3,"grupo":"energia-3.s3.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la electricidad viaja largas distancias en alta tensión?","opciones":[{"id":"o1","texto":"Porque así se pierde menos energía en los cables"},{"id":"o2","texto":"Porque así llega más rápido a las casas"},{"id":"o3","texto":"Porque los cables de alta tensión son más baratos"},{"id":"o4","texto":"Porque las casas usan alta tensión"}]},"solucion":{"clave":["o1"],"explicacion":"Menos corriente, menos calentamiento del cable, menos pérdidas.","por_opcion":{"o3":"El motivo principal es reducir las pérdidas, no el costo del cable."}}},{"slug":"energia-3.s3.p4","orden":4,"grupo":"energia-3.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las pérdidas","cuerpo":["Aun así, una parte de la energía se pierde en el camino: como calor en cables y transformadores (pérdidas técnicas) y, en algunos lugares, por conexiones irregulares o medidores que fallan (pérdidas no técnicas). En total, una parte relevante de la electricidad generada no llega a facturarse.","Por eso cada kWh que se ahorra en casa ahorra algo más en la central: también se evitan las pérdidas de transportarlo."]},"solucion":{}},{"slug":"energia-3.s3.p5","orden":5,"grupo":"energia-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central genera 100 MWh y en la red se pierde el 10 %. ¿Cuántos MWh llegan a los usuarios?","unidad":"MWh","decimales":1},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"100 × 0.9 = 90 MWh. Las pérdidas son energía generada, con sus emisiones, que no usa nadie."}},{"slug":"energia-3.s3.p5.v2","orden":5,"grupo":"energia-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central genera 250 MWh y en la red se pierde el 12 %. ¿Cuántos MWh llegan a los usuarios?","unidad":"MWh","decimales":1},"solucion":{"valor":220,"tolerancia":4.4,"explicacion":"250 × 0.88 = 220 MWh. Las pérdidas son energía generada, con sus emisiones, que no usa nadie."}},{"slug":"energia-3.s3.p5.v3","orden":5,"grupo":"energia-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central genera 500 MWh y en la red se pierde el 8 %. ¿Cuántos MWh llegan a los usuarios?","unidad":"MWh","decimales":1},"solucion":{"valor":460,"tolerancia":9.200000000000001,"explicacion":"500 × 0.92 = 460 MWh. Las pérdidas son energía generada, con sus emisiones, que no usa nadie."}},{"slug":"energia-3.s3.p6","orden":6,"grupo":"energia-3.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en la red se pierde el 10 % de lo generado, ¿cuántos kWh hay que generar para que lleguen 100 kWh a una casa? Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":111.1,"tolerancia":0.2,"explicacion":"100 ÷ 0,9 ≈ 111,1 kWh. Por eso ahorrar en casa ahorra un poco más en la central."}},{"slug":"energia-3.s3.p6.v2","orden":6,"grupo":"energia-3.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en la red se pierde el 10 % de lo generado, ¿cuántos kWh hay que generar para que lleguen 90 kWh a una casa? Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":100,"tolerancia":0.2,"explicacion":"90 ÷ 0,9 ≈ 100 kWh. Por eso ahorrar en casa ahorra un poco más en la central."}},{"slug":"energia-3.s3.p6.v3","orden":6,"grupo":"energia-3.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en la red se pierde el 20 % de lo generado, ¿cuántos kWh hay que generar para que lleguen 200 kWh a una casa? Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":250,"tolerancia":0.2,"explicacion":"200 ÷ 0,8 ≈ 250 kWh. Por eso ahorrar en casa ahorra un poco más en la central."}},{"slug":"energia-3.s3.p7","orden":7,"grupo":"energia-3.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una pérdida técnica o no técnica?","grupos":[{"id":"g1","nombre":"Técnica"},{"id":"g2","nombre":"No técnica"}],"items":[{"id":"i1","texto":"Calor en los cables de alta tensión"},{"id":"i2","texto":"Una conexión irregular a la red"},{"id":"i3","texto":"Calentamiento de un transformador"},{"id":"i4","texto":"Un medidor que registra de menos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las técnicas se reducen con mejor infraestructura; las no técnicas, con control y acceso formal al servicio."}},{"slug":"energia-3.s3.p8","orden":8,"grupo":"energia-3.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cortes y confiabilidad","cuerpo":["Un sistema eléctrico tiene que equilibrar en cada instante lo que se genera con lo que se consume. Si una línea importante se cae o la demanda supera lo disponible, puede haber cortes. En días de calor extremo, las redes de distribución de los barrios, sobrecargadas por miles de aires acondicionados, son las que más fallan."]},"solucion":{}},{"slug":"energia-3.s3.p9","orden":9,"grupo":"energia-3.s3.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué hay cortes en los barrios en una ola de calor.","items":[{"id":"i1","texto":"Hace muchísimo calor varios días seguidos"},{"id":"i2","texto":"Miles de aires acondicionados funcionan a la vez"},{"id":"i3","texto":"Los cables y transformadores del barrio se sobrecargan"},{"id":"i4","texto":"Se calientan y se dañan"},{"id":"i5","texto":"Se corta la luz en el barrio"},{"id":"i6","texto":"El calor hace que las centrales dejen de existir"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Muchas veces el problema no es la generación, sino la distribución local."}},{"slug":"energia-3.s3.p10","orden":10,"grupo":"energia-3.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Ahorrar energía en casa en un día de calor extremo puede ayudar a evitar cortes en el barrio.","razones":[{"id":"r1","texto":"Porque alivia la carga de la red del barrio en las horas pico"},{"id":"r2","texto":"Porque la red no tiene límites"},{"id":"r3","texto":"Porque los cortes solo dependen de las centrales"}]},"solucion":{"valor":true,"explicacion":"Si muchos vecinos bajan su consumo en las horas pico, por ejemplo con el aire a 24 °C, se alivia la carga de los transformadores del barrio.","clave":["r1"]}},{"slug":"energia-3.s3.p11","orden":11,"grupo":"energia-3.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de la red con su función.","izquierda":[{"id":"a1","texto":"Línea de alta tensión"},{"id":"a2","texto":"Subestación"},{"id":"a3","texto":"Distribuidora"},{"id":"a4","texto":"Transformador del barrio"}],"derecha":[{"id":"b1","texto":"Transportar energía a larga distancia"},{"id":"b2","texto":"Bajar la tensión cerca de las ciudades"},{"id":"b3","texto":"Llevar la electricidad hasta cada casa y facturar"},{"id":"b4","texto":"Adaptar la tensión para las casas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada parte de la red cumple su función en la cadena."}},{"slug":"energia-3.s3.p12","orden":12,"grupo":"energia-3.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La electricidad viaja en alta tensión para perder menos energía."},{"id":"s2","texto":"Toda la electricidad que se genera llega a las casas sin pérdidas."},{"id":"s3","texto":"En olas de calor, las redes de los barrios pueden sobrecargarse."},{"id":"s4","texto":"Las casas reciben la electricidad en alta tensión directamente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La red es tan importante como las centrales.","por_opcion":{"s2":"Una parte se pierde como calor en cables y transformadores, y por pérdidas no técnicas.","s4":"Llega a 220 voltios después de pasar por transformadores."}}},{"slug":"energia-3.s3.p13","orden":13,"grupo":"energia-3.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La electricidad viaja lejos en alta {{0}}; los {{1}} la adaptan; y una parte se {{2}} en el camino.","banco":[{"id":"w1","texto":"tensión"},{"id":"w2","texto":"transformadores"},{"id":"w3","texto":"pierde"},{"id":"w4","texto":"velocidad"},{"id":"w5","texto":"medidores"},{"id":"w6","texto":"multiplica"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre el viaje de la electricidad."}}]},{"slug":"energia-3.s4","orden":4,"tipo":"leccion","titulo_es":"La demanda cambia cada hora","bajada_es":"La curva diaria, los picos de verano e invierno y por qué la electricidad tiene que generarse en el momento.","minutos":11,"pasos":[{"slug":"energia-3.s4.p1","orden":1,"grupo":"energia-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Generar al instante","cuerpo":["A diferencia del agua o el gas, la electricidad casi no se guarda en la red: tiene que generarse en el mismo instante en que se consume. Por eso el sistema sigue la demanda minuto a minuto, encendiendo y apagando centrales.","La demanda cambia a lo largo del día: baja de madrugada, sube a la mañana y tiene picos, que en Argentina suelen darse en las tardes y noches de verano muy caluroso, por el aire acondicionado, y en los días más fríos del invierno."]},"solucion":{}},{"slug":"energia-3.s4.p2","orden":2,"grupo":"energia-3.s4.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos momentos de un día de verano caluroso por su demanda eléctrica típica, de menor a mayor.","items":[{"id":"i1","texto":"Madrugada, a las 5"},{"id":"i2","texto":"Mañana, a las 10"},{"id":"i3","texto":"Mediodía, a las 13"},{"id":"i4","texto":"Tarde-noche, a las 20"}],"extremos":["Menor demanda","Mayor demanda"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"En los días de mucho calor, el pico suele llegar a la tarde y primeras horas de la noche."}},{"slug":"energia-3.s4.p3","orden":3,"grupo":"energia-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Base y pico","cuerpo":["Algunas centrales generan casi todo el tiempo, cubriendo la demanda mínima: se las llama de base (por ejemplo, las nucleares). Otras se encienden solo en los picos: suelen ser térmicas más caras y, a veces, menos eficientes. Por eso los picos son los momentos más caros y a menudo los de más emisiones.","Bajar el pico —moviendo consumos a otras horas o ahorrando en esos momentos— evita encender las centrales más caras y contaminantes."]},"solucion":{}},{"slug":"energia-3.s4.p4","orden":4,"grupo":"energia-3.s4.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta central suele funcionar como base o para los picos?","grupos":[{"id":"g1","nombre":"Base"},{"id":"g2","nombre":"Picos"}],"items":[{"id":"i1","texto":"Central nuclear"},{"id":"i2","texto":"Turbina de gas que se enciende rápido"},{"id":"i3","texto":"Represa de pasada que genera con el caudal del río"},{"id":"i4","texto":"Motores diésel de emergencia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las de base generan parejo; las de pico se prenden y apagan según la demanda."}},{"slug":"energia-3.s4.p5","orden":5,"grupo":"energia-3.s4.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el pico de demanda suele ser el momento más contaminante.","items":[{"id":"i1","texto":"La demanda sube en la tarde de un día caluroso"},{"id":"i2","texto":"Las centrales de base ya están a pleno"},{"id":"i3","texto":"Se encienden centrales de pico"},{"id":"i4","texto":"Suelen ser térmicas menos eficientes"},{"id":"i5","texto":"Cada kWh del pico emite más"},{"id":"i6","texto":"En el pico solo generan los paneles solares"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Mover o reducir consumos en el pico tiene un efecto mayor que en otras horas."}},{"slug":"energia-3.s4.p6","orden":6,"grupo":"energia-3.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad se puede guardar en los cables para usarla en el pico.","razones":[{"id":"r1","texto":"Porque la red transporta pero no almacena"},{"id":"r2","texto":"Porque los cables son baterías gigantes"},{"id":"r3","texto":"Porque la electricidad no se usa en los picos"}]},"solucion":{"valor":false,"explicacion":"La red no almacena: hay que generar en el momento. Para guardar hacen falta baterías, represas de bombeo u otros sistemas.","clave":["r1"]}},{"slug":"energia-3.s4.p7","orden":7,"grupo":"energia-3.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad, 10.000 casas suben el aire de 18 °C a 24 °C en el pico y cada una baja 500 W su consumo. ¿Cuántos MW baja la demanda del pico?","unidad":"MW","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"10.000 × 500 W = 5.000.000 W = 5 MW. Lo que genera una central chica, sin construir nada."}},{"slug":"energia-3.s4.p7.v2","orden":7,"grupo":"energia-3.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad, 50.000 casas suben el aire de 18 °C a 24 °C en el pico y cada una baja 400 W su consumo. ¿Cuántos MW baja la demanda del pico?","unidad":"MW","decimales":1},"solucion":{"valor":20,"tolerancia":0.4,"explicacion":"50.000 × 400 W = 20.000.000 W = 20 MW. Lo que genera una central chica, sin construir nada."}},{"slug":"energia-3.s4.p7.v3","orden":7,"grupo":"energia-3.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad, 20.000 casas suben el aire de 18 °C a 24 °C en el pico y cada una baja 600 W su consumo. ¿Cuántos MW baja la demanda del pico?","unidad":"MW","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"20.000 × 600 W = 12.000.000 W = 12 MW. Lo que genera una central chica, sin construir nada."}},{"slug":"energia-3.s4.p8","orden":8,"grupo":"energia-3.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol y el pico","cuerpo":["La energía solar genera más al mediodía. En verano, ayuda a cubrir parte de la demanda de la tarde. Pero cuando el sol baja, la demanda sigue alta y la solar cae. Por eso, con mucha solar, se vuelve cada vez más importante almacenar energía del mediodía para la noche, o mover consumos hacia el mediodía."]},"solucion":{}},{"slug":"energia-3.s4.p9","orden":9,"grupo":"energia-3.s4.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada medida con cómo ayuda en el pico.","izquierda":[{"id":"a1","texto":"Poner el aire a 24 °C"},{"id":"a2","texto":"Programar el lavarropas de noche"},{"id":"a3","texto":"Baterías que se cargan al mediodía"},{"id":"a4","texto":"Tarifas más caras en el pico"}],"derecha":[{"id":"b1","texto":"Baja la demanda de cada casa"},{"id":"b2","texto":"Mueve un consumo fuera del pico"},{"id":"b3","texto":"Guardan energía solar para la noche"},{"id":"b4","texto":"Incentivan consumir en otras horas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Reducir, mover y almacenar: las tres formas de aliviar el pico."}},{"slug":"energia-3.s4.p10","orden":10,"grupo":"energia-3.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a bajar el pico de demanda en un día de calor? Marcá todo.","opciones":[{"id":"o1","texto":"Aire acondicionado a 24 °C"},{"id":"o2","texto":"Cerrar persianas donde da el sol"},{"id":"o3","texto":"Usar el lavarropas en otro horario"},{"id":"o4","texto":"Apagar aparatos que no se usan"},{"id":"o5","texto":"Encender todos los aires a 16 °C al llegar a casa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchas medidas chicas en muchas casas bajan mucho el pico."}},{"slug":"energia-3.s4.p11","orden":11,"grupo":"energia-3.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene poner el lavarropas de noche en lugar de a las 20 en un día muy caluroso?","opciones":[{"id":"o1","texto":"Porque se usa menos electricidad en el pico"},{"id":"o2","texto":"Porque de noche el lavarropas lava mejor"},{"id":"o3","texto":"Porque de noche la electricidad no tiene costo"},{"id":"o4","texto":"Porque de noche no se usa agua"}]},"solucion":{"clave":["o1"],"explicacion":"Mover consumos fuera del pico evita encender centrales caras y reduce el riesgo de cortes.","por_opcion":{"o3":"Puede ser más barata con tarifas horarias, pero no es gratis."}}},{"slug":"energia-3.s4.p12","orden":12,"grupo":"energia-3.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La demanda eléctrica cambia a lo largo del día."},{"id":"s2","texto":"El pico de demanda es a las 4 de la mañana."},{"id":"s3","texto":"En los picos se encienden centrales más caras."},{"id":"s4","texto":"Los paneles solares generan más de noche."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender la curva de demanda permite ahorrar donde más importa.","por_opcion":{"s2":"En los días calurosos, el pico suele ser a la tarde y primeras horas de la noche.","s4":"Generan más al mediodía y nada de noche."}}},{"slug":"energia-3.s4.p13","orden":13,"grupo":"energia-3.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La electricidad se genera en el mismo {{0}} en que se consume; las centrales de {{1}} funcionan siempre; y en el {{2}} se encienden las más caras.","banco":[{"id":"w1","texto":"instante"},{"id":"w2","texto":"base"},{"id":"w3","texto":"pico"},{"id":"w4","texto":"año"},{"id":"w5","texto":"punta"},{"id":"w6","texto":"valle"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres ideas centrales de la curva de demanda eléctrica."}}]},{"slug":"energia-3.s5","orden":5,"tipo":"leccion","titulo_es":"Cuánto emite un kWh","bajada_es":"El factor de emisión de la red, cómo cambia según la fuente y cómo calcular las emisiones de tu consumo.","minutos":11,"pasos":[{"slug":"energia-3.s5.p1","orden":1,"grupo":"energia-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El factor de emisión","cuerpo":["Para saber cuánto CO₂ emite un kWh que se consume, se usa el factor de emisión de la red: los kilos de CO₂ que se emitieron, en promedio, para generar cada kWh. Depende de la mezcla de fuentes: una red con mucho carbón puede superar 0,8 kg por kWh; una con mucha hidro y nuclear puede estar por debajo de 0,1.","En Argentina, con mucho gas y una parte importante de hidro, nuclear y renovables, el factor ronda valores del orden de 0,3 a 0,4 kg de CO₂ por kWh, y cambia de un año a otro."],"destacado":{"valor":"≈ 0,3-0,4 kg","texto":"de CO₂ por kWh es el orden del factor de emisión de la red eléctrica argentina en años recientes."}},"solucion":{}},{"slug":"energia-3.s5.p2","orden":2,"grupo":"energia-3.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa consume 250 kWh por mes. Con un factor de emisión de 0,35 kg de CO₂ por kWh, ¿cuántos kg de CO₂ corresponden a su consumo mensual?","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":87.5,"tolerancia":1.75,"explicacion":"250 × 0,35 = 87,5 kg de CO₂ por mes. Por año, doce veces eso."}},{"slug":"energia-3.s5.p2.v2","orden":2,"grupo":"energia-3.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa consume 400 kWh por mes. Con un factor de emisión de 0,35 kg de CO₂ por kWh, ¿cuántos kg de CO₂ corresponden a su consumo mensual?","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"400 × 0,35 = 140 kg de CO₂ por mes. Por año, doce veces eso."}},{"slug":"energia-3.s5.p2.v3","orden":2,"grupo":"energia-3.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa consume 180 kWh por mes. Con un factor de emisión de 0,35 kg de CO₂ por kWh, ¿cuántos kg de CO₂ corresponden a su consumo mensual?","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":63,"tolerancia":1.26,"explicacion":"180 × 0,35 = 63 kg de CO₂ por mes. Por año, doce veces eso."}},{"slug":"energia-3.s5.p3","orden":3,"grupo":"energia-3.s5.p3","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas redes eléctricas por su factor de emisión típico, de más a menos.","items":[{"id":"i1","texto":"Red basada en carbón"},{"id":"i2","texto":"Red basada en gas"},{"id":"i3","texto":"Red argentina de años recientes"},{"id":"i4","texto":"Red con mucha hidro y nuclear"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El mismo aparato emite muy distinto según el país donde se enchufe.","valores":{"i1":"más de 0,8 kg/kWh","i2":"≈ 0,4-0,5 kg/kWh","i3":"≈ 0,3-0,4 kg/kWh","i4":"menos de 0,1 kg/kWh"}}},{"slug":"energia-3.s5.p4","orden":4,"grupo":"energia-3.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué el mismo aparato emite distinto","cuerpo":["Una heladera que consume 300 kWh por año emite unos 105 kg de CO₂ con un factor de 0,35, pero más de 240 kg en una red de carbón y menos de 30 kg en una red muy limpia. La eficiencia del aparato importa, y también cómo se genera la electricidad.","Por eso limpiar la red —sumar renovables— reduce las emisiones de todos los aparatos a la vez, sin que nadie cambie nada en su casa."]},"solucion":{}},{"slug":"energia-3.s5.p5","orden":5,"grupo":"energia-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato consume 300 kWh por año. ¿Cuántos kg de CO₂ más emite en una red de carbón (0,8 kg/kWh) que en una red muy limpia (0,1 kg/kWh)?","unidad":"kg de CO₂","decimales":3},"solucion":{"valor":210.00000000000003,"tolerancia":4.200000000000001,"explicacion":"300 × (0,8 − 0,1) = 210 kg de CO₂ más por año. La red importa tanto como el aparato."}},{"slug":"energia-3.s5.p5.v2","orden":5,"grupo":"energia-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato consume 500 kWh por año. ¿Cuántos kg de CO₂ más emite en una red de carbón (0,8 kg/kWh) que en una red muy limpia (0,1 kg/kWh)?","unidad":"kg de CO₂","decimales":3},"solucion":{"valor":350.00000000000006,"tolerancia":7.000000000000001,"explicacion":"500 × (0,8 − 0,1) = 350 kg de CO₂ más por año. La red importa tanto como el aparato."}},{"slug":"energia-3.s5.p5.v3","orden":5,"grupo":"energia-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato consume 200 kWh por año. ¿Cuántos kg de CO₂ más emite en una red de carbón (0,8 kg/kWh) que en una red muy limpia (0,1 kg/kWh)?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"200 × (0,8 − 0,1) = 140 kg de CO₂ más por año. La red importa tanto como el aparato."}},{"slug":"energia-3.s5.p6","orden":6,"grupo":"energia-3.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo sumar renovables a la red baja las emisiones de tu heladera.","items":[{"id":"i1","texto":"Se construyen parques eólicos y solares"},{"id":"i2","texto":"Generan una parte mayor de la electricidad"},{"id":"i3","texto":"Se quema menos gas en las centrales"},{"id":"i4","texto":"Baja el factor de emisión de la red"},{"id":"i5","texto":"Cada kWh de tu heladera emite menos"},{"id":"i6","texto":"Tu heladera empieza a funcionar con viento directo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Limpiar la red es una palanca de sistema: mejora todos los aparatos a la vez."}},{"slug":"energia-3.s5.p7","orden":7,"grupo":"energia-3.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si dos casas consumen los mismos kWh, siempre emiten lo mismo, estén en el país que estén.","razones":[{"id":"r1","texto":"Porque depende de cómo se genera la electricidad en cada lugar"},{"id":"r2","texto":"Porque todos los kWh del mundo son idénticos en emisiones"},{"id":"r3","texto":"Porque las emisiones dependen solo del precio"}]},"solucion":{"valor":false,"explicacion":"Depende del factor de emisión de la red de cada lugar. El mismo consumo puede emitir varias veces más en una red de carbón.","clave":["r1"]}},{"slug":"energia-3.s5.p8","orden":8,"grupo":"energia-3.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Generar en casa","cuerpo":["Con la Ley 27.424 de generación distribuida, una casa o un comercio pueden instalar paneles solares, consumir su propia energía y volcar los excedentes a la red, que la distribuidora descuenta o paga. Un sistema de 3 kW en buena parte de Argentina puede generar del orden de 4.000 kWh por año, aunque depende mucho de la región y la orientación."]},"solucion":{}},{"slug":"energia-3.s5.p9","orden":9,"grupo":"energia-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Unos paneles en el techo generan 4.000 kWh por año. Con un factor de 0,35 kg de CO₂ por kWh de la red, ¿cuántos kg de CO₂ por año se evitan?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":1400,"tolerancia":28,"explicacion":"4.000 × 0,35 = 1.400 kg de CO₂ por año que no hace falta emitir en una central."}},{"slug":"energia-3.s5.p9.v2","orden":9,"grupo":"energia-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Unos paneles en el techo generan 3.500 kWh por año. Con un factor de 0,35 kg de CO₂ por kWh de la red, ¿cuántos kg de CO₂ por año se evitan?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":1225,"tolerancia":24.5,"explicacion":"3.500 × 0,35 = 1.225 kg de CO₂ por año que no hace falta emitir en una central."}},{"slug":"energia-3.s5.p9.v3","orden":9,"grupo":"energia-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Unos paneles en el techo generan 5.000 kWh por año. Con un factor de 0,35 kg de CO₂ por kWh de la red, ¿cuántos kg de CO₂ por año se evitan?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":1750,"tolerancia":35,"explicacion":"5.000 × 0,35 = 1.750 kg de CO₂ por año que no hace falta emitir en una central."}},{"slug":"energia-3.s5.p10","orden":10,"grupo":"energia-3.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción reduce las emisiones de la electricidad bajando el consumo o limpiando la generación?","grupos":[{"id":"g1","nombre":"Baja el consumo"},{"id":"g2","nombre":"Limpia la generación"}],"items":[{"id":"i1","texto":"Cambiar a lámparas LED"},{"id":"i2","texto":"Paneles solares en el techo"},{"id":"i3","texto":"Poner el aire a 24 °C"},{"id":"i4","texto":"Un nuevo parque eólico"},{"id":"i5","texto":"Heladera eficiente"},{"id":"i6","texto":"Una represa que genera más en un año lluvioso"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos palancas se multiplican: menos kWh y cada kWh más limpio."}},{"slug":"energia-3.s5.p11","orden":11,"grupo":"energia-3.s5.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿De qué depende cuánto CO₂ emite el consumo eléctrico de una casa? Marcá todo.","opciones":[{"id":"o1","texto":"Cuántos kWh consume"},{"id":"o2","texto":"La mezcla de fuentes de la red"},{"id":"o3","texto":"En qué horario consume, si en el pico se usan centrales más sucias"},{"id":"o4","texto":"Si genera parte de su energía con paneles"},{"id":"o5","texto":"El color de la factura"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cantidad, mezcla, horario y generación propia: las variables de la huella eléctrica."}},{"slug":"energia-3.s5.p12","orden":12,"grupo":"energia-3.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cálculo y marcá los errores.","segmentos":[{"id":"s1","texto":"La casa usa 3.000 kWh por año."},{"id":"s2","texto":"Con 0,35 kg por kWh, emite 3.000 × 0,35 = 1.050 kg de CO₂ por año."},{"id":"s3","texto":"Si la red se vuelve más limpia, sus emisiones no cambian."},{"id":"s4","texto":"Si instala paneles que generan 2.000 kWh, sus emisiones se duplican."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Consumo por factor: una cuenta simple con dos palancas.","por_opcion":{"s3":"Si baja el factor de emisión, baja la huella de cada kWh.","s4":"Al revés: evita comprar esos kWh a la red y baja su huella."}}},{"slug":"energia-3.s5.p13","orden":13,"grupo":"energia-3.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los kg de CO₂ por kWh de la red son el factor de {{0}}; en Argentina ronda los {{1}} kg; y sumar {{2}} lo baja.","banco":[{"id":"w1","texto":"emisión"},{"id":"w2","texto":"0,35"},{"id":"w3","texto":"renovables"},{"id":"w4","texto":"consumo"},{"id":"w5","texto":"3,5"},{"id":"w6","texto":"medidores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La cuenta que conecta el enchufe con el clima."}}]},{"slug":"energia-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: de dónde sale la electricidad","bajada_es":"Generación, matriz, red, demanda y emisiones, mezclados.","minutos":8,"pasos":[{"slug":"energia-3.s6.p1","orden":1,"grupo":"energia-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «De dónde sale la electricidad». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el pico de febrero","bajada_es":"Una ola de calor pone al límite la red de una ciudad. Con los números, armá el plan para pasar el pico sin cortes.","minutos":10,"pasos":[{"slug":"energia-3.s7.p1","orden":1,"grupo":"energia-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Una ciudad de 200.000 casas enfrenta una ola de calor. A las 20 horas, la demanda llega a 450 MW y la red de distribución aguanta 420 MW sin cortes. Muchas casas tienen el aire a 18 °C. Se estima que subirlo a 24 °C baja unos 400 W por casa que lo use, y que la mitad de las casas tiene aire.","La red tiene un factor de emisión de 0,35 kg de CO₂ por kWh, pero en el pico se encienden turbinas de gas con un factor de 0,6."]},"solucion":{}},{"slug":"energia-3.s7.p2","orden":2,"grupo":"energia-3.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos MW sobran de demanda por encima de lo que aguanta la red?","unidad":"MW","decimales":0,"contexto":"Demanda de 450 MW; la red aguanta 420 MW."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"450 − 420 = 30 MW. Hay que bajar al menos eso para evitar cortes."}},{"slug":"energia-3.s7.p3","orden":3,"grupo":"energia-3.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la mitad de las 200.000 casas sube el aire a 24 °C y cada una baja 400 W, ¿cuántos MW baja la demanda?","unidad":"MW","decimales":0,"contexto":"100.000 casas con aire; 400 W menos cada una."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"100.000 × 400 W = 40.000.000 W = 40 MW. Alcanza para pasar el pico sin cortes."}},{"slug":"energia-3.s7.p4","orden":4,"grupo":"energia-3.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂ se evitan por cada hora que se bajan esos 40 MW en el pico? (0,6 kg por kWh en el pico)","unidad":"kg de CO₂","decimales":0,"contexto":"40 MW menos durante una hora; turbinas de pico con 0,6 kg de CO₂ por kWh."},"solucion":{"valor":24000,"tolerancia":480,"explicacion":"40 MW durante 1 hora son 40 MWh = 40.000 kWh; × 0,6 = 24.000 kg de CO₂ evitados por hora de pico."}},{"slug":"energia-3.s7.p5","orden":5,"grupo":"energia-3.s7.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas para esta noche por rapidez de efecto, de más rápida a más lenta.","items":[{"id":"i1","texto":"Pedido masivo de subir los aires a 24 °C"},{"id":"i2","texto":"Mover lavarropas y termotanques eléctricos fuera del pico"},{"id":"i3","texto":"Cambiar transformadores del barrio"},{"id":"i4","texto":"Construir un parque solar con baterías"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Para esta noche, la demanda. Para los próximos veranos, la red y la generación.","valores":{"i1":"efecto en minutos","i2":"efecto en horas","i3":"efecto en meses","i4":"efecto en años"}}},{"slug":"energia-3.s7.p6","orden":6,"grupo":"energia-3.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué mensaje a la población tiene más chances de funcionar?","opciones":[{"id":"o1","texto":"\"Hoy de 18 a 22, aire a 24 °C: evitemos cortes\""},{"id":"o2","texto":"\"Usen menos energía porque sí, sin más explicación\""},{"id":"o3","texto":"\"El que tenga cortes es por su culpa y de nadie más\""},{"id":"o4","texto":"\"No hay ningún problema, sigan todo igual que siempre\""}]},"solucion":{"clave":["o1"],"explicacion":"Concreto, con horario, con una acción simple y con el motivo: fácil, oportuno y social.","por_opcion":{"o3":"Culpar aleja; un pedido concreto y con motivo claro funciona mejor."}}},{"slug":"energia-3.s7.p7","orden":7,"grupo":"energia-3.s7.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las medidas según su horizonte.","grupos":[{"id":"g1","nombre":"Para esta noche"},{"id":"g2","nombre":"Para los próximos años"}],"items":[{"id":"i1","texto":"Pedir aires a 24 °C"},{"id":"i2","texto":"Reforzar la red de distribución"},{"id":"i3","texto":"Mover consumos flexibles fuera del pico"},{"id":"i4","texto":"Sumar solar con baterías"},{"id":"i5","texto":"Apagar vidrieras iluminadas del centro"},{"id":"i6","texto":"Mejorar la aislación de las viviendas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Un buen plan combina respuestas inmediatas con cambios estructurales."}},{"slug":"energia-3.s7.p8","orden":8,"grupo":"energia-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La distribuidora publica su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pedimos aires a 24 °C entre las 18 y las 22."},{"id":"s2","texto":"Para ahorrar, cortaremos la luz a los hospitales en el pico."},{"id":"s3","texto":"Reforzaremos los transformadores de los barrios más cargados."},{"id":"s4","texto":"Como la solar no genera a las 20, no conviene sumar solar nunca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Pasar el pico hoy y prepararse para los próximos veranos.","por_opcion":{"s2":"Los servicios esenciales se protegen; se piden reducciones a consumos flexibles.","s4":"Con baterías o moviendo consumos al mediodía, la solar ayuda mucho."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-4","rama":"energia","orden":4,"nivel":2,"titulo_es":"Energías renovables","bajada_es":"El sol de la Puna y el viento patagónico están entre los mejores del mundo. Cómo se aprovechan, qué pasa cuando no hay sol ni viento y cuánto cuestan.","objetivos_es":["Explicar cómo funcionan la energía solar, eólica, hidráulica, biomasa y geotérmica","Calcular la energía que genera una instalación usando el factor de capacidad","Describir estrategias para manejar la variabilidad de sol y viento","Interpretar la caída de costos de las renovables","Evaluar impactos y beneficios locales de los proyectos renovables"],"repasa":["energia-3","energia-1","tronco-2"],"requiere_tronco":2,"fuentes":["irena","cammesa","ley-27424-generacion","iea-energia","owid-energia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-4.s1","orden":1,"tipo":"leccion","titulo_es":"La energía del sol","bajada_es":"Paneles fotovoltaicos, termotanques solares y por qué el noroeste argentino es un lugar privilegiado.","minutos":12,"pasos":[{"slug":"energia-4.s1.p1","orden":1,"grupo":"energia-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos formas de usar el sol","cuerpo":["El sol se puede usar para producir electricidad, con paneles fotovoltaicos, o para calentar agua o aire directamente, con colectores solares térmicos como los termotanques solares. Los dos aprovechan una fuente gratuita e inagotable, pero de formas distintas.","Un termotanque solar puede cubrir buena parte del agua caliente de una casa durante gran parte del año, y ahorrar mucho gas o electricidad."]},"solucion":{}},{"slug":"energia-4.s1.p2","orden":2,"grupo":"energia-4.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es energía solar fotovoltaica o térmica?","grupos":[{"id":"g1","nombre":"Fotovoltaica"},{"id":"g2","nombre":"Térmica"}],"items":[{"id":"i1","texto":"Paneles en el techo que alimentan la heladera"},{"id":"i2","texto":"Termotanque solar para la ducha"},{"id":"i3","texto":"Parque solar en la Puna conectado a la red"},{"id":"i4","texto":"Colector que calienta el agua de una pileta"},{"id":"i5","texto":"Cargador solar de celular"},{"id":"i6","texto":"Cocina solar parabólica"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La fotovoltaica produce electricidad; la térmica, calor. Las dos usan el mismo sol."}},{"slug":"energia-4.s1.p3","orden":3,"grupo":"energia-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol de Argentina","cuerpo":["La cantidad de energía solar que llega al suelo se llama irradiación. En la Puna y el noroeste argentino está entre las más altas del mundo, por la altura, el aire seco y los cielos despejados. Por eso allí se construyeron grandes parques solares, como el de Cauchari, en Jujuy, a más de 4.000 metros de altura.","Pero el sol sirve en casi todo el país: incluso en la región pampeana o en ciudades como Córdoba o Mendoza, un panel bien orientado genera mucha energía a lo largo del año."]},"solucion":{}},{"slug":"energia-4.s1.p4","orden":4,"grupo":"energia-4.s1.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la Puna es uno de los mejores lugares del mundo para la energía solar?","opciones":[{"id":"o1","texto":"Por la altura, el aire seco y los cielos despejados"},{"id":"o2","texto":"Porque allí el sol sale dos veces por día"},{"id":"o3","texto":"Porque hace mucho calor todo el año"},{"id":"o4","texto":"Porque hay mucha agua para enfriar los paneles"}]},"solucion":{"clave":["o1"],"explicacion":"La radiación solar importa más que el calor. De hecho, los paneles rinden mejor con frío.","por_opcion":{"o3":"En la Puna hace frío: lo que importa es la radiación, no la temperatura."}}},{"slug":"energia-4.s1.p5","orden":5,"grupo":"energia-4.s1.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los paneles solares rinden mejor cuanto más calor hace.","razones":[{"id":"r1","texto":"Porque lo que importa es la luz; el calor los hace rendir un poco menos"},{"id":"r2","texto":"Porque los paneles funcionan con el calor del aire"},{"id":"r3","texto":"Porque de noche rinden más"}]},"solucion":{"valor":false,"explicacion":"Los paneles fotovoltaicos pierden algo de eficiencia con el calor. Lo que los hace rendir es la cantidad de luz, no la temperatura.","clave":["r1"]}},{"slug":"energia-4.s1.p6","orden":6,"grupo":"energia-4.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Orientación e inclinación","cuerpo":["En el hemisferio sur, los paneles rinden más si miran hacia el norte, con una inclinación parecida a la latitud del lugar. Las sombras de árboles, edificios o tanques de agua pueden bajar mucho la producción, incluso si tapan una parte chica del panel."]},"solucion":{}},{"slug":"energia-4.s1.p7","orden":7,"grupo":"energia-4.s1.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un panel solar en una casa genere más? Marcá todo.","opciones":[{"id":"o1","texto":"Que mire hacia el norte, en el hemisferio sur"},{"id":"o2","texto":"Que no tenga sombras durante el día"},{"id":"o3","texto":"Que tenga una inclinación adecuada"},{"id":"o4","texto":"Que esté limpio de polvo"},{"id":"o5","texto":"Que mire hacia el sur"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Norte, sin sombras, bien inclinado y limpio."}},{"slug":"energia-4.s1.p8","orden":8,"grupo":"energia-4.s1.p8","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánto genera un techo","planteo":"Un sistema de 3 kW está en un lugar donde el sol equivale, en promedio, a 4,5 horas por día de luz plena.","pasos":["Por día: 3 kW × 4,5 h = 13,5 kWh.","Por año: 13,5 × 365 ≈ 4.930 kWh.","Con pérdidas del sistema de un 15 %: 4.930 × 0,85 ≈ 4.190 kWh."],"resultado":"Más de lo que usa en electricidad una casa típica con gas en un año. Las \"horas de sol pleno\" resumen cuánta luz llega en promedio."},"solucion":{}},{"slug":"energia-4.s1.p9","orden":9,"grupo":"energia-4.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema solar de 3 kW está en un lugar con 4,5 horas de sol pleno por día en promedio. Sin contar pérdidas, ¿cuántos kWh genera por año? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":4928,"tolerancia":5,"explicacion":"3 × 4,5 × 365 ≈ 4.928 kWh por año, antes de descontar pérdidas del sistema."}},{"slug":"energia-4.s1.p9.v2","orden":9,"grupo":"energia-4.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema solar de 5 kW está en un lugar con 5 horas de sol pleno por día en promedio. Sin contar pérdidas, ¿cuántos kWh genera por año? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":9125,"tolerancia":5,"explicacion":"5 × 5 × 365 ≈ 9.125 kWh por año, antes de descontar pérdidas del sistema."}},{"slug":"energia-4.s1.p9.v3","orden":9,"grupo":"energia-4.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema solar de 2 kW está en un lugar con 4 horas de sol pleno por día en promedio. Sin contar pérdidas, ¿cuántos kWh genera por año? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":2920,"tolerancia":5,"explicacion":"2 × 4 × 365 ≈ 2.920 kWh por año, antes de descontar pérdidas del sistema."}},{"slug":"energia-4.s1.p10","orden":10,"grupo":"energia-4.s1.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un termotanque solar ahorra gas.","items":[{"id":"i1","texto":"El sol calienta el agua en el colector"},{"id":"i2","texto":"El agua caliente se guarda en un tanque aislado"},{"id":"i3","texto":"La ducha usa esa agua ya caliente"},{"id":"i4","texto":"El calefón o termotanque a gas se enciende mucho menos"},{"id":"i5","texto":"Se quema menos gas y se emite menos CO₂"},{"id":"i6","texto":"El termotanque solar genera gas con el sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una tecnología simple y probada que ataca uno de los grandes consumos de una casa: el agua caliente."}},{"slug":"energia-4.s1.p11","orden":11,"grupo":"energia-4.s1.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un termotanque solar produce electricidad para la casa.","razones":[{"id":"r1","texto":"Porque calienta agua, no genera electricidad"},{"id":"r2","texto":"Porque tiene paneles fotovoltaicos adentro"},{"id":"r3","texto":"Porque funciona a gas"}]},"solucion":{"valor":false,"explicacion":"Produce calor: calienta agua directamente con el sol. La electricidad la producen los paneles fotovoltaicos.","clave":["r1"]}},{"slug":"energia-4.s1.p12","orden":12,"grupo":"energia-4.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 20 m³ de gas por mes para calentar agua. Si un termotanque solar cubre el 60 % del agua caliente, ¿cuántos m³ de gas ahorra por año?","unidad":"m³","decimales":1},"solucion":{"valor":144,"tolerancia":2.88,"explicacion":"20 × 0,6 × 12 = 144 m³ por año. Con 1,9 kg de CO₂ por m³, más de 273 kg de CO₂ evitados."}},{"slug":"energia-4.s1.p12.v2","orden":12,"grupo":"energia-4.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 25 m³ de gas por mes para calentar agua. Si un termotanque solar cubre el 50 % del agua caliente, ¿cuántos m³ de gas ahorra por año?","unidad":"m³","decimales":1},"solucion":{"valor":150,"tolerancia":3,"explicacion":"25 × 0,5 × 12 = 150 m³ por año. Con 1,9 kg de CO₂ por m³, más de 285 kg de CO₂ evitados."}},{"slug":"energia-4.s1.p12.v3","orden":12,"grupo":"energia-4.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 15 m³ de gas por mes para calentar agua. Si un termotanque solar cubre el 70 % del agua caliente, ¿cuántos m³ de gas ahorra por año?","unidad":"m³","decimales":1},"solucion":{"valor":126,"tolerancia":2.52,"explicacion":"15 × 0,7 × 12 = 126 m³ por año. Con 1,9 kg de CO₂ por m³, más de 239 kg de CO₂ evitados."}},{"slug":"energia-4.s1.p13","orden":13,"grupo":"energia-4.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Nuestros paneles rinden más orientados al norte."},{"id":"s2","texto":"Funcionan igual de bien a la sombra de un árbol."},{"id":"s3","texto":"El termotanque solar ahorra gas en el agua caliente."},{"id":"s4","texto":"Los paneles generan más en los días de más calor, aunque esté nublado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer cómo funciona el sol evita promesas engañosas.","por_opcion":{"s2":"Las sombras bajan mucho la producción.","s4":"Lo que importa es la luz; con nubes generan menos."}}},{"slug":"energia-4.s1.p14","orden":14,"grupo":"energia-4.s1.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía solar que llega al suelo se llama {{0}}; en el hemisferio sur los paneles conviene orientarlos al {{1}}; y un termotanque solar ahorra {{2}}.","banco":[{"id":"w1","texto":"irradiación"},{"id":"w2","texto":"norte"},{"id":"w3","texto":"gas"},{"id":"w4","texto":"evaporación"},{"id":"w5","texto":"sur"},{"id":"w6","texto":"agua"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para aprovechar bien la energía del sol."}},{"slug":"energia-4.s1.p15","orden":15,"grupo":"energia-4.s1.p15","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas ubicaciones por la energía solar que suelen recibir por año, de más a menos.","items":[{"id":"i1","texto":"Puna jujeña"},{"id":"i2","texto":"Mendoza"},{"id":"i3","texto":"Buenos Aires"},{"id":"i4","texto":"Ushuaia"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El noroeste y Cuyo son privilegiados, pero el sol sirve en casi todo el país.","valores":{"i1":"de las más altas del mundo","i2":"muy alta","i3":"buena","i4":"más baja"}}}]},{"slug":"energia-4.s2","orden":2,"tipo":"leccion","titulo_es":"La energía del viento","bajada_es":"Aerogeneradores, el viento patagónico y el factor de capacidad.","minutos":12,"pasos":[{"slug":"energia-4.s2.p1","orden":1,"grupo":"energia-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo funciona un aerogenerador","cuerpo":["Un aerogenerador moderno tiene una torre de más de 100 metros y palas enormes. El viento hace girar las palas, que mueven un generador en la góndola, arriba de la torre. La potencia que se puede sacar del viento crece muchísimo con la velocidad: si el viento sopla el doble de rápido, la energía disponible es unas ocho veces mayor.","Por eso importa tanto dónde se instalan: unos pocos kilómetros por hora de diferencia en el viento promedio cambian mucho la producción."]},"solucion":{}},{"slug":"energia-4.s2.p2","orden":2,"grupo":"energia-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía disponible en el viento crece con el cubo de la velocidad. Si el viento sopla 2 veces más rápido, ¿cuántas veces más energía hay disponible? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":8,"tolerancia":0.1,"explicacion":"2³ = 8. Por eso los mejores lugares de viento valen tanto."}},{"slug":"energia-4.s2.p2.v2","orden":2,"grupo":"energia-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía disponible en el viento crece con el cubo de la velocidad. Si el viento sopla 1,5 veces más rápido, ¿cuántas veces más energía hay disponible? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.4,"tolerancia":0.1,"explicacion":"1,5³ = 3,4. Por eso los mejores lugares de viento valen tanto."}},{"slug":"energia-4.s2.p2.v3","orden":2,"grupo":"energia-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía disponible en el viento crece con el cubo de la velocidad. Si el viento sopla 3 veces más rápido, ¿cuántas veces más energía hay disponible? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":27,"tolerancia":0.1,"explicacion":"3³ = 27. Por eso los mejores lugares de viento valen tanto."}},{"slug":"energia-4.s2.p3","orden":3,"grupo":"energia-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El viento patagónico","cuerpo":["La Patagonia tiene algunos de los vientos más fuertes y constantes del mundo. Allí, algunos parques eólicos producen en un año cerca de la mitad de lo que producirían si funcionaran a plena potencia todo el tiempo, un rendimiento muy alto a nivel mundial. También hay parques en la provincia de Buenos Aires y en otras regiones."]},"solucion":{}},{"slug":"energia-4.s2.p4","orden":4,"grupo":"energia-4.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El factor de capacidad","cuerpo":["Ningún generador funciona siempre a su potencia máxima. El factor de capacidad es la energía que produce en un año dividida por la que produciría a potencia máxima las 8.760 horas del año. Un parque solar puede tener un factor de 20 a 30 %; un buen parque eólico patagónico, cerca del 45 al 50 %; una central nuclear, más del 80 %."],"destacado":{"valor":"Factor de capacidad","texto":"= energía real del año ÷ (potencia máxima × 8.760 horas)."}},"solucion":{}},{"slug":"energia-4.s2.p5","orden":5,"grupo":"energia-4.s2.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánto genera un parque eólico","planteo":"Un parque de 100 MW en la Patagonia tiene un factor de capacidad del 45 %.","pasos":["A potencia máxima todo el año: 100 MW × 8.760 h = 876.000 MWh.","Con factor 45 %: 876.000 × 0,45 = 394.200 MWh.","Si una casa usa 3 MWh por año: 394.200 ÷ 3 ≈ 131.400 casas."],"resultado":"Un solo parque puede abastecer el consumo eléctrico de más de cien mil hogares."},"solucion":{}},{"slug":"energia-4.s2.p6","orden":6,"grupo":"energia-4.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 100 MW tiene un factor de capacidad del 45 %. ¿Cuántos MWh genera por año? (8.760 horas)","unidad":"MWh","decimales":0},"solucion":{"valor":394200,"tolerancia":7884,"explicacion":"100 × 8.760 × 0,45 = 394.200 MWh por año: el consumo de miles de hogares."}},{"slug":"energia-4.s2.p6.v2","orden":6,"grupo":"energia-4.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 50 MW tiene un factor de capacidad del 40 %. ¿Cuántos MWh genera por año? (8.760 horas)","unidad":"MWh","decimales":0},"solucion":{"valor":175200,"tolerancia":3504,"explicacion":"50 × 8.760 × 0,4 = 175.200 MWh por año: el consumo de miles de hogares."}},{"slug":"energia-4.s2.p6.v3","orden":6,"grupo":"energia-4.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 200 MW tiene un factor de capacidad del 50 %. ¿Cuántos MWh genera por año? (8.760 horas)","unidad":"MWh","decimales":0},"solucion":{"valor":876000,"tolerancia":17520,"explicacion":"200 × 8.760 × 0,5 = 876.000 MWh por año: el consumo de miles de hogares."}},{"slug":"energia-4.s2.p7","orden":7,"grupo":"energia-4.s2.p7","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas centrales por su factor de capacidad típico, de mayor a menor.","items":[{"id":"i1","texto":"Central nuclear"},{"id":"i2","texto":"Parque eólico patagónico"},{"id":"i3","texto":"Parque solar en la Puna"},{"id":"i4","texto":"Paneles en un techo de la llanura"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El factor de capacidad no dice si una fuente es buena o mala: dice cuántas horas equivalentes genera.","valores":{"i1":"más del 80 %","i2":"≈ 45-50 %","i3":"≈ 25-30 %","i4":"≈ 15-20 %"}}},{"slug":"energia-4.s2.p8","orden":8,"grupo":"energia-4.s2.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un parque eólico de 100 MW genera 100 MW todo el tiempo.","razones":[{"id":"r1","texto":"Porque depende del viento: el factor de capacidad resume cuánto genera"},{"id":"r2","texto":"Porque los parques eólicos nunca generan"},{"id":"r3","texto":"Porque 100 MW es la energía de todo el año"}]},"solucion":{"valor":false,"explicacion":"Genera según el viento. En un año, produce una fracción de lo que produciría a potencia máxima: esa fracción es el factor de capacidad.","clave":["r1"]}},{"slug":"energia-4.s2.p9","orden":9,"grupo":"energia-4.s2.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su significado.","izquierda":[{"id":"a1","texto":"Potencia instalada"},{"id":"a2","texto":"Factor de capacidad"},{"id":"a3","texto":"Energía anual"},{"id":"a4","texto":"Horas de sol pleno"}],"derecha":[{"id":"b1","texto":"Lo máximo que puede generar en un momento"},{"id":"b2","texto":"Fracción de la energía máxima que genera en un año"},{"id":"b3","texto":"Lo que efectivamente genera en un año"},{"id":"b4","texto":"Equivalente diario de luz a máxima intensidad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Potencia y energía otra vez, como en el tronco: la potencia es la capacidad; la energía, lo que realmente se genera."}},{"slug":"energia-4.s2.p10","orden":10,"grupo":"energia-4.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un lugar sea bueno para un parque eólico? Marcá todo.","opciones":[{"id":"o1","texto":"Vientos fuertes y constantes"},{"id":"o2","texto":"Pocas turbulencias"},{"id":"o3","texto":"Acceso a una línea eléctrica cercana"},{"id":"o4","texto":"Evitar rutas migratorias importantes de aves"},{"id":"o5","texto":"Muchos árboles altos alrededor"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Buen viento, conexión a la red y cuidado de la fauna."}},{"slug":"energia-4.s2.p11","orden":11,"grupo":"energia-4.s2.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa que un parque eólico tenga un factor de capacidad del 50 %?","opciones":[{"id":"o1","texto":"Que en el año genera la mitad de su máximo posible"},{"id":"o2","texto":"Que la mitad de los aerogeneradores está rota"},{"id":"o3","texto":"Que funciona solo la mitad de los días del año"},{"id":"o4","texto":"Que genera el 50 % de la electricidad del país"}]},"solucion":{"clave":["o1"],"explicacion":"El factor de capacidad resume la variabilidad del viento en un solo número anual.","por_opcion":{"o3":"Funciona casi todos los días, pero a distintas potencias según el viento."}}},{"slug":"energia-4.s2.p12","orden":12,"grupo":"energia-4.s2.p12","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un dato de potencia o de energía?","grupos":[{"id":"g1","nombre":"Potencia (kW, MW)"},{"id":"g2","nombre":"Energía (kWh, MWh)"}],"items":[{"id":"i1","texto":"Parque eólico de 100 MW"},{"id":"i2","texto":"394.200 MWh generados en un año"},{"id":"i3","texto":"Paneles de 3 kW en un techo"},{"id":"i4","texto":"4.190 kWh generados por los paneles"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Como en el tronco: la potencia es la capacidad en un momento; la energía, lo que se genera en un tiempo."}},{"slug":"energia-4.s2.p13","orden":13,"grupo":"energia-4.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Patagonia tiene vientos de los mejores del mundo."},{"id":"s2","texto":"Si el viento sopla el doble de rápido, el parque genera el doble."},{"id":"s3","texto":"El factor de capacidad resume cuánto genera en el año."},{"id":"s4","texto":"Un parque de 100 MW genera 876.000 MWh por año siempre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Velocidad al cubo y factor de capacidad: las dos claves del viento.","por_opcion":{"s2":"La energía disponible crece con el cubo: unas ocho veces más.","s4":"Eso sería a potencia máxima todo el año; con el factor real, bastante menos."}}},{"slug":"energia-4.s2.p14","orden":14,"grupo":"energia-4.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía disponible en el viento crece con el {{0}} de su velocidad; la fracción de la energía máxima que genera una central en un año es su factor de {{1}}.","banco":[{"id":"w1","texto":"cubo"},{"id":"w2","texto":"capacidad"},{"id":"w3","texto":"doble"},{"id":"w4","texto":"emisión"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Las dos ideas clave de la energía eólica."}},{"slug":"energia-4.s2.p15","orden":15,"grupo":"energia-4.s2.p15","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas horas tiene un año, para calcular la energía máxima de una central.","min":100,"max":50000,"paso":1,"unidad":"horas","escala":"log"},"solucion":{"valor":8760,"banda":"log","explicacion":"365 × 24 = 8.760 horas. Es la base para calcular el factor de capacidad."}}]},{"slug":"energia-4.s3","orden":3,"tipo":"leccion","titulo_es":"Agua, biomasa y calor de la Tierra","bajada_es":"Pequeños aprovechamientos hidráulicos, biogás, biomasa y geotermia: las otras renovables.","minutos":11,"pasos":[{"slug":"energia-4.s3.p1","orden":1,"grupo":"energia-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hidráulica chica y grande","cuerpo":["Las grandes represas generan mucha electricidad sin emitir CO₂ al funcionar, pero tienen impactos importantes: inundan valles, cortan ríos y afectan a peces migradores, como viste en la rama de Agua. Por eso la ley argentina de promoción de renovables considera renovables promovidas solo a los pequeños aprovechamientos hidráulicos, hasta cierta potencia.","Los pequeños aprovechamientos, en ríos y canales de riego, tienen menos impacto y sirven a pueblos y regiones."]},"solucion":{}},{"slug":"energia-4.s3.p2","orden":2,"grupo":"energia-4.s3.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las grandes represas no tienen ningún impacto ambiental porque no emiten CO₂ al generar.","razones":[{"id":"r1","texto":"Porque inundan valles y cortan ríos, aunque no emitan al generar"},{"id":"r2","texto":"Porque las represas emiten más CO₂ que el carbón"},{"id":"r3","texto":"Porque las represas no usan agua"}]},"solucion":{"valor":false,"explicacion":"No emiten al generar, pero inundan valles, cortan ríos y afectan la fauna. Toda fuente tiene impactos; la pregunta es cuáles y cuánto.","clave":["r1"]}},{"slug":"energia-4.s3.p3","orden":3,"grupo":"energia-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Biomasa y biogás","cuerpo":["La biomasa es materia orgánica que se usa como energía: leña, restos de aserraderos, cáscaras de maní o de arroz, bagazo de caña. Se quema para generar calor o electricidad. Es renovable si lo que se usa vuelve a crecer y si no se desmontan bosques para obtenerla.","El biogás se produce cuando microbios descomponen residuos orgánicos sin oxígeno —estiércol, restos de alimentos, efluentes de industrias—, en equipos llamados biodigestores. Tiene metano, que se quema para generar energía. Así se evita que ese metano llegue a la atmósfera y se reemplaza gas fósil."]},"solucion":{}},{"slug":"energia-4.s3.p4","orden":4,"grupo":"energia-4.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un biodigestor en un tambo.","items":[{"id":"i1","texto":"Se junta el estiércol de las vacas"},{"id":"i2","texto":"Se carga en un biodigestor sin oxígeno"},{"id":"i3","texto":"Los microbios producen biogás con metano"},{"id":"i4","texto":"El biogás se quema para generar electricidad o calor"},{"id":"i5","texto":"Lo que queda se usa como fertilizante"},{"id":"i6","texto":"El biodigestor convierte el estiércol en nafta"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un residuo que era un problema se convierte en energía y abono, y se evita metano."}},{"slug":"energia-4.s3.p5","orden":5,"grupo":"energia-4.s3.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es biomasa o biogás?","grupos":[{"id":"g1","nombre":"Biomasa"},{"id":"g2","nombre":"Biogás"}],"items":[{"id":"i1","texto":"Cáscaras de maní quemadas en una caldera"},{"id":"i2","texto":"Gas de un biodigestor con estiércol"},{"id":"i3","texto":"Restos de un aserradero"},{"id":"i4","texto":"Gas captado en un relleno sanitario"},{"id":"i5","texto":"Bagazo de caña de azúcar"},{"id":"i6","texto":"Gas de efluentes de una industria láctea"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La biomasa se quema directamente; el biogás se produce primero con microbios."}},{"slug":"energia-4.s3.p6","orden":6,"grupo":"energia-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El calor de la Tierra","cuerpo":["La geotermia aprovecha el calor del interior de la Tierra. En zonas volcánicas, como Copahue en Neuquén, hay agua y vapor a alta temperatura que podrían mover turbinas. Y en cualquier lugar, a pocos metros de profundidad, el suelo tiene una temperatura bastante estable, que las bombas de calor geotérmicas usan para calefaccionar y refrescar."]},"solucion":{}},{"slug":"energia-4.s3.p7","orden":7,"grupo":"energia-4.s3.p7","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada fuente con un ejemplo argentino.","izquierda":[{"id":"a1","texto":"Geotermia"},{"id":"a2","texto":"Biogás"},{"id":"a3","texto":"Biomasa"},{"id":"a4","texto":"Pequeño aprovechamiento hidráulico"}],"derecha":[{"id":"b1","texto":"Copahue, en Neuquén"},{"id":"b2","texto":"Biodigestores en tambos"},{"id":"b3","texto":"Cáscaras de maní en Córdoba"},{"id":"b4","texto":"Minicentral en un canal de riego"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las \"otras renovables\" también tienen lugar en el país."}},{"slug":"energia-4.s3.p8","orden":8,"grupo":"energia-4.s3.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿En qué caso la biomasa NO sería sostenible?","opciones":[{"id":"o1","texto":"Si se desmonta bosque nativo para quemar la leña"},{"id":"o2","texto":"Si se usan restos de un aserradero"},{"id":"o3","texto":"Si se usan cáscaras que sobran de una industria"},{"id":"o4","texto":"Si se replanta lo que se cosecha"}]},"solucion":{"clave":["o1"],"explicacion":"Quemar bosque nativo libera carbono guardado por siglos y destruye biodiversidad.","por_opcion":{"o3":"Aprovechar un residuo que ya existe suele ser sostenible."}}},{"slug":"energia-4.s3.p9","orden":9,"grupo":"energia-4.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tambo con 200 vacas, el estiércol de cada vaca produce unos 1,5 m³ de biogás por día. ¿Cuántos m³ de biogás por día produce el tambo?","unidad":"m³","decimales":1},"solucion":{"valor":300,"tolerancia":6,"explicacion":"200 × 1,5 = 300 m³ por día de un combustible renovable que antes era un problema."}},{"slug":"energia-4.s3.p9.v2","orden":9,"grupo":"energia-4.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tambo con 500 vacas, el estiércol de cada vaca produce unos 1,2 m³ de biogás por día. ¿Cuántos m³ de biogás por día produce el tambo?","unidad":"m³","decimales":1},"solucion":{"valor":600,"tolerancia":12,"explicacion":"500 × 1,2 = 600 m³ por día de un combustible renovable que antes era un problema."}},{"slug":"energia-4.s3.p9.v3","orden":9,"grupo":"energia-4.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tambo con 100 vacas, el estiércol de cada vaca produce unos 1,8 m³ de biogás por día. ¿Cuántos m³ de biogás por día produce el tambo?","unidad":"m³","decimales":1},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"100 × 1,8 = 180 m³ por día de un combustible renovable que antes era un problema."}},{"slug":"energia-4.s3.p10","orden":10,"grupo":"energia-4.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios tiene el biogás de residuos? Marcá todos.","opciones":[{"id":"o1","texto":"Evita que el metano llegue a la atmósfera"},{"id":"o2","texto":"Reemplaza gas fósil"},{"id":"o3","texto":"Deja un fertilizante"},{"id":"o4","texto":"Reduce olores y contaminación de los residuos"},{"id":"o5","texto":"Aumenta el metano en el aire"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Energía, abono y menos contaminación en una sola tecnología."}},{"slug":"energia-4.s3.p11","orden":11,"grupo":"energia-4.s3.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Captar el biogás de un relleno sanitario y usarlo para generar electricidad evita que parte del metano llegue a la atmósfera.","razones":[{"id":"r1","texto":"Porque el metano se quema y se aprovecha en lugar de escaparse"},{"id":"r2","texto":"Porque los rellenos no producen metano"},{"id":"r3","texto":"Porque quemar metano produce más metano"}]},"solucion":{"valor":true,"explicacion":"El metano se quema y se convierte en CO₂, que calienta mucho menos, y además se aprovecha su energía.","clave":["r1"]}},{"slug":"energia-4.s3.p12","orden":12,"grupo":"energia-4.s3.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la ley argentina de promoción de renovables incluye solo los pequeños aprovechamientos hidráulicos?","opciones":[{"id":"o1","texto":"Porque las grandes represas tienen impactos mayores"},{"id":"o2","texto":"Porque las grandes represas no generan electricidad"},{"id":"o3","texto":"Porque el agua de los ríos grandes no es renovable"},{"id":"o4","texto":"Porque en Argentina no hay ríos grandes"}]},"solucion":{"clave":["o1"],"explicacion":"La ley busca promover fuentes con menos impacto; las grandes represas ya tienen su propio esquema.","por_opcion":{"o3":"El agua es renovable; lo que pesa son los impactos de las obras grandes."}}},{"slug":"energia-4.s3.p13","orden":13,"grupo":"energia-4.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El biogás se produce con microbios sin oxígeno."},{"id":"s2","texto":"Toda la biomasa es sostenible, venga de donde venga."},{"id":"s3","texto":"En Copahue hay recursos geotérmicos."},{"id":"s4","texto":"La geotermia solo existe en otros países."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las renovables también tienen condiciones para ser sostenibles.","por_opcion":{"s2":"No si se desmontan bosques nativos para obtenerla.","s4":"Argentina tiene recursos geotérmicos, como en Neuquén."}}},{"slug":"energia-4.s3.p14","orden":14,"grupo":"energia-4.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La materia orgánica que se usa como energía es {{0}}; el gas que se obtiene de residuos en un biodigestor es {{1}}; y el calor de la Tierra se aprovecha con la {{2}}.","banco":[{"id":"w1","texto":"biomasa"},{"id":"w2","texto":"biogás"},{"id":"w3","texto":"geotermia"},{"id":"w4","texto":"petróleo"},{"id":"w5","texto":"propano"},{"id":"w6","texto":"hidráulica"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres renovables menos conocidas, en una línea."}}]},{"slug":"energia-4.s4","orden":4,"tipo":"leccion","titulo_es":"Cuando no hay sol ni viento","bajada_es":"Variabilidad, complementariedad, almacenamiento y redes: cómo se sostiene un sistema con muchas renovables.","minutos":11,"pasos":[{"slug":"energia-4.s4.p1","orden":1,"grupo":"energia-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Variables, pero predecibles","cuerpo":["El sol y el viento varían: el sol no genera de noche y baja con nubes; el viento cambia de un día a otro. Pero son bastante predecibles con pronósticos, y se complementan: en muchos lugares el viento sopla más de noche o en invierno, cuando el sol rinde menos.","Un sistema eléctrico con muchas renovables combina varias herramientas: diversidad de fuentes y lugares, redes que las conecten, almacenamiento, centrales flexibles de respaldo y gestión de la demanda."]},"solucion":{}},{"slug":"energia-4.s4.p2","orden":2,"grupo":"energia-4.s4.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué herramientas ayudan a integrar mucha energía solar y eólica a la red? Marcá todas.","opciones":[{"id":"o1","texto":"Combinar fuentes y lugares distintos"},{"id":"o2","texto":"Redes que conecten regiones"},{"id":"o3","texto":"Almacenamiento en baterías o bombeo"},{"id":"o4","texto":"Mover consumos a las horas de más generación"},{"id":"o5","texto":"Apagar la red cuando no hay sol"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Diversidad, redes, almacenamiento y demanda flexible: las cuatro patas del sistema."}},{"slug":"energia-4.s4.p3","orden":3,"grupo":"energia-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Almacenar energía","cuerpo":["Las baterías guardan electricidad para usarla horas después: se cargan al mediodía con solar y se descargan a la noche. Las centrales hidroeléctricas de bombeo hacen algo parecido a gran escala: cuando sobra energía, bombean agua a un embalse alto; cuando falta, la dejan caer y generan. En Córdoba, el complejo Río Grande funciona así desde hace décadas."]},"solucion":{}},{"slug":"energia-4.s4.p4","orden":4,"grupo":"energia-4.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el ciclo de una central de bombeo.","items":[{"id":"i1","texto":"Sobra electricidad en la red, por ejemplo de noche"},{"id":"i2","texto":"Se usa para bombear agua a un embalse alto"},{"id":"i3","texto":"El agua queda guardada arriba"},{"id":"i4","texto":"Cuando falta electricidad, el agua baja por las turbinas"},{"id":"i5","texto":"Se genera electricidad en el momento de más demanda"},{"id":"i6","texto":"El agua sube sola al embalse de noche"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una \"batería de agua\": guarda energía como altura."}},{"slug":"energia-4.s4.p5","orden":5,"grupo":"energia-4.s4.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una central de bombeo produce más energía de la que usa para bombear.","razones":[{"id":"r1","texto":"Porque pierde una parte: su valor es mover energía en el tiempo"},{"id":"r2","texto":"Porque el agua genera energía de la nada"},{"id":"r3","texto":"Porque el bombeo no usa electricidad"}]},"solucion":{"valor":false,"explicacion":"Pierde una parte en el proceso: devuelve alrededor del 70 a 80 % de lo que usó. Su valor está en mover energía de cuando sobra a cuando falta.","clave":["r1"]}},{"slug":"energia-4.s4.p6","orden":6,"grupo":"energia-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central de bombeo usa 100 MWh para subir agua y devuelve el 75 % al generar. ¿Cuántos MWh devuelve?","unidad":"MWh","decimales":0},"solucion":{"valor":75,"tolerancia":1.5,"explicacion":"100 × 75 ÷ 100 = 75 MWh. Se pierden 25, pero se gana poder usar la energía cuando más se necesita."}},{"slug":"energia-4.s4.p6.v2","orden":6,"grupo":"energia-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central de bombeo usa 250 MWh para subir agua y devuelve el 80 % al generar. ¿Cuántos MWh devuelve?","unidad":"MWh","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"250 × 80 ÷ 100 = 200 MWh. Se pierden 50, pero se gana poder usar la energía cuando más se necesita."}},{"slug":"energia-4.s4.p6.v3","orden":6,"grupo":"energia-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central de bombeo usa 80 MWh para subir agua y devuelve el 70 % al generar. ¿Cuántos MWh devuelve?","unidad":"MWh","decimales":0},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"80 × 70 ÷ 100 = 56 MWh. Se pierden 24, pero se gana poder usar la energía cuando más se necesita."}},{"slug":"energia-4.s4.p7","orden":7,"grupo":"energia-4.s4.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta herramienta es almacenamiento, respaldo o gestión de la demanda?","grupos":[{"id":"g1","nombre":"Almacenamiento"},{"id":"g2","nombre":"Respaldo"},{"id":"g3","nombre":"Gestión de la demanda"}],"items":[{"id":"i1","texto":"Baterías junto a un parque solar"},{"id":"i2","texto":"Turbina de gas que se enciende rápido"},{"id":"i3","texto":"Cargar autos eléctricos al mediodía"},{"id":"i4","texto":"Central de bombeo"},{"id":"i5","texto":"Represa que regula cuánta agua turbina"},{"id":"i6","texto":"Tarifas más baratas cuando sobra viento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres formas distintas de equilibrar un sistema con mucho sol y viento."}},{"slug":"energia-4.s4.p8","orden":8,"grupo":"energia-4.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Redes que conectan","cuerpo":["Cuando hay viento en la Patagonia pero no en Buenos Aires, o sol en el norte pero nubes en el centro, una red bien interconectada permite llevar la energía de donde sobra a donde falta. Por eso ampliar las líneas de transmisión es clave para sumar renovables: en Argentina, la falta de capacidad de transmisión llegó a limitar la construcción de nuevos parques."]},"solucion":{}},{"slug":"energia-4.s4.p9","orden":9,"grupo":"energia-4.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la capacidad de las líneas de transmisión puede frenar nuevos parques eólicos?","opciones":[{"id":"o1","texto":"Porque sin líneas no se puede llevar su energía a las ciudades"},{"id":"o2","texto":"Porque las líneas generan viento en contra"},{"id":"o3","texto":"Porque los parques eólicos no se conectan a la red"},{"id":"o4","texto":"Porque las líneas solo transportan gas"}]},"solucion":{"clave":["o1"],"explicacion":"Generar donde hay viento sirve si se puede transportar la energía hasta donde se consume.","por_opcion":{"o3":"Sí se conectan; el problema es que las líneas existentes pueden estar al límite."}}},{"slug":"energia-4.s4.p10","orden":10,"grupo":"energia-4.s4.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con su solución.","izquierda":[{"id":"a1","texto":"No hay sol a la noche"},{"id":"a2","texto":"Una región sin viento hoy"},{"id":"a3","texto":"Pico de demanda de pocas horas"},{"id":"a4","texto":"Sobra energía al mediodía"}],"derecha":[{"id":"b1","texto":"Baterías cargadas al mediodía"},{"id":"b2","texto":"Energía de otra región por la red"},{"id":"b3","texto":"Central de respaldo que se enciende rápido"},{"id":"b4","texto":"Mover consumos flexibles a esa hora"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada desafío de la variabilidad tiene una o varias respuestas."}},{"slug":"energia-4.s4.p11","orden":11,"grupo":"energia-4.s4.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la energía usada para bombear devuelve una central de bombeo al generar.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"Alrededor del 70 al 80 %. Se pierde una parte, pero se gana poder usar la energía cuando más falta."}},{"slug":"energia-4.s4.p12","orden":12,"grupo":"energia-4.s4.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En muchos lugares, el viento y el sol se complementan: el viento suele soplar más de noche o en invierno, cuando el sol rinde menos.","razones":[{"id":"r1","texto":"Porque generan en momentos distintos y se compensan"},{"id":"r2","texto":"Porque el viento solo sopla al mediodía"},{"id":"r3","texto":"Porque sol y viento generan siempre a la vez"}]},"solucion":{"valor":true,"explicacion":"Combinar fuentes que generan en momentos distintos hace más estable el sistema.","clave":["r1"]}},{"slug":"energia-4.s4.p13","orden":13,"grupo":"energia-4.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El sol y el viento varían, pero se pueden pronosticar."},{"id":"s2","texto":"Como el sol no sale de noche, las renovables nunca podrán aportar mucho."},{"id":"s3","texto":"Las centrales de bombeo guardan energía como agua en altura."},{"id":"s4","texto":"Las baterías generan energía por sí mismas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La variabilidad es un desafío técnico con soluciones conocidas.","por_opcion":{"s2":"Con almacenamiento, redes, diversidad y demanda flexible, pueden aportar una parte muy grande.","s4":"Guardan energía generada antes; no la producen."}}},{"slug":"energia-4.s4.p14","orden":14,"grupo":"energia-4.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las centrales de {{0}} guardan energía como agua en altura; las {{1}} se cargan con sol al mediodía; y las líneas de {{2}} llevan energía de una región a otra.","banco":[{"id":"w1","texto":"bombeo"},{"id":"w2","texto":"baterías"},{"id":"w3","texto":"transmisión"},{"id":"w4","texto":"carbón"},{"id":"w5","texto":"turbinas"},{"id":"w6","texto":"agua"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres piezas para sostener un sistema con muchas renovables."}}]},{"slug":"energia-4.s5","orden":5,"tipo":"leccion","titulo_es":"Costos, beneficios e impactos","bajada_es":"Por qué las renovables se volvieron tan baratas, qué empleos generan y qué impactos locales hay que cuidar.","minutos":11,"pasos":[{"slug":"energia-4.s5.p1","orden":1,"grupo":"energia-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una caída de costos histórica","cuerpo":["Según IRENA, la agencia internacional de energías renovables, entre 2010 y 2023 el costo de generar electricidad con paneles solares a gran escala cayó alrededor de un 90 % en promedio en el mundo, y el de la eólica en tierra, alrededor de un 70 %. Hoy, en muchos lugares, construir solar o eólica nueva es más barato que construir centrales fósiles nuevas.","La razón principal es la curva de aprendizaje: cada vez que se duplica la cantidad instalada, la tecnología mejora y se abarata."],"destacado":{"valor":"≈ 90 %","texto":"bajó el costo de la electricidad solar a gran escala entre 2010 y 2023, según IRENA."}},"solucion":{}},{"slug":"energia-4.s5.p2","orden":2,"grupo":"energia-4.s5.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuánto bajó el costo de la electricidad solar a gran escala entre 2010 y 2023, según IRENA.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":90,"banda":"lineal","explicacion":"Alrededor del 90 %. Una de las caídas de costos más rápidas de la historia de la energía."}},{"slug":"energia-4.s5.p3","orden":3,"grupo":"energia-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si generar un kWh solar costaba 0,46 dólares y el costo bajó un 90 %, ¿cuánto cuesta ahora? Redondeá a tres decimales.","unidad":"dólares por kWh","decimales":3},"solucion":{"valor":0.046,"tolerancia":0.002,"explicacion":"0,46 × 0,1 ≈ 0,046 dólares por kWh: una fracción de lo que costaba."}},{"slug":"energia-4.s5.p3.v2","orden":3,"grupo":"energia-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si generar un kWh solar costaba 0,4 dólares y el costo bajó un 85 %, ¿cuánto cuesta ahora? Redondeá a tres decimales.","unidad":"dólares por kWh","decimales":3},"solucion":{"valor":0.06,"tolerancia":0.002,"explicacion":"0,4 × 0,15 ≈ 0,06 dólares por kWh: una fracción de lo que costaba."}},{"slug":"energia-4.s5.p3.v3","orden":3,"grupo":"energia-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si generar un kWh solar costaba 0,5 dólares y el costo bajó un 88 %, ¿cuánto cuesta ahora? Redondeá a tres decimales.","unidad":"dólares por kWh","decimales":3},"solucion":{"valor":0.06,"tolerancia":0.002,"explicacion":"0,5 × 0,12 ≈ 0,06 dólares por kWh: una fracción de lo que costaba."}},{"slug":"energia-4.s5.p4","orden":4,"grupo":"energia-4.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la curva de aprendizaje.","items":[{"id":"i1","texto":"Se instalan más paneles en el mundo"},{"id":"i2","texto":"Las fábricas producen a mayor escala"},{"id":"i3","texto":"Mejoran la tecnología y los procesos"},{"id":"i4","texto":"Baja el costo de cada panel"},{"id":"i5","texto":"Se instalan todavía más paneles"},{"id":"i6","texto":"Cuantos más paneles se fabrican, más caros se vuelven"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un círculo virtuoso que explica por qué las renovables se abarataron tanto."}},{"slug":"energia-4.s5.p5","orden":5,"grupo":"energia-4.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Impactos locales","cuerpo":["Las renovables también tienen impactos que hay que evaluar y reducir: los parques eólicos pueden afectar a aves y murciélagos, sobre todo si se ubican en rutas migratorias; los grandes parques solares ocupan superficie y pueden afectar ambientes frágiles; las represas cortan ríos; y la fabricación de paneles, turbinas y baterías usa minerales cuya extracción tiene impactos, como verás en la rama Digital.","Por eso los proyectos renovables también pasan por evaluación de impacto ambiental, y se eligen ubicaciones y diseños que reduzcan esos efectos."]},"solucion":{}},{"slug":"energia-4.s5.p6","orden":6,"grupo":"energia-4.s5.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada fuente con un impacto a cuidar.","izquierda":[{"id":"a1","texto":"Eólica"},{"id":"a2","texto":"Solar a gran escala"},{"id":"a3","texto":"Gran hidráulica"},{"id":"a4","texto":"Baterías"}],"derecha":[{"id":"b1","texto":"Aves y murciélagos en rutas migratorias"},{"id":"b2","texto":"Ocupación de superficie en ambientes frágiles"},{"id":"b3","texto":"Ríos cortados y peces migradores"},{"id":"b4","texto":"Extracción de minerales como el litio"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Ninguna fuente es impacto cero. Lo importante es comparar y reducir."}},{"slug":"energia-4.s5.p7","orden":7,"grupo":"energia-4.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como las renovables no emiten CO₂ al generar, no necesitan evaluación de impacto ambiental.","razones":[{"id":"r1","texto":"Porque tienen otros impactos que hay que evaluar"},{"id":"r2","texto":"Porque la ley prohíbe evaluarlas"},{"id":"r3","texto":"Porque no ocupan ningún espacio"}]},"solucion":{"valor":false,"explicacion":"Tienen otros impactos —sobre fauna, suelo, agua y paisaje— que hay que evaluar y reducir antes de construir.","clave":["r1"]}},{"slug":"energia-4.s5.p8","orden":8,"grupo":"energia-4.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Beneficios más allá del clima","cuerpo":["Además de bajar emisiones, las renovables mejoran la calidad del aire (menos combustión), reducen la dependencia de importar combustibles, generan empleo en instalación y mantenimiento, y pueden llevar energía a lugares aislados, como escuelas rurales con paneles solares.","Cuando las comunidades locales participan y se benefician —con empleo, energía más barata o participación en los proyectos—, los proyectos suelen tener más apoyo."]},"solucion":{}},{"slug":"energia-4.s5.p9","orden":9,"grupo":"energia-4.s5.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios pueden traer las renovables? Marcá todos.","opciones":[{"id":"o1","texto":"Aire más limpio"},{"id":"o2","texto":"Menos importación de combustibles"},{"id":"o3","texto":"Empleo local"},{"id":"o4","texto":"Energía para lugares aislados"},{"id":"o5","texto":"Cero impactos de ningún tipo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchos beneficios, sin olvidar que también tienen impactos a cuidar."}},{"slug":"energia-4.s5.p10","orden":10,"grupo":"energia-4.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión reduce el impacto de un proyecto renovable o lo aumenta?","grupos":[{"id":"g1","nombre":"Lo reduce"},{"id":"g2","nombre":"Lo aumenta"}],"items":[{"id":"i1","texto":"Ubicar el parque eólico lejos de rutas migratorias"},{"id":"i2","texto":"Desmontar bosque nativo para un parque solar"},{"id":"i3","texto":"Instalar paneles sobre techos y estacionamientos"},{"id":"i4","texto":"Instalar aerogeneradores en un corredor de aves"},{"id":"i5","texto":"Detener turbinas en momentos de paso de aves"},{"id":"i6","texto":"No consultar a las comunidades cercanas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Dónde y cómo se construye decide gran parte del impacto."}},{"slug":"energia-4.s5.p11","orden":11,"grupo":"energia-4.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para instalar paneles solares en una ciudad, ¿qué lugar suele tener menor impacto?","opciones":[{"id":"o1","texto":"Techos y playas de estacionamiento"},{"id":"o2","texto":"Una plaza con árboles nativos"},{"id":"o3","texto":"Un humedal urbano"},{"id":"o4","texto":"Un parque público con césped"}]},"solucion":{"clave":["o1"],"explicacion":"Los techos y estacionamientos ya son superficies construidas: aprovecharlos no quita espacio verde.","por_opcion":{"o3":"Rellenar o cubrir un humedal destruye un ecosistema valioso."}}},{"slug":"energia-4.s5.p12","orden":12,"grupo":"energia-4.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La solar y la eólica se abarataron mucho en la última década."},{"id":"s2","texto":"Por eso ya no hace falta evaluar sus impactos."},{"id":"s3","texto":"Las renovables pueden llevar energía a escuelas rurales aisladas."},{"id":"s4","texto":"La curva de aprendizaje hace que las tecnologías se encarezcan con el tiempo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Beneficios grandes, impactos que se pueden reducir.","por_opcion":{"s2":"Siguen necesitando evaluación: tienen impactos locales.","s4":"Al revés: al instalarse más, se abaratan."}}},{"slug":"energia-4.s5.p13","orden":13,"grupo":"energia-4.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Según IRENA, el costo de la solar a gran escala bajó cerca del {{0}} %; esa baja se explica por la curva de {{1}}.","banco":[{"id":"w1","texto":"90"},{"id":"w2","texto":"aprendizaje"},{"id":"w3","texto":"10"},{"id":"w4","texto":"demanda"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La historia económica de las renovables, en una línea."}}]},{"slug":"energia-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: energías renovables","bajada_es":"Sol, viento, otras renovables, almacenamiento y costos, mezclados.","minutos":8,"pasos":[{"slug":"energia-4.s6.p1","orden":1,"grupo":"energia-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Energías renovables». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el techo solar de la escuela","bajada_es":"Una escuela de Córdoba quiere instalar paneles solares. Con los números, evaluá el proyecto.","minutos":10,"pasos":[{"slug":"energia-4.s7.p1","orden":1,"grupo":"energia-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El proyecto","cuerpo":["La escuela consume 12.000 kWh de electricidad por año, casi todo de día. Tiene un techo que mira al norte, sin sombras, donde entran paneles por 8 kW. En su zona, el sol equivale a unas 5 horas de sol pleno por día en promedio, y el sistema pierde un 15 % entre cables, inversor y suciedad.","Con la ley de generación distribuida, lo que no consume puede volcarlo a la red. El factor de emisión de la red es de 0,35 kg de CO₂ por kWh."]},"solucion":{}},{"slug":"energia-4.s7.p2","orden":2,"grupo":"energia-4.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por año generarían los paneles antes de las pérdidas? (8 kW × 5 h × 365)","unidad":"kWh","decimales":0,"contexto":"8 kW de paneles; 5 horas de sol pleno por día."},"solucion":{"valor":14600,"tolerancia":292,"explicacion":"8 × 5 × 365 = 14.600 kWh por año antes de descontar pérdidas."}},{"slug":"energia-4.s7.p3","orden":3,"grupo":"energia-4.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con un 15 % de pérdidas, ¿cuántos kWh por año generarían?","unidad":"kWh","decimales":0,"contexto":"14.600 kWh antes de pérdidas; 15 % de pérdidas."},"solucion":{"valor":12410,"tolerancia":248.20000000000002,"explicacion":"14.600 × 0,85 = 12.410 kWh: un poco más de lo que consume la escuela en un año."}},{"slug":"energia-4.s7.p4","orden":4,"grupo":"energia-4.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂ por año se evitarían con esa generación? (0,35 kg por kWh) Redondeá al entero.","unidad":"kg de CO₂","decimales":0,"contexto":"12.410 kWh por año; 0,35 kg de CO₂ por kWh."},"solucion":{"valor":4344,"tolerancia":5,"explicacion":"12.410 × 0,35 ≈ 4.344 kg de CO₂ por año: más de 4 toneladas."}},{"slug":"energia-4.s7.p5","orden":5,"grupo":"energia-4.s7.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Como la escuela casi no consume en vacaciones, ¿qué pasa con la energía de enero?","opciones":[{"id":"o1","texto":"Se vuelca a la red y se compensa"},{"id":"o2","texto":"Se pierde sin que nadie la use"},{"id":"o3","texto":"Los paneles se apagan solos en vacaciones"},{"id":"o4","texto":"Se guarda en los cables hasta marzo"}]},"solucion":{"clave":["o1"],"explicacion":"La generación distribuida permite aprovechar los excedentes: otras casas los consumen.","por_opcion":{"o3":"Siguen generando: la ley permite volcar el excedente a la red."}}},{"slug":"energia-4.s7.p6","orden":6,"grupo":"energia-4.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene revisar antes de instalar? Marcá todo.","opciones":[{"id":"o1","texto":"Que el techo resista el peso de los paneles"},{"id":"o2","texto":"Que no haya sombras a lo largo del año"},{"id":"o3","texto":"Los trámites de conexión con la distribuidora"},{"id":"o4","texto":"Quién se encarga de la limpieza y el mantenimiento"},{"id":"o5","texto":"Que los paneles miren al sur"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Estructura, sombras, trámites y mantenimiento: lo que asegura que el proyecto funcione años."}},{"slug":"energia-4.s7.p7","orden":7,"grupo":"energia-4.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los argumentos que aparecen en la reunión de padres.","grupos":[{"id":"g1","nombre":"Con fundamento"},{"id":"g2","nombre":"Sin fundamento"}],"items":[{"id":"i1","texto":"La escuela consume sobre todo de día, cuando hay sol"},{"id":"i2","texto":"En invierno los paneles no generan nada"},{"id":"i3","texto":"Evitaría más de 4 toneladas de CO₂ por año"},{"id":"i4","texto":"Los paneles funcionan mejor mirando al sur"},{"id":"i5","texto":"Los chicos pueden aprender con los datos de generación"},{"id":"i6","texto":"Si hay un día nublado, se rompen"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Decidir con datos concretos y sin mitos sobre los paneles."}},{"slug":"energia-4.s7.p8","orden":8,"grupo":"energia-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La escuela escribe el proyecto. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Instalaremos 8 kW en el techo que mira al norte."},{"id":"s2","texto":"Plantaremos árboles altos delante de los paneles para que se vean lindos."},{"id":"s3","texto":"Mostraremos en un pi